const ASSETS={"npc-portraits.png": "data:image/png;base64,", "boys-layers.png": "data:image/png;base64,", "meishan-ranch.png": "data:image/webp;base64,", "meishan-pond.png": "data:image/webp;base64,", "meishan-day.png": "data:image/webp;base64,", "meishan-map.png": "data:image/webp;base64,", "meishan-title.png": "data:image/webp;base64,", "dolls.png": "data:image/png;base64,", "girls-layers.png": "data:image/png;base64,", "meishan-night.png": "data:image/webp;base64,", "room17.png": "data:image/webp;base64,", "carpenter17.png": "data:image/webp;base64,", "furniture17.png": "data:image/webp;base64,", "furniture-extra17.png": "data:image/webp;base64,", "furniture-decor17.png": "data:image/webp;base64,", "furniture18.webp": "data:image/webp;base64,", "decor18.webp": "data:image/webp;base64,"};
for(const n of ['courtyard.png','courtyard-v2.png','courtyard-v3.png'])ASSETS[n]=ASSETS['meishan-day.png'];
for(const [n,v] of Object.entries(ASSETS))document.documentElement.style.setProperty('--asset-'+n.replace('.','-'),'url("'+v+'")');
const KEY='lixi-cottage-v1';
const crops={greens:{name:'青菜',icon:'🥬',days:1,price:3},radish:{name:'萝卜',icon:'🥕',days:2,price:4},beans:{name:'黄豆',icon:'🌱',days:2,price:4}};
const names={rice:'大米',flour:'面粉',greens:'青菜',radish:'萝卜',beans:'黄豆',porridge:'清粥',pancake:'青菜饼',radishcake:'萝卜饼',soymilk:'热豆浆'};
const recipes={soymilk:{name:'热豆浆',icon:'🥛',needs:{beans:1},price:10},porridge:{name:'清粥',icon:'🥣',needs:{rice:1},price:7},pancake:{name:'青菜饼',icon:'🥞',needs:{greens:1,flour:1},price:12},radishcake:{name:'萝卜饼',icon:'🍘',needs:{radish:1,flour:1},price:15}};
const people=[{name:'桂婆婆',icon:'👵',role:'总惦记你吃没吃饱',line:'小院借你住，地也交你照看。别急着挣钱，先把第一锅粥熬香。'},{name:'阿禾',icon:'👩🏻',role:'带着种子，也带着好奇',line:'种子最认认真照看它的人。记得浇一次水，明早再看看！'},{name:'周木匠',icon:'🧑🏻',role:'想要一份软一点的饼',line:'这张桌子还能用。等你的小铺热闹起来，我来帮你把招牌挂正。'}];
function initial(){return {version:1,day:1,money:24,rep:0,harvests:0,sold:0,chapter:0,inv:{rice:4,flour:3,greens:0,radish:0,beans:0,porridge:0,pancake:0,radishcake:0,soymilk:0},seeds:{greens:3,radish:2,beans:1},plots:Array.from({length:4},()=>null),talked:{},orders:[],patted:0,log:['雨停后，你在栗溪村的一间旧屋醒来。桂婆婆把小院和菜地借给了你。']}}
let s=initial();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.version===1&&saved.inv&&saved.plots?.length===4){s=saved;s.inv={...initial().inv,...s.inv};}}catch{}
let tab='farm',timer;const $=q=>document.querySelector(q);
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));$('#saveStatus').textContent='已自动保存 · 当前浏览器'}catch{$('#saveStatus').textContent='无法存档，请勿关闭网页'}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function modal(t,body){$('#modalBody').innerHTML=`<h2>${t}</h2>${body}`;const d=$('#modal');if(!d.open){if(typeof d.showModal==='function')d.showModal();else{d.setAttribute('open','');d.classList.add('dialog-fallback')}}d.scrollTop=0}
function closeModal(){const d=$('#modal');if(typeof d.close==='function')d.close();else d.removeAttribute('open');d.classList.remove('dialog-fallback')}
function commit(t){render();save();if(t)toast(t)}
function ready(p){return p&&p.growth>=crops[p.crop].days}
function selectTab(t){tab=t;render();$('#tabs').scrollIntoView({behavior:'smooth',block:'nearest'})}
function render(){const stat=[['☀','山间日历',`第 ${s.day} 天`,'初秋'],['◉','小小钱袋',s.money,'铜钱'],['♡','邻里心意',s.rep,'点'],['♨','热饭送出',s.sold,'份']];$('#stats').innerHTML=stat.map(x=>`<div class="stat"><span class="stat-symbol">${x[0]}</span><div><small>${x[1]}</small><strong>${x[2]}</strong><em>${x[3]}</em></div></div>`).join('');$('#weather').textContent=s.day%3===0?'☂ 山间小雨':'☀ 微风 · 晴';const chapter=['第一章 · 第一缕炊烟','第二章 · 山外的消息','第三章 · 把灶火留下'][s.chapter];$('#chapterTitle').textContent=chapter;$('#chapterText').textContent=['旧屋已经收拾妥当。先种一畦菜，再给路过的人煮一碗热粥吧。','来客提到一个陌生的地名——立煌。你开始留意这座山村的往事。','你终于明白了所处的年代。继续经营小院，也为赶路的人留一盏灯。'][s.chapter];let q=s.chapter===0?`收获 ${Math.min(s.harvests,1)}/1 次 · 送出 ${Math.min(s.sold,3)}/3 份早餐`:s.chapter===1?`第 ${Math.min(s.day,5)}/5 天 · 送出 ${Math.min(s.sold,6)}/6 份早餐`:'故事已展开 · 小院可以一直经营';$('#quest').innerHTML=`<div class="quest"><strong>今日的小小盼头</strong>${q}</div>`;$('#npcs').innerHTML=people.map((p,i)=>`<div class="npc"><div class="avatar">${p.icon}</div><div class="npc-name">${p.name}<small>${p.role}</small></div><button onclick="talk(${i})">聊聊</button></div>`).join('');$('#tabs').innerHTML=[['farm','❀ 菜地'],['kitchen','♨ 灶台'],['orders','☷ 订单'],['shop','♧ 集市']].map(([id,n])=>`<button class="${tab===id?'active':''}" onclick="selectTab('${id}')">${n}</button>`).join('');renderPanel()}
function heading(title,desc,tag){return `<div class="panel-heading"><div><h3>${title}</h3><p>${desc}</p></div><span class="tag">${tag}</span></div>`}
function inventory(){return `<div class="inventory">${Object.entries(s.inv).filter(([k,v])=>v>0).map(([k,v])=>`<span>${names[k]} × ${v}</span>`).join('')||'<span>行囊空空，去集市看看吧</span>'}</div>`}
function renderPanel(){let html='';if(tab==='farm'){html=heading('门前四畦，慢慢长大','播种 → 浇一次水 → 结束今日 → 收获。雨天自动浇水。','不枯萎 · 无需守候')+`<div class="grid">`+s.plots.map((p,i)=>`<button class="plot ${ready(p)?'ready':''}" onclick="plot(${i})"><span class="plot-no">0${i+1} 号田</span><span class="plant">${p?(ready(p)?crops[p.crop].icon:'🌱'):'﹢'}</span><strong>${p?crops[p.crop].name:'空着的小菜地'}</strong><small>${p?(ready(p)?'成熟啦 · 点击收获':p.watered?'已浇水 · 明天会长大':'有点渴了 · 点击浇水'):'点击挑一包种子'}</small>${p?`<div class="progress"><i style="width:${p.growth/crops[p.crop].days*100}%"></i></div>`:''}</button>`).join('')+'</div>'}
if(tab==='kitchen'){html=heading('热气腾腾，刚刚好','做好的早餐放进行囊，去「订单」交给客人。','每次制作 1 份')+'<div class="grid">'+Object.entries(recipes).map(([k,r])=>`<div class="recipe"><span class="food">${r.icon}</span><h3>${r.name}</h3><small>${Object.entries(r.needs).map(([n,v])=>`${names[n]} ${s.inv[n]}/${v}`).join(' · ')}</small><button onclick="cook('${k}')" ${canCook(k)?'':'disabled'}>制作一份</button></div>`).join('')+'</div>'+inventory()}
if(tab==='orders'){const list=dailyOrders();html=heading('一份早饭，一个故事','每日三位来客；已做好的早餐才能交付。','完成订单获得铜钱')+'<div class="grid">'+list.map((o,i)=>`<div class="order"><small>${o.who}</small><h3>${recipes[o.food].icon} ${recipes[o.food].name} × 1</h3><small>${o.line}</small><p>◉ ${recipes[o.food].price} 铜钱 · ♡ 1 心意</p><button onclick="serve(${i})" ${s.orders.includes(i)||!s.inv[o.food]?'disabled':''}>${s.orders.includes(i)?'已送到 · 谢谢你':s.inv[o.food]?'送上热饭':'去灶台准备'}</button></div>`).join('')+'</div>'+inventory()}
if(tab==='shop'){html=heading('阿禾的山间小摊','买种子、补食材。钱不够时可帮忙整理摊位。','种子 & 食材')+Object.entries(crops).map(([k,c])=>`<div class="shop-item"><div>${c.icon} ${c.name}种子 <small>已有 ${s.seeds[k]} 包 · ${c.days} 个生长日成熟 · 收获 3 份</small></div><button onclick="buy('${k}',true)" ${s.money<c.price?'disabled':''}>${c.price} 铜钱 / 包</button></div>`).join('')+['rice','flour'].map(k=>`<div class="shop-item"><div>${names[k]}<small>行囊里还有 ${s.inv[k]} 份</small></div><button onclick="buy('${k}',false)" ${s.money<2?'disabled':''}>2 铜钱 / 份</button></div>`).join('')+`<div class="shop-item"><div>帮阿禾整理摊位<small>每日一次，获得 5 铜钱；任何时候都能重新起步。</small></div><button onclick="helpShop()" ${s.helped===s.day?'disabled':''}>${s.helped===s.day?'今日已帮忙':'搭把手'}</button></div>`}$('#panel').innerHTML=html}
function plot(i){const p=s.plots[i];if(!p){modal('给这畦地种点什么？',Object.entries(crops).map(([k,c])=>`<div class="shop-item"><div>${c.icon} ${c.name}<small>种子 ${s.seeds[k]} 包 · ${c.days} 个生长日成熟</small></div><button onclick="plant(${i},'${k}')" ${s.seeds[k]?'':'disabled'}>播种</button></div>`).join('')+'<p>种子不够？在集市可以买到。</p>');return}if(ready(p)){s.inv[p.crop]+=3;s.seeds[p.crop]+=1;s.harvests++;s.plots[i]=null;commit('收获 3 份'+crops[p.crop].name+'，并留下 1 包种子');checkChapter()}else if(p.watered)toast('已经浇过水啦，结束今日就会生长。');else{p.watered=true;commit('水浇好了，等明天的小惊喜。')}}
function plant(i,k){if(s.plots[i]||s.seeds[k]<1)return;s.seeds[k]--;s.plots[i]={crop:k,growth:0,watered:s.day%3===0};closeModal();commit('种下'+crops[k].name+'，记得浇水哦。')}
function canCook(k){return Object.entries(recipes[k].needs).every(([n,v])=>s.inv[n]>=v)}
function cook(k){if(!canCook(k))return;for(const[n,v]of Object.entries(recipes[k].needs))s.inv[n]-=v;s.inv[k]++;commit('做好了一份'+recipes[k].name+'，去看看订单吧。')}
function dailyOrders(){return [{who:'桂婆婆',food:'porridge',line:'「热乎一点，慢慢喝。」'},{who:s.day<3?'路过的村民':'赶路的客人',food:s.day%4===0?'soymilk':'porridge',line:'「一份热乎的就很好。」'},{who:'周木匠',food:s.day%2===0?'radishcake':'pancake',line:'「想给家里人带一份。」'}]}
function serve(i){const o=dailyOrders()[i];if(!o||s.orders.includes(i)||!s.inv[o.food])return;s.inv[o.food]--;s.money+=recipes[o.food].price;s.rep++;s.sold++;s.orders.push(i);commit('热饭送到了，获得 '+recipes[o.food].price+' 铜钱。');checkChapter()}
function buy(k,seed){const cost=seed?crops[k].price:2;if(s.money<cost)return;s.money-=cost;if(seed)s.seeds[k]++;else s.inv[k]++;commit('放进行囊啦。')}
function helpShop(){if(s.helped===s.day)return;s.helped=s.day;s.money+=5;commit('摊位收拾好了，阿禾给了你 5 铜钱。')}
function nextDay(){const thirsty=s.plots.filter(p=>p&&!ready(p)&&!p.watered).length;modal('今天，也辛苦啦。',`<p>今天送出了 ${s.orders.length} 份早餐。明天会有新客人来，也许还有长大的菜。</p>${thirsty?`<p>还有 ${thirsty} 块菜地没浇水，今晚不会生长。可以先回去照料。</p>`:''}<p>食材与早餐都会保留，不会过期。日期只在你点击时推进。</p><button class="primary" onclick="advanceDay()">收好小院，迎接明天 →</button>`)}
function advanceDay(){s.plots.forEach(p=>{if(p&&!ready(p)&&p.watered)p.growth++});s.day++;s.orders=[];s.plots.forEach(p=>{if(p)p.watered=s.day%3===0});closeModal();commit(s.day%3===0?'下雨了，菜地已经自动浇好水。':'新的一天，灶火等着你。');checkChapter()}
function talk(i){const p=people[i];const key=s.day+'-'+i;if(!s.talked[key]){s.talked[key]=true;s.rep++;save();render()}let text=p.line;if(s.chapter===1&&i===0)text='山外有人说立煌那边有了新消息。你问这里是哪一年？这孩子，莫不是被那场雨淋糊涂了。';if(s.chapter===2&&i===2)text='山路上有人继续赶路，村里也要好好过日子。你的这口灶，能暖不少人的心。';modal(p.icon+' '+p.name,`<p>“${text}”</p><p class="story-note">每日首次交谈，邻里心意 +1。</p><button class="primary" onclick="closeModal()">记在心里 ♡</button>`)}
function petDog(){if(s.patted!==s.day){s.patted=s.day;s.rep++;commit('阿黄把脑袋靠过来。邻里心意 +1 ♡')}else toast('阿黄翻了个身，继续晒太阳。')}
function checkChapter(){if(s.chapter===0&&s.harvests>=1&&s.sold>=3){s.chapter=1;s.log.push('客人提起“立煌”。为什么不是你熟悉的金寨？旧照片上的屋檐，和这里一模一样。');commit();showStory()}else if(s.chapter===1&&s.day>=5&&s.sold>=6){s.chapter=2;s.log.push('林先生带来山外的消息：刘伯承、邓小平率领的部队已经挺进大别山。你才意识到，这是1947年。眼前经过的是人民解放军。原来，那张旧照片里也有自己留下的灶火。');commit();showStory()}}
function showStory(){modal('旧照片里的炊烟',s.log.map((t,i)=>`<p><strong>0${i+1}</strong> · ${t}</p>`).join('')+`<p class="story-note">故事以金寨及1947年刘邓大军挺进大别山为背景；栗溪村、人物与小院订单均为虚构。试玩版压缩了作物生长时间。</p><button class="primary" onclick="closeModal()">回到我的小院 →</button>`)}
function showHelp(){modal('在小院，慢慢来',`<p>① 菜地：播种后再点一次浇水。</p><p>② 灶台：用初始的大米煮粥。</p><p>③ 订单：送出早餐，获得铜钱。</p><p>④ 结束今日：浇过水的菜会生长，订单刷新。</p><p>集市可以买食材，或帮忙挣 5 铜钱。成熟作物收获 3 份并留种 1 包。</p><p>完成收获与早餐订单后，故事自然展开。没有现实倒计时，没有离线惩罚。</p><p class="story-note">进度仅保存在当前浏览器；换设备、清除浏览器数据可能丢失。</p><button class="primary" onclick="closeModal()">知道啦，去种菜 →</button>`)}
function settings(){modal('小院设置',`<p>你的进度自动保存在当前浏览器。可以导出存档，留一份备份。</p><button class="primary" onclick="exportSave()">导出存档</button><p><label>恢复存档 <input type="file" accept="application/json,.json" onchange="importSave(this.files[0])"></label></p><hr><p>重新开始会清空当前小院进度。</p><button class="secondary" onclick="confirmReset()">重新开始</button>`)}
function exportSave(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));a.download='lixi-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function validState(x){const num=v=>Number.isSafeInteger(v)&&v>=0&&v<1000000;return x&&x.version===1&&num(x.day)&&x.day>=1&&num(x.money)&&num(x.rep)&&num(x.sold)&&num(x.harvests)&&[0,1,2,3,4,5].includes(x.chapter)&&Object.keys(initial().inv).every(k=>num(x.inv?.[k]))&&Object.keys(crops).every(k=>num(x.seeds?.[k]))&&Array.isArray(x.plots)&&x.plots.length===4&&x.plots.every(p=>p===null||(p&&Object.hasOwn(crops,p.crop)&&num(p.growth)&&typeof p.watered==='boolean'))&&Array.isArray(x.orders)&&x.orders.every(v=>[0,1,2].includes(v))&&Array.isArray(x.log)&&x.log.every(v=>typeof v==='string')&&x.talked&&typeof x.talked==='object'}
async function importSave(file){if(!file)return;try{const x=JSON.parse(await file.text());if(!validState(x))throw Error();x.log=x.log.map(t=>t.replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c])));s=x;closeModal();commit('存档已恢复。')}catch{toast('这个存档无法读取，当前进度没有改变。')}}
function confirmReset(){modal('真的要重新开始吗？','<p>目前的小院进度会被清空，建议先导出存档。</p><button class="primary" onclick="resetGame()">确认重新开始</button>')}
function resetGame(){s=initial();tab='farm';closeModal();commit('新的小院故事开始了。');showStory()}
async function sourceView(){modal('这间小院的代码','<p>使用原生 HTML、CSS 与 JavaScript，无需框架。选择文件即可查看完整源码。</p><div class="inventory"><button class="secondary" onclick="loadSource(\'index.html\')">页面 HTML</button><button class="secondary" onclick="loadSource(\'style.css\')">样式 CSS</button><button class="secondary" onclick="loadSource(\'app.js\')">游戏逻辑 JS</button></div><pre class="source" id="sourceText">选择一个文件查看</pre>')}
async function loadSource(file){try{const r=await fetch(file);if(!r.ok)throw Error();$('#sourceText').textContent=await r.text()}catch{$('#sourceText').textContent='暂时无法读取，请稍后再试。'}}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});

const routes={home:['⌂','小院','山有归处，灶有余温','HOME'],farm:['❀','农田','把日子种进泥土里','GARDEN'],kitchen:['♨','食铺','今日也有热饭香','KITCHEN'],shop:['♧','集市','把山间好物带回家','MARKET'],neighbors:['♡','村民','有人惦记，就是家','NEIGHBORS'],journal:['▤','手记','日子一页页，故事慢慢写','JOURNAL']};
let page='home',sub='cook';const oldPanel=renderPanel,oldPlot=plot,oldServe=serve,oldTalk=talk,oldReset=resetGame;
function extras(){s.upgrades??={farm:0,kitchen:0};s.claimed??=[];s.friends??=[0,0,0];s.friendDays??={};s.discovered??=[];s.earnings??=0;s.harvestedUnits??=0;s.inv={...initial().inv,...s.inv};}
function go(p){if(!routes[p]&&p!=='bag')p='home';if(location.hash.slice(1)===p){page=p;render()}else location.hash=p;window.scrollTo({top:0,behavior:'smooth'})}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';if(!routes[page]&&page!=='bag')page='home';render()});
selectTab=function(t){if(t==='orders'){sub='orders';go('kitchen')}else{if(t==='kitchen')sub='cook';go(t)}};
function routeHeader(kicker,title,desc,extra=''){return `<div class="page-heading"><div><small>${kicker}</small><h2>${title}</h2><p>${desc}</p></div>${extra}</div>`}
function chapterName(){return ['第一缕炊烟','山外的消息','把灶火留下'][s.chapter]}
function chapterGoal(){return s.chapter===0?`收获 ${Math.min(s.harvests,1)}/1 次 · 早餐 ${Math.min(s.sold,3)}/3 份`:s.chapter===1?`村居 ${Math.min(s.day,5)}/5 天 · 早餐 ${Math.min(s.sold,6)}/6 份`:'继续经营，书写属于你的小院日常'}
render=function(){extras();const r=routes[page]||['♧','行囊','收好每一份山间馈赠','BAG'];$('#breadcrumb').textContent=`栗溪村 / ${r[1]}`;$('#viewTitle').textContent=r[2];$('#navigation').innerHTML=Object.entries(routes).map(([k,v])=>`<a href="#${k}" class="${page===k?'selected':''}" ${page===k?'aria-current="page"':''}><span>${v[0]}</span><b>${v[1]}</b><small>›</small></a>`).join('');$('#stats').innerHTML=`<div><span class="sun">${s.day%3===0?'☂':'☀'}</span><b>初秋 · 第 ${s.day} 天</b><small>${s.day%3===0?'山间小雨':'晴 · 微风'}</small></div><div><span>◉</span><b>${s.money}</b><small>铜钱</small></div><div><span>♡</span><b>${s.rep}</b><small>心意</small></div><div><span>♨</span><b>${s.sold}</b><small>份热饭</small></div>`;if(page==='home')homeView();else if(['farm','kitchen','shop'].includes(page))workView();else if(page==='neighbors')friendsView();else if(page==='journal')journalView();else bagView()};
function homeView(){let mature=s.plots.filter(ready).length;$('#view').innerHTML=`<section class="village-scene"><img src="${ASSETS['courtyard-v3.png']}" alt="灯火温暖的金寨像素卡通小院，有农田、早餐铺、花树与小黄狗"><div class="scene-ribbon">✦ 栗溪村 · 我的归处</div><button class="world-label field-label" onclick="go('farm')"><span>❀</span><b>我的农田</b><small>${mature?mature+' 块可以收获':'种一点小小的盼头'} →</small></button><button class="world-label food-label" onclick="go('kitchen')"><span>♨</span><b>山坳小食铺</b><small>${s.orders.length}/3 位客人已招待 →</small></button><button class="world-label village-label" onclick="go('neighbors')"><b>村口走走</b><small>去见见老朋友 →</small></button><button class="dog-hit" onclick="petDog()" aria-label="摸摸阿黄">♡</button><div class="scene-title"><small>YOUR LITTLE CORNER OF THE WORLD</small><h2>人间烟火，山间日常。</h2></div></section><section class="home-bottom"><button class="story-teaser" onclick="go('journal')"><span class="teaser-icon">▤</span><div><small>当前故事 · 第 ${s.chapter+1} 章</small><h3>${chapterName()}</h3><p>${chapterGoal()}</p></div><span>↗</span></button><div class="daily-note"><small>今日的一点小事</small><p>${mature?'菜地里已经有成熟的蔬菜，去收下今天的惊喜吧。':s.day%3===0?'雨声轻轻落下来。菜地已经浇好了，安心去开店吧。':'灶台还温着。给桂婆婆煮碗粥，再去照看门前的菜。'}</p><button onclick="go('journal')">查看任务与奖励 →</button></div></section>`}
function workView(){let title,desc;if(page==='farm'){title='门前四畦';desc='播种、浇水、等待一个明天。收获时会自动留下一包种子。'}else if(page==='kitchen'){title='山坳小食铺';desc='从田里到碗里，每一份早餐都藏着一点心意。'}else{title='阿禾的山间小摊';desc='种子、米面、小院的新模样，都在这里等你。'}$('#view').innerHTML=`${routeHeader(routes[page][3],title,desc)}<div class="feature-banner ${page}"><div><small>${page==='farm'?'一蔬一饭，来自自己的土地':page==='kitchen'?'热气腾腾的小日子':'山间赶集，不慌不忙'}</small><h3>${page==='farm'?'种下去，就有了盼头。':page==='kitchen'?'今天想做点什么？':'把喜欢的日子带回家。'}</h3></div></div><div class="page-toolbar">${page==='kitchen'?`<div class="segmented"><button class="${sub==='cook'?'active':''}" onclick="sub='cook';render()">♨ 制作早餐</button><button class="${sub==='orders'?'active':''}" onclick="sub='orders';render()">☷ 今日订单 <i>${3-s.orders.length}</i></button></div>`:page==='farm'?`<span>农田等级 Lv.${s.upgrades.farm+1} · 每次收获 ${3+s.upgrades.farm} 份</span><button class="secondary" onclick="waterAll()">♧ 一键浇水</button>`:`<span>每日补给 · 无需等待真实时间</span><button class="secondary" onclick="go('bag')">查看行囊 →</button>`}</div><section class="page-panel" id="panel"></section>${page==='shop'?upgradeCards():''}`;tab=page==='kitchen'?(sub==='orders'?'orders':'kitchen'):page;oldPanel();if(page==='shop')$('#panel').innerHTML=$('#panel').innerHTML.replaceAll('收获 3 份','收获 '+(3+s.upgrades.farm)+' 份');if(page==='kitchen'&&sub==='orders')document.querySelectorAll('.order p').forEach((node,i)=>{node.textContent='◉ '+(recipes[dailyOrders()[i].food].price+s.upgrades.kitchen*2)+' 铜钱 · ♡ 1 心意'});if(page==='farm'){document.querySelectorAll('.plot').forEach((node,i)=>{let p=s.plots[i];node.insertAdjacentHTML('afterbegin',`<div class="soil-art ${p?'planted':''}">${p?Array.from({length:6},()=>`<span>${ready(p)?crops[p.crop].icon:'🌱'}</span>`).join(''):'<span class="empty-soil">＋</span>'}</div>`)});}}
function waterAll(){let n=0;s.plots.forEach(p=>{if(p&&!ready(p)&&!p.watered){p.watered=true;n++}});commit(n?`浇好了 ${n} 块菜地。`:'菜地都照料好了。')}
plot=function(i){const p=s.plots[i],harvesting=ready(p),k=p?.crop;oldPlot(i);if(harvesting){s.inv[k]+=s.upgrades.farm;s.harvestedUnits+=3+s.upgrades.farm;if(!s.discovered.includes(k))s.discovered.push(k);commit(`收获 ${3+s.upgrades.farm} 份${crops[k].name}，留种 1 包。`)}};
serve=function(i){const before=s.money;oldServe(i);if(s.money>before){const bonus=s.upgrades.kitchen*2;s.money+=bonus;s.earnings+=s.money-before;commit(bonus?`客人很喜欢！升级额外获得 ${bonus} 铜钱。`:undefined)}};
const rawCook=cook;cook=function(k){const before=s.inv[k];rawCook(k);if(s.inv[k]>before&&!s.discovered.includes(k)){s.discovered.push(k);save()}};
function upgradeCards(){return `<section class="upgrade-section"><h3>给小院添一点新模样</h3><div class="upgrade-grid">${[['farm','❀','改良菜地','每块菜地的收获量 +1'],['kitchen','♨','修缮食铺','每份早餐的收入 +2 铜钱']].map(([k,icon,title,desc])=>{const lv=s.upgrades[k],cost=40+lv*40;return `<article class="upgrade-card"><span>${icon}</span><div><small>Lv.${lv+1} / 3</small><h3>${title}</h3><p>${desc}</p></div><button class="primary" onclick="upgrade('${k}')" ${lv>=2||s.money<cost?'disabled':''}>${lv>=2?'已升至最高级':cost+' 铜钱 · 升级'}</button></article>`}).join('')}</div></section>`}
function upgrade(k){if(!['farm','kitchen'].includes(k))return;const lv=s.upgrades[k],cost=40+lv*40;if(lv>=2||s.money<cost)return;s.money-=cost;s.upgrades[k]++;commit('小院变得更好了！升级效果已生效。')}
function friendsView(){$('#view').innerHTML=routeHeader('NEIGHBORS','山间有故人','每天聊聊天，送一份亲手做的早餐。关系会慢慢长大。')+`<div class="friend-grid">${people.map((p,i)=>{const f=s.friends[i],gift=['porridge','pancake','radishcake'][i];return `<article class="friend-card"><div class="portrait portrait-${i}"><span>${p.icon}</span><small>栗溪村 · ${['守着老屋的人','照看种子的人','修补日常的人'][i]}</small></div><div class="friend-body"><small>${f>=8?'知心邻里':f>=3?'熟悉的朋友':'初识的邻居'}</small><h2>${p.name}</h2><p>${p.role}</p><div class="friend-hearts">${'♥'.repeat(Math.min(5,Math.floor(f/2)))+'♡'.repeat(5-Math.min(5,Math.floor(f/2)))}</div><p class="gift-tip">喜欢：${recipes[gift].name} · 已有 ${s.inv[gift]} 份</p><div class="friend-actions"><button class="primary" onclick="talk(${i})">聊一会儿</button><button class="secondary" onclick="gift(${i})" ${!s.inv[gift]||s.friendDays['gift'+i]===s.day?'disabled':''}>${s.friendDays['gift'+i]===s.day?'今天已送礼':'送一份早餐'}</button></div></div></article>`}).join('')}</div>`}
talk=function(i){const key='talk'+i;if(s.friendDays[key]!==s.day){s.friendDays[key]=s.day;s.friends[i]++}oldTalk(i);save()};
function gift(i){const k=['porridge','pancake','radishcake'][i];if(!s.inv[k]||s.friendDays['gift'+i]===s.day)return;s.inv[k]--;s.friendDays['gift'+i]=s.day;s.friends[i]+=2;s.rep+=2;commit(`${people[i].name}收下了早餐，亲近度 +2。`)}
const milestones=[{id:'firstharvest',title:'第一捧收获',desc:'完成一次作物收获',target:1,value:()=>s.harvests,reward:12},{id:'breakfast',title:'开门见喜',desc:'累计送出 3 份早餐',target:3,value:()=>s.sold,reward:20},{id:'neighbors',title:'山间有人家',desc:'与三位村民分别交谈',target:3,value:()=>[0,1,2].filter(i=>s.friendDays['talk'+i]!==undefined).length,reward:15},{id:'regular',title:'小店有回头客',desc:'累计送出 10 份早餐',target:10,value:()=>s.sold,reward:35},{id:'grow',title:'把小院照顾好',desc:'完成任意一次设施升级',target:1,value:()=>s.upgrades.farm+s.upgrades.kitchen,reward:20}];
function journalView(){$('#view').innerHTML=routeHeader('JOURNAL','山间手记','记住那些平凡又闪光的日子。已完成的任务，记得领取奖励。')+`<section class="journal-story"><div class="journal-art"><span>山间<br>旧事</span></div><div><small>第 ${s.chapter+1} 章 · 当前故事</small><h2>${chapterName()}</h2><p>${s.log[s.log.length-1]}</p><div class="chapter-goal">${chapterGoal()}</div><button class="secondary" onclick="showStory()">翻阅完整故事 →</button></div></section><h3 class="block-title">小院成长任务</h3><div class="mission-list">${milestones.map(m=>{const v=Math.min(m.value(),m.target),claimed=s.claimed.includes(m.id);return `<article class="mission"><span class="mission-icon">${claimed?'✓':'✦'}</span><div><h3>${m.title}</h3><p>${m.desc} · ${v}/${m.target}</p><div class="progress"><i style="width:${v/m.target*100}%"></i></div></div><button class="primary" onclick="claim('${m.id}')" ${claimed||v<m.target?'disabled':''}>${claimed?'已领取':'领取 '+m.reward+' 铜钱'}</button></article>`}).join('')}</div>`}
function claim(id){const m=milestones.find(x=>x.id===id);if(!m||s.claimed.includes(id)||m.value()<m.target)return;s.claimed.push(id);s.money+=m.reward;commit(`「${m.title}」完成，获得 ${m.reward} 铜钱。`)}
function bagView(){$('#view').innerHTML=routeHeader('COLLECTION','我的行囊','食材和早餐不会过期。慢慢积攒属于你的小院收藏。')+`<h3 class="block-title">食材与早餐</h3><div class="bag-grid">${Object.entries(names).map(([k,n])=>`<article class="bag-item ${s.inv[k]?'':'empty'}"><span>${crops[k]?.icon||recipes[k]?.icon||(k==='rice'?'🌾':'🥡')}</span><h3>${n}</h3><b>× ${s.inv[k]||0}</b></article>`).join('')}</div><h3 class="block-title">种子袋</h3><div class="inventory">${Object.entries(crops).map(([k,c])=>`<span>${c.icon} ${c.name}种子 × ${s.seeds[k]}</span>`).join('')}</div><div class="collection-note">✦ 已亲手收获或制作 ${s.discovered.length} / 7 种物品 · 累计经营收入 ${s.earnings} 铜钱</div>`}
resetGame=function(){oldReset();extras();page='home';location.hash='home';render();save()};
const originalValid=validState;validState=function(x){return originalValid(x)&&(!x.upgrades||['farm','kitchen'].every(k=>Number.isInteger(x.upgrades[k])&&x.upgrades[k]>=0&&x.upgrades[k]<=2))&&(!x.claimed||Array.isArray(x.claimed)&&x.claimed.every(k=>milestones.some(m=>m.id===k)))&&(!x.friends||Array.isArray(x.friends)&&x.friends.length>=3&&x.friends.length<=8&&x.friends.every(n=>Number.isSafeInteger(n)&&n>=0))&&(!x.discovered||Array.isArray(x.discovered)&&x.discovered.every(k=>Object.hasOwn(names,k)))};
sourceView=function(){modal('这间小院的代码','<p>原生 HTML、CSS 与 JavaScript。页面切换与经营逻辑均在浏览器运行。</p><div class="inventory">'+['index.html','app.js','style.css','village.js','village.css','story-data.js','chronicles.js','chronicles.css'].map(f=>`<button class="secondary" onclick="loadSource('${f}')">${f}</button>`).join('')+'</div><pre class="source" id="sourceText">选择文件查看源码</pre>')};
extras();page=location.hash.slice(1)||'home';if(!routes[page]&&page!=='bag')page='home';render();save();

const CHAPTERS=[
{title:'雾落梅山',subtitle:'一张照片，把你带回了旧时光',goal:'读完本章 · 收获 1 次 · 送出 3 份早餐',test:()=>s.harvests>=1&&s.sold>=3,scenes:[
['史河边的雨','来到金寨梅山的那天，雨比预报里大得多。你沿着史河边走，躲进一家收藏旧物的小店。窗边摆着梅山水库的明信片，柜台里却压着另一张泛黄照片：一间瓦屋、一口灶，门前站着一个模糊的人。照片背后只有一句话：“天暗了，也给赶路的人留盏灯。”你伸手拂去灰尘，耳边忽然响起木门撞上门框的声音。'],
['陌生的屋檐','再睁眼时，路灯和玻璃橱窗都不见了。屋檐滴着雨，泥路边蹲着一只小黄狗。桂婆婆递来一碗温水，说这间小院空了很久，你若愿意拾掇，就先住下。你问这里是不是梅山，她只指着山外说：“沿着史河走，总能找着路。”手机没了反应，照片却还夹在掌心。你决定先把灶火点起来。'],
['第一碗热粥','阿禾送来几包种子，周木匠替你扶正了晃动的桌脚。没人追问你的来处，他们只问明天有没有早饭。你忽然发现，想弄清发生了什么，得先在这里好好生活。门前四畦地还空着，米袋里有一点口粮。小黄狗在门边睡着了，鼻尖朝向灶台。也许今天的任务不用那么宏大：种下一棵菜，给别人盛一碗热粥。']]},
{title:'史河有信',subtitle:'沿着河岸，找到被遗漏的线索',goal:'读完本章 · 探访史河渡口 · 与林先生对话 · 村居到第 3 天',test:()=>s.visited.includes('river')&&s.met.includes('lin')&&s.day>=3,scenes:[
['赶集的小路','清早，阿禾邀你去河边赶集。竹篮里有带刺的栗苞，晒干的茶叶被仔细包在纸里。你认得这些味道，却不认得摊主口中的地名。卖米的人说要去“立煌”办事，你下意识看向远山：这里明明是你旅行中的金寨，为什么名字不一样？阿禾见你走神，把一枚板栗放在你掌心：“先别想那么远，炒熟了可甜。”'],
['渡口的纸船','渡口边，小满正追着一只被风吹走的纸船。你帮他拾回来，发现折痕里有一截旧报纸。日期残缺，只有“民国三十六年”几个字还看得清。你不敢立刻下结论。小满说林先生识得字，也认得旧地名，若你愿意，下午可以一道去学堂。河风翻动纸角，那张小院照片忽然变得沉甸甸的。'],
['没有水库的山谷','从高处望去，你记忆中的湖面不见了，眼前只有史河与起伏的山谷。林先生听你问起水库，摇了摇头：“你说的那座大坝，我未见过。”你终于意识到，自己找的也许不是回镇上的路，而是回到原来年代的路。他没有催问你的秘密，只借你一本空册子：“记下来。记得越清楚，就越不容易迷路。”']]},
{title:'栗香与旧针脚',subtitle:'认识这里的人，才读得懂这里的往事',goal:'读完本章 · 探访栗林 · 与罗伯对话 · 累计送出 6 份早餐',test:()=>s.visited.includes('grove')&&s.met.includes('luo')&&s.sold>=6,scenes:[
['栗树下的约定','栗林的风里有一点甜味。阿禾挑出饱满的栗子，说你可以试着做栗子粥，剩下的留给来帮忙的邻里。你问她有没有想过去更远的地方，她想了想：“想啊。可我也想让留下的人吃得好一点。”这句话让你记了一整天。回小院时，桂婆婆正在补一件褪色的旧衣，针脚细得像一条条山路。'],
['罗伯的旧布包','周木匠带你认识罗伯。老人早年参加过红军，如今留在村里修竹器。他打开旧布包，里面不是你想象的传奇物件，而是一只磨损的水壶和几根缝衣针。“走得再远，人也得喝水，衣裳也会破。”你听见故事里的人忽然有了温度。罗伯说，他最记得的，是赶路时有人递来的一口热饭。'],
['山外有人来','傍晚，小满跑来说山外的路上来了许多赶路人。村里没有立刻热闹起来，只是有人添了柴，有人多淘了一碗米。桂婆婆把灶边的干木头码好，叮嘱你遇到客人先问吃没吃饭。你望向照片里的屋檐，发现灯下那张木桌的缺口，竟和眼前完全一样。某些事情正在靠近，但你还没有看清它们的名字。']]},
{title:'山路上的灯',subtitle:'在一个普通的清晨，听见历史的回声',goal:'读完本章 · 与小川对话 · 探访山路驿棚 · 累计送出 9 份早餐',test:()=>s.met.includes('chuan')&&s.visited.includes('trail')&&s.sold>=9,scenes:[
['三份不加盐的粥','天刚亮，一个穿旧军装的年轻人来问能不能做几份淡一点的粥。他说同行的人走累了，想让他们吃些容易入口的。付钱时，他把铜钱一枚枚数清，又问借来的竹筒该还在哪里。你没有追问，只记下他的名字：小川。等他走远，桂婆婆把门口的凳子往里挪了挪，给后来的人留出地方。'],
['名字终于连起来','林先生带来消息：刘伯承、邓小平率领的部队已经挺进大别山。你想起纸船上的年份，想起人们口中的立煌，终于把零散线索拼到一起——这是1947年。眼前经过的是人民解放军，而罗伯讲述的红军岁月，属于更早的历史。你一直当作课本标题的那段往事，此刻正从小院门前经过。'],
['灶火也是回答','你问小川能帮上什么，他没有要求你做惊天动地的大事，只说若能备些方便携带的饭食，路上就少一分难处。你望着新长出的青菜和灶上的热气，第一次没有急着寻找回去的方法。你仍然想家，却也开始明白：在这里把一件小事做好，也能成为别人的依靠。今晚，要留哪一盏灯，由你自己决定。']]},
{title:'把灶火留下',subtitle:'选择你的帮助方式，照顾身边的人',goal:'读完本章 · 完成 1 次互助委托 · 累计送出 12 份早餐',test:()=>s.supportDone>=1&&s.sold>=12,scenes:[
['两条都温暖的路','村里开始安排互助。你可以留在小院，为老人和路过的人做饭，也可以帮小川准备便携的补给。林先生说，两种选择都重要。你没有无穷的粮食，也不是能改变一切的人；先顾好自己，再尽力帮别人，已经很好。桂婆婆把一只干净的竹篮放到桌上，让你自己决定装进去什么。'],
['灯下的人','青禾是一位随队的年轻卫生员。她来取热水时，顺手替小满重新系好松开的鞋带。她说自己最盼望的，是有一天赶路不再着急，人们能坐下来好好吃饭。你问她到那时想做什么，她笑着说也许开一间小店。窗外的灯照着每个人的脸，那些被称作“大事”的日子，也由许多这样的愿望组成。'],
['一张新的照片','你再翻看那张旧照片，终于认出了门前模糊的人影。那个人没有站在队伍最前面，只扶着门框，朝路上挥手。你没有试图把每个人都留住，而是认真记下他们喜欢的饭、说过的话和留下的约定。有些人还要继续赶路，有些人留下守着村子。属于你的那一页，已经写进了小院的炊烟。']]},
{title:'梅山的回声',subtitle:'故事暂告一段落，生活仍在继续',goal:'主线完成 · 自由经营与邻里日常已开放',test:()=>false,scenes:[
['梦里的水面','那夜你梦见了现代梅山。史河的水向前流，后来建成的梅山水库静静映着群山。你知道，那属于另一个年代的建设与生活，不能与眼前的1947年混为一谈。梦里有人在岸边拍照，有人提着菜回家。原来你最初习以为常的平静，值得被这样仔细地记住。'],
['一封没有地址的信','你写了一封没有地址的信：这里有桂婆婆的热粥、阿禾的种子、罗伯的竹器，也有年轻人不肯放下的愿望。你没有写自己做了多大的事，只写今天的青菜长得很好。信被夹进手记，和那张照片放在一起。是否离开，留给以后的某一天。此刻，门外已经有人问：“今天开门吗？”'],
['明天，照常开门','你推开窗，山风带来熟悉的味道。故事中的悬念有了回答，日常却还有许多空白：没尝过的栗子粥、还未说完的话、想慢慢修好的院子。你把招牌擦干净，给灶里添了一把柴。梅山拾光记的第一段旅程到这里结束，但你的小院仍会迎来下一个早晨。愿每一次相逢，都有一碗热饭。']]}
];
const CAST=[
{id:'gui',name:'桂婆婆',icon:'👵',unlock:0,role:'守着老屋与一口热灶',gift:'porridge',topics:[['我想听听这间老屋的故事','从前赶集的人走累了，就在这儿歇脚。屋子空了，灶还在。你愿意住下来，它就又有了人气。','house'],['我有点想家了','那就先好好吃饭。找路的事情可以慢慢来，别让自己饿着。','home'],['明天做什么好吃的？','青菜切细些，粥熬软些。好吃不一定要贵，让人吃着舒服就好。','food']]},
{id:'he',name:'阿禾',icon:'👩🏻',unlock:0,role:'把愿望藏在种子里的姑娘',gift:'pancake',topics:[['教我照顾种子吧','浇过水就让它慢慢长。收获时记得留种，明年的盼头，就在今天手里。','seed'],['你最喜欢这里的什么？','栗树开花的时候，风里有种特别的味道。等栗子落了，我们一起去捡。','grove'],['想试试我的新菜饼吗？','当然！不过我还想自己试着种出更甜的菜。哪天咱们比一比？','challenge']]},
{id:'zhou',name:'周木匠',icon:'🧑🏻',unlock:0,role:'把生活修补得结结实实',gift:'radishcake',topics:[['这块招牌还能修吗？','能。木头有纹路，顺着它来就不容易裂。做事和过日子，多少也有点像。','craft'],['你为什么总要软一点的饼？','家里的老人牙口不好。我带回去，她总说吃不完，其实每次都吃得干净。','family'],['我想把小院经营得更好','先顾好眼前的客人。集市里能修缮食铺，也能改良菜地，一点点来。','upgrade']]},
{id:'man',name:'小满',icon:'🧒',unlock:1,role:'史河边的纸船收藏家',gift:'chestnutporridge',topics:[['纸船要漂到哪里？','我也不知道！也许能到山外，也许有人会捡到，知道我们村今天开了一家小食铺。','boat'],['帮我找找照片里的地方','这棵树我认识！不过照片里的门口比现在热闹。你等等，我去叫林先生来看看。','photo'],['今天有什么新消息？','渡口的大叔又讲故事了。还有，我没有偷吃栗子，真的只有一小颗！','news']]},
{id:'lin',name:'林先生',icon:'👨🏻‍🏫',unlock:1,role:'替山村留住字与记忆',gift:'tea',topics:[['“立煌”是什么地方？','那是人们眼下使用的县名。一个地方的名字会变化，山河与住在这里的人，会留下更多记忆。','name'],['这张纸写的是哪一年？','民国三十六年，换算起来是1947年。你看得这样认真，莫非在找一个重要的日子？','year'],['我想把这些事记下来','记人的名字，也记他们怎么吃饭、怎么笑。真正的生活，比一句大话更有分量。','record']]},
{id:'luo',name:'罗伯',icon:'👴',unlock:2,role:'曾参加红军的竹匠老人',gift:'chestnutporridge',topics:[['能讲讲当年的红军吗？','那是更早的岁月了。我记得艰难，也记得乡亲递来的水。别只记住故事里的远方，也记住身边帮过你的人。','redmemory'],['这只旧水壶为什么留着？','它陪我走过路。如今拿来浇花，照样有用。旧东西能接着过日子，就不算白留。','kettle'],['我能做点什么？','先把眼前这顿饭做好。大事小事，人都是一步一步走过去的。','ordinary']]},
{id:'chuan',name:'小川',icon:'🧑🏻‍✈️',unlock:3,role:'1947年路过的解放军战士',gift:'pancake',topics:[['你们是从哪里来的？','走了很长的路，才到大别山。一路都有乡亲帮忙。这份情，我们记着。','arrival'],['我想帮忙准备饭食','可以备些方便带走的饼，但别勉强。村里老人和孩子也要吃饭，先安排好。','supplies'],['等安定下来，你想做什么？','想陪家里人坐下来，慢慢吃一顿饭。不用急着起身赶路。','wish']]},
{id:'qing',name:'青禾',icon:'👩🏻‍⚕️',unlock:4,role:'照看同行人的年轻卫生员',gift:'tea',topics:[['有什么是我能帮上的？','烧些干净的热水，备点易入口的食物。照顾人，要细心，也要量力而行。','care'],['你会不会害怕？','会。但有人互相照应，就能再往前走一步。你这间亮着灯的小店，也让人安心。','courage'],['以后来我的店坐坐吧','说好了。那时别忙着招呼我，坐下来一起吃。我想听听你后来都种了些什么。','promise']]}
];
const PLACES=[{id:'yard',name:'史河小院',icon:'⌂',unlock:0,where:'虚构经营据点',desc:'沿史河山地意象创作的小院。你在这里种菜、经营早餐铺。',route:'home'}, {id:'market',name:'梅山山集',icon:'♧',unlock:0,where:'虚构村集',desc:'板栗、米面和茶香挤在竹篮里。这里的交易与人物均为游戏创作。',route:'shop'}, {id:'river',name:'史河渡口',icon:'≈',unlock:1,where:'史河文化意象 · 虚构渡口',desc:'现代与旧时记忆都沿着史河展开。小满的纸船，在这里留下第一条年代线索。',reward:'rice'}, {id:'grove',name:'栗林茶坡',icon:'♠',unlock:2,where:'金寨物产意象 · 虚构山坡',desc:'金寨板栗与茶叶成为这里的采集物。每天可以带回一小篮栗子与一包茶叶。',reward:'chestnut'}, {id:'trail',name:'山路驿棚',icon:'⚑',unlock:3,where:'虚构故事地点',desc:'赶路的人借一处屋檐歇脚。你可以选择为邻里留饭，或准备路上的补给。',reward:'flour'}, {id:'memory',name:'梅山湖畔 · 现代记忆',icon:'◈',unlock:5,where:'现代回望 · 非1947年场景',desc:'梅山水库位于史河上游、金寨县梅山镇，1954年开工、1956年建成。它只出现在现代序章与回望中。',reward:'teaLeaf'}];

const PREFKEY='meishan-prefs',SLOTKEY='meishan-slots';let prefs={volume:25,mode:'auto'},running=false,loading=false,currentDialogue=null,readingIndex=0;
try{prefs={...prefs,...JSON.parse(localStorage.getItem(PREFKEY)||'{}')}}catch{}
const v5baseExtras=extras;extras=function(){v5baseExtras();s.storyRead??={};s.visited??=[];s.met??=[];s.dialogueChoices??={};s.dialogueLog??=[];s.exploreDays??={};s.supportDone??=0;s.supportDay??=0;s.helpPath??='';s.actions??=0;s.storyEdition=2;while(s.friends.length<CAST.length)s.friends.push(0);s.inv.chestnut??=0;s.inv.teaLeaf??=0;s.inv.chestnutporridge??=0;s.inv.tea??=0;s.storyRead[s.chapter]??=0;};
Object.assign(names,{chestnut:'金寨板栗',teaLeaf:'山茶叶',chestnutporridge:'栗香米粥',tea:'山间清茶'});Object.assign(recipes,{chestnutporridge:{name:'栗香米粥',icon:'🌰',needs:{chestnut:1,rice:1},price:18},tea:{name:'山间清茶',icon:'🍵',needs:{teaLeaf:1},price:10}});
