const safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function writeLocal(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('浏览器存储空间不足，请导出存档备份。');return false}}
function syncLayout11(){document.body.dataset.mode=window.innerWidth<800?'phone':prefs.mode;}
window.addEventListener('resize',syncLayout11);
function applyPrefs(){prefs.volume=Math.min(100,Math.max(0,Number(prefs.volume)||0));if(!['auto','phone','desktop'].includes(prefs.mode))prefs.mode='auto';syncLayout11();if(musicGain)musicGain.gain.setTargetAtTime(prefs.volume/100*.12,audioCtx.currentTime,.05);writeLocal(PREFKEY,prefs)}
let audioCtx=null,musicGain=null,musicTimer=null,noteIndex=0;const tune=[60,64,67,69,67,64,62,60,55,60,64,67,64,62,60,55];
function beginMusic(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(!musicGain){musicGain=audioCtx.createGain();musicGain.connect(audioCtx.destination)}audioCtx.resume();musicGain.gain.value=prefs.volume/100*.12;if(musicTimer)return;musicTimer=setInterval(()=>{if(!running||document.hidden||prefs.volume===0)return;const n=tune[noteIndex++%tune.length],osc=audioCtx.createOscillator(),g=audioCtx.createGain();osc.type='sine';osc.frequency.value=440*2**((n-69)/12);g.gain.setValueAtTime(0,audioCtx.currentTime);g.gain.linearRampToValueAtTime(.75,audioCtx.currentTime+.025);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+1.5);osc.connect(g);g.connect(musicGain);osc.start();osc.stop(audioCtx.currentTime+1.6)},550)}catch{toast('当前浏览器暂不支持背景音乐，其余玩法可正常使用。')}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null;if(audioCtx)audioCtx.suspend()}
function setVolume(v){prefs.volume=Number(v);applyPrefs();const n=$('#volumeValue');if(n)n.textContent=v+'%';if(running)beginMusic()}
function setMode(v){prefs.mode=v;applyPrefs();toast(v==='phone'?'已切换为大按钮手机模式':v==='desktop'?'已切换为电脑侧栏模式':'已跟随屏幕自动适配')}
settings=function(){modal('把小院调成喜欢的样子',`<div class="settings-row"><label for="volume">背景音乐 <b id="volumeValue">${prefs.volume}%</b></label><input id="volume" type="range" min="0" max="100" value="${prefs.volume}" oninput="setVolume(this.value)"><small>轻柔的合成器旋律 · 开始游戏后播放 · 0 为静音</small></div><div class="settings-row"><label for="layoutMode">操作布局</label><select id="layoutMode" onchange="setMode(this.value)"><option value="auto" ${prefs.mode==='auto'?'selected':''}>自动适配</option><option value="phone" ${prefs.mode==='phone'?'selected':''}>手机模式 · 底部导航 / 大按钮</option><option value="desktop" ${prefs.mode==='desktop'?'selected':''}>电脑模式 · 侧边导航</option></select></div><p class="story-note">进度保存在当前浏览器，游客也能玩。换设备请先导出存档。早晚随游戏行动推进，不随现实时间倒计时。</p><div class="modal-actions"><button class="primary" onclick="closeModal()">设置好了</button>${running?'<button class="secondary" onclick="saveMenu(true)">保存 / 读取</button><button class="secondary" onclick="returnTitle()">返回标题</button>':''}</div>`)};
function newState(){const x=initial();x.log=['在现代金寨梅山的一场雨里，你触碰到一张旧照片，醒来时已经身在史河沿岸的虚构栗溪村。'];return x}
function newAdventure(){if(s.day>1||s.sold||s.harvests||s.storyRead?.[0]){modal('开启一段新的拾光旅程？','<p>开始新游戏会替换自动存档。手动存档槽不会被删除，建议先保存当前进度。</p><div class="modal-actions"><button class="primary" onclick="startFresh()">开始新旅程</button><button class="secondary" onclick="saveMenu(true)">先保存进度</button></div>')}else startFresh()}
function startFresh(){s=newState();extras();closeModal();loadWorld(true)}
async function loadWorld(intro=false){if(loading)return;loading=true;closeModal();$('#loadingScreen').hidden=false;$('#loadingBar').style.width='0%';$('#loadingPercent').textContent='0%';$('#loadingText').textContent='小猫正在检查小院的灯与种子…';let loaded=0;const assets=[ASSETS["meishan-day.png"],ASSETS["meishan-night.png"]];try{await Promise.all(assets.map(src=>new Promise((resolve,reject)=>{const im=new Image();const timer=setTimeout(()=>reject(Error('图片加载超时')),12000);im.onload=()=>{clearTimeout(timer);loaded++;const p=Math.round(loaded/(assets.length+1)*100);$('#loadingBar').style.width=p+'%';$('#loadingPercent').textContent=p+'%';resolve()};im.onerror=()=>{clearTimeout(timer);reject(Error('背景加载失败'))};im.src=src})));extras();running=true;page='home';location.hash='home';document.body.classList.remove('at-title');render();save();beginMusic();$('#loadingBar').style.width='100%';$('#loadingPercent').textContent='100%';$('#loadingText').textContent='小院准备好了，欢迎回家。';await new Promise(r=>setTimeout(r,450));$('#loadingScreen').hidden=true;loading=false;if(intro)readStory(0)}catch{loading=false;$('#loadingScreen').hidden=true;modal('小猫在路上停了一下','<p>背景暂时加载失败，请检查网络后重试。存档没有删除。</p><button class="primary" onclick="loadWorld(false)">重新进入</button>')}}
function returnTitle(){save();closeModal();running=false;stopMusic();document.body.classList.add('at-title');window.scrollTo(0,0)}
function exitGame(){returnTitle();modal('今天的拾光，先到这里','<p>进度已自动保存。网页通常不能主动关闭浏览器标签，你现在可以直接关闭页面，下次从「读取存档」继续。</p><button class="primary" onclick="closeModal()">回到标题</button>')}
function slots(){try{const x=JSON.parse(localStorage.getItem(SLOTKEY)||'[]');return Array.isArray(x)?x.slice(0,3):[]}catch{return []}}
function saveMenu(canSave=running){const arr=slots();let auto=null;try{auto=JSON.parse(localStorage.getItem(KEY))}catch{}modal('拾光存档',`<p>自动存档 + 3 个手动存档槽。记录只属于当前浏览器。</p><div class="save-slots"><div class="save-slot"><div><b>自动存档</b><small>${auto?'第 '+auto.day+' 天 · '+safe(CHAPTERS[auto.chapter]?.title||'小院生活'):'还没有存档'}</small></div><button class="secondary" ${auto?'':'disabled'} onclick="loadSlot(-1)">继续</button></div>${[0,1,2].map(i=>`<div class="save-slot"><div><b>存档 ${i+1}</b><small>${arr[i]?'第 '+arr[i].state.day+' 天 · '+safe(arr[i].label):'空存档槽'}</small></div>${canSave?`<button class="secondary" onclick="storeSlot(${i})">保存</button>`:''}<button class="primary" ${arr[i]?'':'disabled'} onclick="loadSlot(${i})">读取</button></div>`).join('')}</div><div class="modal-actions"><button class="secondary" onclick="exportSave()">导出当前存档</button><label class="secondary file-import">导入 JSON<input type="file" accept=".json,application/json" onchange="importSave(this.files[0])"></label></div>`)}
function storeSlot(i,confirmed=false){if(![0,1,2].includes(i))return;const arr=slots();if(arr[i]&&!confirmed){modal('覆盖这个存档槽？',`<p>存档 ${i+1} 将替换为当前第 ${s.day} 天的进度。</p><button class="primary" onclick="storeSlot(${i},true)">确认覆盖</button>`);return}arr[i]={state:JSON.parse(JSON.stringify(s)),label:CHAPTERS[s.chapter].title,at:Date.now()};if(writeLocal(SLOTKEY,arr)){toast('存档 '+(i+1)+' 已保存');saveMenu(true)}}
function restoreState(x){if(!validState(x))throw Error('invalid');s=JSON.parse(JSON.stringify(x));extras();s.log=s.log.map(t=>safe(t));s.dialogueLog=s.dialogueLog.filter(v=>typeof v==='string').slice(-80);}
function loadSlot(i,confirmed=false){let x;try{x=i===-1?JSON.parse(localStorage.getItem(KEY)):slots()[i]?.state;if(!x||!validState(x))throw Error();if(running&&!confirmed){modal('读取之前的时光？',`<p>当前进度将替换为这个存档。需要保留当前进度时，请先保存到其他存档槽。</p><button class="primary" onclick="loadSlot(${i},true)">确认读取</button>`);return}restoreState(x);loadWorld(false)}catch{toast('这个存档无法读取，当前进度没有改变。')}}
importSave=async function(file){if(!file)return;try{const x=JSON.parse(await file.text());if(!validState(x))throw Error();pendingImport=x;modal('恢复导入的存档？',`<p>将切换到第 ${x.day} 天的记录，当前自动存档会被替换。</p><button class="primary" onclick="acceptImport()">确认恢复</button>`)}catch{toast('存档格式不正确，当前进度没有改变。')}};let pendingImport=null;
function acceptImport(){if(!pendingImport)return;restoreState(pendingImport);pendingImport=null;loadWorld(false)}
const validBefore5=validState;validState=function(x){try{return validBefore5(x)&&(!x.storyRead||typeof x.storyRead==='object'&&!Array.isArray(x.storyRead)&&Object.values(x.storyRead).every(n=>Number.isInteger(n)&&n>=0&&n<=3))&&['visited','met','dialogueLog'].every(k=>x[k]===undefined||Array.isArray(x[k])&&x[k].every(v=>typeof v==='string'))&&['actions','supportDone','supportDay'].every(k=>x[k]===undefined||Number.isSafeInteger(x[k])&&x[k]>=0)&&['exploreDays','dialogueChoices','friendDays'].every(k=>x[k]===undefined||x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k]))}catch{return false}};
chapterName=function(){return CHAPTERS[s.chapter].title};chapterGoal=function(){return CHAPTERS[s.chapter].goal};checkChapter=function(){};
function advanceClock(){s.actions=Math.min(6,s.actions+1);save();render()}
function evening(){return s.actions>=4}
const dayBefore5=advanceDay;advanceDay=function(){s.actions=0;dayBefore5()};
const plantBefore5=plant;plant=function(i,k){const before=s.seeds[k];plantBefore5(i,k);if(s.seeds[k]<before)advanceClock()};
const cookBefore5=cook;cook=function(k){const n=s.inv[k];cookBefore5(k);if(s.inv[k]>n)advanceClock()};
const serveBefore5=serve;serve=function(i){const n=s.sold;serveBefore5(i);if(s.sold>n)advanceClock()};
const harvestBefore5=plot;plot=function(i){const n=s.harvests;harvestBefore5(i);if(s.harvests>n)advanceClock()};
function restUntilEvening(){if(evening())return;s.actions=4;commit('日影慢慢移过屋檐，灯火亮起来了。')}
const renderBefore5=render;render=function(){extras();renderBefore5();document.body.dataset.time=evening()?'night':'day';$('#breadcrumb').textContent='金寨 · 梅山拾光 / '+(routes[page]?.[1]||'行囊');const time=evening()?'18:30':'0'+(7+Math.min(3,s.actions))+':00';$('#stats').innerHTML=`<div class="time-card"><span class="clock-medal">${evening()?'☾':'☀'}</span><div><small>初秋 · 第 ${s.day} 天</small><b>${time} <em>${evening()?'灯火初上':'晨光正好'}</em></b></div><button class="time-skip" onclick="restUntilEvening()" ${evening()?'disabled':''}>${evening()?'晚安小院':'等到傍晚'}</button></div><div class="resource-pill"><span>◉</span><div><small>钱袋</small><b>${s.money}</b></div></div><div class="resource-pill"><span>♡</span><div><small>邻里心意</small><b>${s.rep}</b></div></div><div class="resource-pill"><span>♨</span><div><small>送出热饭</small><b>${s.sold}</b></div></div>`;const bg=evening()?ASSETS["meishan-night.png"]:ASSETS["meishan-day.png"];document.documentElement.style.setProperty('--scene-art',`url("${bg}")`);const im=document.querySelector('.village-scene>img');if(im)im.src=bg;const ribbon=$('.scene-ribbon');if(ribbon)ribbon.textContent='✦ 史河小院 · '+(evening()?'给晚归的人留一盏灯':'清晨的一碗热粥');if(page==='map')mapView();if(page==='home'){const n=$('.daily-note');if(n)n.innerHTML=`<small>主线 · 第 ${s.chapter+1} 章</small><p>${safe(CHAPTERS[s.chapter].subtitle)}</p><button onclick="readStory()">${(s.storyRead[s.chapter]||0)<3?'继续主线故事':'回顾这一章'} →</button>`;}if(page==='bag'){const note=$('.collection-note');if(note)note.textContent='✦ 金寨板栗与山间清茶已加入食材收藏 · 累计经营收入 '+s.earnings+' 铜钱';}if(page==='shop')$('#view').insertAdjacentHTML('beforeend',`<section class="regional-shop"><h3>山里来的好物</h3><p>栗林未解锁前，也能从山集少量采购。</p><button class="secondary" onclick="buyLocal('chestnut')">🌰 金寨板栗 · 5 铜钱</button><button class="secondary" onclick="buyLocal('teaLeaf')">🍃 山茶叶 · 4 铜钱</button></section>`)};
function buyLocal(k){const price={chestnut:5,teaLeaf:4}[k];if(!price||s.money<price){toast('钱袋还不够，先完成一份订单吧。');return}s.money-=price;s.inv[k]++;commit('购入 '+names[k]+' 1 份。')}
function readStory(index){readingIndex=index??Math.min(s.storyRead[s.chapter]||0,2);if(!Number.isInteger(readingIndex)||readingIndex<0||readingIndex>2)return;const sc=CHAPTERS[s.chapter].scenes[readingIndex];modal(sc[0],`<div class="story-meta">第 ${s.chapter+1} 章 · ${safe(chapterName())} <span>${readingIndex+1} / 3</span></div><p class="story-prose">${sc[1]}</p><div class="story-dots">${[0,1,2].map(n=>`<i class="${n<=readingIndex?'lit':''}"></i>`).join('')}</div><div class="modal-actions">${readingIndex?'<button class="secondary" onclick="readStory(readingIndex-1)">上一段</button>':''}<button class="primary" onclick="finishStoryPage()">${readingIndex<2?'继续阅读 →':'把这一页记下来'}</button></div>`)}
function finishStoryPage(){s.storyRead[s.chapter]=Math.max(s.storyRead[s.chapter]||0,readingIndex+1);save();if(readingIndex<2)readStory(readingIndex+1);else{closeModal();commit('故事已记入手记。完成章目标后可开启下一章。');go('journal')}}
function nextChapter(){if(s.chapter>=5)return;if((s.storyRead[s.chapter]||0)<3||!CHAPTERS[s.chapter].test()){toast('先读完本章，并完成章目标。');return}s.chapter++;s.storyRead[s.chapter]=0;s.log.push(CHAPTERS[s.chapter].subtitle);commit('新章节开启：'+chapterName());readStory(0)}
showStory=function(){readStory()};
const journalBefore5=journalView;journalView=function(){journalBefore5();const st=$('.journal-story');if(st)st.innerHTML=`<div class="journal-art"><span>梅山<br>拾光</span></div><div><small>第 ${s.chapter+1} 章 · 已读 ${s.storyRead[s.chapter]||0}/3 段</small><h2>${chapterName()}</h2><p>${CHAPTERS[s.chapter].subtitle}</p><div class="chapter-goal">${chapterGoal()}</div><div class="modal-actions"><button class="primary" onclick="readStory()">继续阅读</button><button class="secondary" onclick="nextChapter()" ${s.chapter>=5||(s.storyRead[s.chapter]||0)<3||!CHAPTERS[s.chapter].test()?'disabled':''}>${s.chapter>=5?'终章 · 自由经营':'开启下一章 →'}</button></div></div>`;$('#view').insertAdjacentHTML('beforeend',`<h3 class="block-title">拾光目录</h3><div class="chapter-list">${CHAPTERS.map((c,i)=>`<button class="chapter-item" onclick="recap(${i})" ${i>s.chapter?'disabled':''}><b>0${i+1} · ${i>s.chapter?'尚未解锁':c.title}</b><small>${i>s.chapter?'随主线解锁':i===s.chapter?'正在经历':'已留下的记忆'}</small></button>`).join('')}</div>${s.chapter>=4?`<section class="support-card"><h3>这一盏灯，留给谁？</h3><p>两条帮助路线都能推进主线；每日完成一次，不影响你继续经营。</p><button class="secondary" onclick="support('village')">邻里暖饭：交付清粥 × 2</button><button class="secondary" onclick="support('road')">山路补给：交付青菜饼 × 2</button><small>累计完成 ${s.supportDone} 次 · 每次获得 12 铜钱与 3 心意</small></section>`:''}<h3 class="block-title">你说过的话</h3><div class="dialogue-record">${s.dialogueLog.length?s.dialogueLog.slice(-8).reverse().map(t=>`<p>${safe(t)}</p>`).join(''):'还没有留下对话选择，去和村民聊聊吧。'}</div><p class="history-note">地域参考：<a href="https://www.luan.gov.cn/zjla/lyla/gjslgy/10031682.html" target="_blank" rel="noopener">梅山湖风景区</a> · <a href="https://www.chinawater.com.cn/wh/202402/t20240229_1038736.html" target="_blank" rel="noopener">史河与梅山水库建设</a>。地理背景真实，村落、人物与事件对白为虚构；地图为剧情示意。</p>`)};
function recap(i){if(i>s.chapter||!CHAPTERS[i])return;modal(CHAPTERS[i].title,CHAPTERS[i].scenes.map(([t,p])=>`<h3>${t}</h3><p>${p}</p>`).join(''))}
function support(path){if(s.chapter<4||s.supportDay===s.day){toast('今天的互助已完成，明天再来吧。');return}const food=path==='village'?'porridge':'pancake';if(s.inv[food]<2){toast('还需要准备 '+names[food]+' × 2。');return}s.inv[food]-=2;s.helpPath=path;s.supportDone++;s.supportDay=s.day;s.money+=12;s.rep+=3;s.dialogueLog.push('第 '+s.day+' 天：你选择了'+(path==='village'?'为邻里留饭':'为山路准备补给')+'。');commit('热饭送到了。互助 +1，获得 12 铜钱与 3 心意。');advanceClock()}
friendsView=function(){$('#view').innerHTML=routeHeader('PEOPLE OF MEISHAN','人间有相逢','还没遇见的人，会在故事里慢慢走来。每一次选择，都能留下一点记忆。')+`<div class="friend-grid">${CAST.map((p,i)=>{const locked=s.chapter<p.unlock,f=s.friends[i]||0;return `<article class="friend-card ${locked?'locked-character':''}"><div class="portrait portrait-${i%3}"><span>${locked?'?':p.icon}</span><small>${locked?'尚未相逢':p.role}</small></div><div class="friend-body"><small>${locked?'第 '+(p.unlock+1)+' 章解锁':f>=8?'知心邻里':f>=3?'熟悉的朋友':'初识的邻居'}</small><h2>${locked?'未解锁角色':p.name}</h2><p>${locked?['','','','河边传来的消息','旧时岁月的见证者','山路上的年轻人','灯下照看他人的人'][i]||'等待故事继续':p.role}</p><div class="friend-hearts">${locked?'✦ · · · ✦':'♥'.repeat(Math.min(5,Math.floor(f/2)))+'♡'.repeat(5-Math.min(5,Math.floor(f/2)))}</div><div class="friend-actions"><button class="primary" onclick="talk(${i})" ${locked?'disabled':''}>${locked?'等待解锁':'选择话题'}</button>${!locked?`<button class="secondary" onclick="gift(${i})" ${s.inv[p.gift]<1||s.friendDays['gift'+i]===s.day?'disabled':''}>送${names[p.gift]}</button>`:''}</div></div></article>`}).join('')}</div>`};
talk=function(i){const p=CAST[i];if(!p||s.chapter<p.unlock)return;currentDialogue=i;const remembered=s.dialogueChoices[p.id];modal(p.name,`<div class="dialogue-speaker"><span>${p.icon}</span><div><small>${p.role}</small><p>${remembered?'“你上回说的话，我还记得。今天想聊什么？”':'“来，坐一会儿。你想聊些什么？”'}</p></div></div><div class="dialogue-options">${p.topics.map((t,j)=>`<button onclick="chooseDialogue(${i},${j})"><span>0${j+1}</span>${t[0]} <b>›</b></button>`).join('')}</div><p class="story-note">每日首次选择话题：亲近度 +1；每个新话题首次选择：心意 +1。选择会记入手记。</p>`)};
function chooseDialogue(i,j){const p=CAST[i];if(currentDialogue!==i||!p||s.chapter<p.unlock||!p.topics[j])return;const t=p.topics[j],key=p.id+':'+j,first=!s.dialogueChoices[key];if(first){s.dialogueChoices[key]=true;s.rep++}s.dialogueChoices[p.id]=j+1;if(s.friendDays['talk'+i]!==s.day){s.friendDays['talk'+i]=s.day;s.friends[i]++;s.actions=Math.min(6,s.actions+1)}if(!s.met.includes(p.id))s.met.push(p.id);s.dialogueLog.push('第 '+s.day+' 天 · '+p.name+'：你问「'+t[0]+'」');s.dialogueLog=s.dialogueLog.slice(-80);commit();modal(p.name,`<div class="dialogue-speaker"><span>${p.icon}</span><div><small>你选择了：${t[0]}</small><p class="npc-reply">“${t[1]}”</p></div></div><div class="choice-result">${first?'✦ 新话题记入手记 · 心意 +1':'♡ 这段话，你们都记得'}</div><div class="modal-actions"><button class="primary" onclick="talk(${i})">再聊一个话题</button><button class="secondary" onclick="closeModal()">下次再来</button></div>`)}
gift=function(i){const p=CAST[i];if(!p||s.chapter<p.unlock||s.inv[p.gift]<1||s.friendDays['gift'+i]===s.day)return;s.inv[p.gift]--;s.friendDays['gift'+i]=s.day;s.friends[i]+=2;s.rep+=2;commit(p.name+'收下了'+names[p.gift]+'，亲近度 +2。')};
function mapView(){$('#view').innerHTML=routeHeader('SHI RIVER · STORY MAP','沿史河，去走走','剧情示意地图，并非真实导航；地点随章节解锁。每处每天可探索一次。')+`<section class="story-map"><div class="map-river"></div><span class="map-mountain">大 别 山</span>${PLACES.map((p,i)=>`<button class="map-pin pin-${i} ${s.chapter<p.unlock?'pin-locked':''}" onclick="visitPlace('${p.id}')"><span>${s.chapter<p.unlock?'♙':p.icon}</span><b>${s.chapter<p.unlock?'未解锁 · 第'+(p.unlock+1)+'章':p.name}</b></button>`).join('')}<small class="map-key">⌖ 梅山与史河意象 · 非按比例绘制</small></section><div class="map-legend"><span>✦ 每日探索收获</span><span>🌰 板栗</span><span>🍃 茶叶</span><span>▤ 年代线索</span></div>`}
function visitPlace(id){const p=PLACES.find(p=>p.id===id);if(!p)return;if(s.chapter<p.unlock){toast('第 '+(p.unlock+1)+' 章解锁这处地点。');return}modal(p.name,`<span class="place-tag">${p.where}</span><p>${p.desc}</p><button class="primary" onclick="explore('${id}')">${p.route?'前往这里 →':s.exploreDays[id]===s.day?'今日已探索':'探索一下 →'}</button>`)}
function explore(id){const p=PLACES.find(p=>p.id===id);if(!p||s.chapter<p.unlock)return;if(p.route){closeModal();go(p.route);return}if(s.exploreDays[id]===s.day){toast('今天已经走过这里，明天再来吧。');return}s.exploreDays[id]=s.day;if(!s.visited.includes(id))s.visited.push(id);s.inv[p.reward]++;if(id==='grove')s.inv.teaLeaf++;closeModal();commit('带回 '+names[p.reward]+' × 1'+(id==='grove'?'、山茶叶 × 1':'')+'，足迹记入手记。');advanceClock()}
const helpBefore5=showHelp;showHelp=function(){modal('在梅山，慢慢生活','<p>① 农田播种并浇水，结束今日后生长。</p><p>② 食铺制作早餐，再切到订单交付。</p><p>③ 种植、制作、交付、首次聊天与探索会推进游戏时间；行动 4 次进入傍晚，也可点击「等到傍晚」。结束今日回到次日清晨。</p><p>④ 手记中分段阅读主线，满足目标后手动开启下一章；地图和角色随章节解锁。</p><p>⑤ 设置中可调音乐、切换手机 / 电脑布局；存档菜单有三个手动槽，支持导出与导入。</p><p>不设离线惩罚。地图、人物和故事事件为虚构；梅山水库只在现代记忆中出现。</p><button class="primary" onclick="closeModal()">开始我的日常</button>')};
sourceView=function(){modal('梅山拾光记 · 源码','<p>原生 HTML、CSS 和 JavaScript，所有经营与存档均在本机浏览器运行。</p><div class="inventory">'+['index.html','app.js','village.js','story-data.js','chronicles.js','chronicles.css'].map(f=>`<button class="secondary" onclick="loadSource('${f}')">${f}</button>`).join('')+'</div><pre class="source" id="sourceText">选择文件查看源码</pre>')};
resetGame=function(){newAdventure()};
extras();applyPrefs();render();save();document.addEventListener('visibilitychange',()=>{if(document.hidden&&audioCtx)audioCtx.suspend();else if(running&&audioCtx)audioCtx.resume()});

/* 梅山拾光记：离线生活扩展 */
const LOOKS=['莓果来信','山茶小满','晴空阿禾','桃桃猫帽','月光铃兰','栗香秋日'];
const HAIRS=['#8c5b48','#e9c583','#ece5eb','#e6a6b7','#b5a3cc','#44414b'];
const CLOTHES=['#eaa5b5','#9eb886','#8ebddd','#c6abd5','#edcb84','#dc9c78'];
const EYES=['#665047','#658eac','#829968','#a8799d'];
const defaultLook=()=>({name:'小满',kind:'preset',preset:0,hair:0,style:0,outfit:0,eye:0,skin:0,hat:0});
const oldExtras6=extras;extras=function(){oldExtras6();s.player={...defaultLook(),energy:100,xp:0,...s.player};s.ranch={chickens:1,rabbits:0,feed:5,fed:0,pet:0,eggs:0,wool:0,...s.ranch};s.pond={fish:0,feed:3,fed:0,growth:0,stock:0,cast:0,...s.pond};for(const k of ['egg','fish','wool','eggRice','fishSoup'])s.inv[k]??=0;};
Object.assign(names,{egg:'鲜鸡蛋',fish:'塘鲜鱼',wool:'软兔绒',eggRice:'鸡蛋米饼',fishSoup:'山蔬鱼汤'});
Object.assign(recipes,{eggRice:{name:'鸡蛋米饼',icon:'🍳',needs:{egg:1,rice:1},price:20},fishSoup:{name:'山蔬鱼汤',icon:'🍲',needs:{fish:1,greens:1},price:26}});
Object.assign(routes,{ranch:['♧','养殖','小小伙伴，慢慢长大','RANCH'],pond:['≈','鱼塘','史河边，等一尾小鱼','POND']});
let lookDraft=null,lookNew=false,introIndex=0;
function pixelAvatar(p){let h=HAIRS[p.hair],c=CLOTHES[p.outfit],e=EYES[p.eye],skin=['#ffe1ca','#ecc3a2','#c98e6f'][p.skin];const r=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;let a='';a+=r(9,6,30,32,h);if(p.style===1)a+=r(3,19,8,29,h)+r(37,19,8,29,h);if(p.style===2)a+=r(10,27,28,26,h);a+=r(12,12,24,23,skin)+r(10,13,3,17,skin)+r(35,13,3,17,skin);a+=r(11,7,27,8,h)+r(12,14,6,5,h)+r(20,13,5,4,h)+r(30,13,6,7,h);a+=r(15,22,5,7,'#fff8eb')+r(28,22,5,7,'#fff8eb')+r(16,24,3,5,e)+r(29,24,3,5,e)+r(16,23,2,2,'white')+r(29,23,2,2,'white');a+=r(12,29,5,2,'#eea3ac')+r(31,29,5,2,'#eea3ac')+r(23,32,3,1,'#ad7169');a+=r(17,36,14,16,c)+r(11,38,6,11,c)+r(31,38,6,11,c)+r(12,49,5,4,skin)+r(31,49,5,4,skin)+r(14,49,20,6,c);a+=r(21,37,6,12,'#fff4df')+r(17,49,14,3,'#fff4df')+r(17,55,5,6,skin)+r(27,55,5,6,skin)+r(15,60,8,4,'#6f5a51')+r(26,60,8,4,'#6f5a51');if(p.hat===1)a+=r(6,6,36,4,'#d9b779')+r(12,1,24,7,'#edd59b')+r(12,6,24,2,'#b78077');if(p.hat===2)a+=r(7,10,8,5,'#eea8b9')+r(15,11,7,3,'#eea8b9')+r(13,12,3,4,'#be7e99');return `<svg class="pixel-avatar" viewBox="0 0 48 68" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg" aria-label="自定义像素角色"><ellipse cx="24" cy="66" rx="14" ry="2" fill="#80695a33"/>${a}</svg>`}
function avatar(p,cls=''){return p.kind==='preset'?`<div class="doll ${cls}" style="--doll-x:${[13,51,90.5][p.preset%3]}%;--doll-y:${Math.floor(p.preset/3)*100}%" role="img" aria-label="${LOOKS[p.preset]}"></div>`:`<div class="custom-doll ${cls}">${pixelAvatar(p)}</div>`}
function openWardrobe(fresh=false){extras();lookNew=fresh;lookDraft=JSON.parse(JSON.stringify(s.player));wardrobe()}
function wardrobe(){const p=lookDraft;modal(lookNew?'先认识一下，新的你':'小院衣橱',`<div class="wardrobe"><div class="mirror"><small>MEISHAN · DRESS UP</small>${avatar(p)}<b>${safe(p.name||'未命名')}</b><span>♡ 今天也要可可爱爱</span></div><div class="wardrobe-controls"><label class="name-label">你的名字<input id="playerName" maxlength="12" value="${safe(p.name)}" oninput="lookDraft.name=this.value.trim().slice(0,12)"></label><div class="segmented"><button onclick="lookDraft.kind='preset';wardrobe()" class="${p.kind==='preset'?'active':''}">插画套装</button><button onclick="lookDraft.kind='custom';wardrobe()" class="${p.kind==='custom'?'active':''}">自由捏脸</button></div>${p.kind==='preset'?`<p class="micro">六套原创软萌像素形象，穿好一整套去山间生活。</p><div class="look-grid">${LOOKS.map((n,i)=>`<button class="look-choice ${p.preset===i?'chosen':''}" onclick="lookDraft.preset=${i};wardrobe()">${avatar({...p,preset:i})}<span>${n}</span></button>`).join('')}</div>`:`<p class="micro">自由搭配采用简洁像素小人，支持独立调整五官与服饰。</p>${[['style','发型',['短发','双马尾','长发']],['hair','发色',HAIRS],['eye','眼睛',EYES],['skin','肤色',['#ffe1ca','#ecc3a2','#c98e6f']],['outfit','衣服',CLOTHES],['hat','配饰',['无','草帽','蝴蝶结']]].map(([k,t,opts])=>`<div class="choice-row"><b>${t}</b><div>${opts.map((v,i)=>`<button aria-label="${t}${i+1}" class="${p[k]===i?'chosen':''} ${v.startsWith('#')?'swatch':''}" style="${v.startsWith('#')?'--swatch:'+v:''}" onclick="lookDraft.${k}=${i};wardrobe()">${v.startsWith('#')?'':v}</button>`).join('')}</div></div>`).join('')}`}</div></div><div class="modal-actions"><button class="primary" onclick="confirmLook()">${lookNew?'带着这个模样出发 →':'保存我的模样'}</button><button class="secondary" onclick="closeModal()">稍后再说</button></div>`)}
function confirmLook(){if(!lookDraft.name){toast('给自己起一个名字吧。');return}s.player={...s.player,...lookDraft};save();closeModal();if(lookNew)startPrologue();else{render();toast('衣橱已收好，新模样也记住了。')}}
const originalStartFresh6=startFresh;startFresh=function(){s=newState();extras();closeModal();openWardrobe(true)};
const INTRO=[['一张来自梅山的明信片','现代 · 金寨梅山','忙碌的消息一条接一条。你把手机收进口袋，沿史河慢慢走。旧书摊里，一张泛黄的照片滑落下来——照片上，是一间亮着灯的小食铺。','✉'],['雨声，把时间轻轻翻页','山间 · 一场忽然的雨','指尖碰到照片背面的字：如果累了，就来这里住几天。雨落在纸上，远处的水声忽然变得很近。你闭上眼，再睁开时，脚下已是陌生的石板路。','☂'],['小院正等着一个名字','史河沿岸 · 虚构山村','桂婆婆撑着伞向你招手：“先来避雨吧。后院有空着的地，鸡舍也还好好的。你若愿意，替我照顾它们，就在这儿安个家。”','⌂'],['把日子，过成喜欢的样子','你的第一天','你推开木门。阿黄摇着尾巴，小鸡挤在草窝里，塘面漾开一圈水纹。至于这究竟是哪一年……先烧一壶水，再慢慢寻找答案吧。','❀']];
function startPrologue(){introIndex=0;showIntro()}
function showIntro(){let root=$('#prologue');if(!root){root=document.createElement('section');root.id='prologue';document.body.appendChild(root)}const x=INTRO[introIndex];root.hidden=false;root.innerHTML=`<div class="intro-haze"></div><div class="intro-particles">✦　　·　　✧　　·　　✦</div><button class="intro-skip" onclick="endIntro()">跳过序章 →</button><div class="intro-card"><small>${x[1]} · ${introIndex+1} / 4</small><div class="intro-symbol">${x[3]}</div><h1>${x[0]}</h1><p>${x[2]}</p><div class="intro-progress">${INTRO.map((_,i)=>`<i class="${i<=introIndex?'on':''}"></i>`).join('')}</div><button class="primary" onclick="nextIntro()">${introIndex===3?'推开小院的门':'翻过这一页'} →</button></div>`}
function nextIntro(){if(introIndex<3){introIndex++;showIntro()}else endIntro()}
function endIntro(){$('#prologue').hidden=true;loadWorld(true)}
function gainLife(x){s.player.xp+=x}
function spendEnergy(n){if(s.player.energy<n){toast('精力不足，先休息一下或结束今日。');return false}s.player.energy-=n;return true}
function takeBreak(){extras();if(s.restDay===s.day){toast('今天已经好好休息过了。明天再来吧。');return}s.restDay=s.day;s.player.energy=Math.min(100,s.player.energy+30);commit('喝口温茶，精力恢复 30。')}
function playerBar(){const p=s.player;return `<section class="player-card"><button class="player-portrait" onclick="openWardrobe()" aria-label="打开角色衣橱">${avatar(p)}</button><div class="player-details"><div><b>${safe(p.name)}</b><span>Lv.${1+Math.floor(p.xp/30)} · 山居新人</span></div><label>精力 <strong>${p.energy} / 100</strong></label><div class="energy-track"><i style="width:${p.energy}%"></i></div><small>生活经验 ${p.xp} · 下一级还需 ${30-p.xp%30}</small></div><div class="player-actions"><button onclick="takeBreak()">♨ 小憩</button><button onclick="openWardrobe()">♡ 换装</button></div></section>`}
const beforeRender6=render;render=function(){extras();beforeRender6();$('#stats').insertAdjacentHTML('afterend','');let hud=$('#lifeHud');if(!hud){hud=document.createElement('div');hud.id='lifeHud';$('#stats').after(hud)}hud.innerHTML=playerBar();if(page==='ranch')ranchView();if(page==='pond')pondView();if(page==='home'){const sc=$('.village-scene');if(sc){sc.insertAdjacentHTML('beforeend',`<button class="world-label ranch-label" onclick="go('ranch')"><b>♧ 养殖小舍</b><small>${s.ranch.chickens} 鸡 · ${s.ranch.rabbits} 兔 →</small></button><button class="world-label pond-label" onclick="go('pond')"><b>≈ 史河小塘</b><small>${s.pond.fish} 尾鱼儿 →</small></button><button class="world-player" onclick="openWardrobe()" aria-label="给角色换装">${avatar(s.player)}</button>`)} }if(page==='map')$('#view').insertAdjacentHTML('beforeend',`<div class="life-map-links"><button class="primary" onclick="go('ranch')">♧ 去养殖小舍</button><button class="secondary" onclick="go('pond')">≈ 去史河小塘</button></div>`)};
function ranchView(){const a=s.ranch;$('#view').innerHTML=routeHeader('LITTLE COMPANIONS','篱笆里，都是小牵挂','每天喂一次，明早收一份惊喜。鸡产蛋，兔子每两个喂养日留下软绒。')+`<div class="life-scene ranch-scene"><div class="life-sun">☀</div><div class="coop">⌂<span>暖暖小舍</span></div><div class="animal-parade">${Array.from({length:a.chickens},(_,i)=>`<span style="--delay:${i*.3}s">🐔</span>`).join('')}${Array.from({length:a.rabbits},(_,i)=>`<span style="--delay:${i*.4}s">🐇</span>`).join('')}</div><div class="life-scene-note">${a.fed===s.day?'♡ 今天吃得饱饱的':'把谷料放进食槽吧'}</div></div><div class="life-grid"><article><small>照料伙伴</small><h3>${a.chickens} 只鸡 · ${a.rabbits} 只兔</h3><p>饲料 ${a.feed} 份 · 每天消耗 ${Math.max(1,Math.ceil((a.chickens+a.rabbits)/2))} 份</p><button class="primary" onclick="feedRanch()" ${a.fed===s.day?'disabled':''}>${a.fed===s.day?'今日已喂养':'喂养 · 精力 −8'}</button><button class="secondary" onclick="petAnimals()" ${a.pet===s.day?'disabled':''}>摸摸伙伴</button></article><article><small>今天的收获</small><h3>🥚 ${a.eggs} 枚蛋 · ☁ ${a.wool} 份绒</h3><p>收进背包后可出售，鸡蛋也能制作米饼。</p><button class="primary" onclick="collectRanch()" ${!a.eggs&&!a.wool?'disabled':''}>收取产物</button><button class="secondary" onclick="buySupply('animal')">买饲料 × 5 · 5 钱</button></article><article><small>添一个新伙伴</small><h3>给小院多添一点热闹</h3><p>鸡最多 4 只，兔最多 3 只。没有喂养只暂停产出，不会死亡。</p><button class="secondary" onclick="buyAnimal('chickens')" ${a.chickens>=4?'disabled':''}>领养小鸡 · 18 钱</button><button class="secondary" onclick="buyAnimal('rabbits')" ${a.rabbits>=3?'disabled':''}>领养小兔 · 24 钱</button></article></div>`+produceSales()}
function feedRanch(){const a=s.ranch,n=Math.max(1,Math.ceil((a.chickens+a.rabbits)/2));if(a.fed===s.day)return;if(a.feed<n){toast('饲料不足，先补一点谷料。');return}if(!spendEnergy(8))return;a.feed-=n;a.fed=s.day;gainLife(3);advanceClock();toast('食槽装满了，小伙伴们开心地围过来。')}
function petAnimals(){if(s.ranch.pet===s.day)return;s.ranch.pet=s.day;s.rep++;gainLife(1);commit('软乎乎的陪伴，心意 +1。')}
function collectRanch(){const a=s.ranch;if(!a.eggs&&!a.wool)return;s.inv.egg+=a.eggs;s.inv.wool+=a.wool;const n=a.eggs+a.wool;a.eggs=0;a.wool=0;gainLife(n);commit('收获装进行囊啦！')}
function buyAnimal(k){if(!['chickens','rabbits'].includes(k))return;const price=k==='chickens'?18:24,cap=k==='chickens'?4:3;if(s.ranch[k]>=cap||s.money<price){toast('钱袋不足，或小舍已经住满了。');return}s.money-=price;s.ranch[k]++;commit('新伙伴入住啦，记得准备明天的饲料。')}
function buySupply(k){if(s.money<5){toast('需要 5 铜钱。');return}s.money-=5;(k==='animal'?s.ranch:s.pond).feed+=5;commit('饲料 +5。')}
function pondView(){const p=s.pond;$('#view').innerHTML=routeHeader('SHI RIVER POND','塘面一圈圈，日子慢悠悠','放养鱼苗，投喂两天后收鱼；也可以试试每日一次的轻量钓鱼。')+`<div class="life-scene pond-scene"><div class="ripples">◯　◯　◯</div><span class="pond-lotus">🪷</span><div class="swimming-fish">${'🐟　'.repeat(Math.min(5,p.fish||1))}</div><div class="pond-deck">🎣</div><div class="life-scene-note">${p.fish?p.growth>=2?'鱼儿已经长大，可以收获了':'成长 '+p.growth+' / 2 个投喂日':'塘水清亮，等你放入第一批鱼苗'}</div></div><div class="life-grid"><article><small>塘里生活</small><h3>${p.fish} 尾鱼 · ${p.feed} 份鱼食</h3><p>每次放养 3 尾，最多 6 尾；新鱼苗加入会重置这批成长。</p><button class="secondary" onclick="stockPond()" ${p.fish>=6?'disabled':''}>放养 × 3 · 9 钱</button><button class="primary" onclick="feedPond()" ${!p.fish||p.fed===s.day||p.growth>=2?'disabled':''}>投喂 · 精力 −6</button></article><article><small>塘鲜收获</small><h3>成长 ${p.growth} / 2</h3><p>投喂后结束今日才会成长。鲜鱼可出售或烹饪。</p><button class="primary" onclick="harvestFish()" ${!p.fish||p.growth<2?'disabled':''}>收获鲜鱼</button><button class="secondary" onclick="buySupply('fish')">鱼食 × 5 · 5 钱</button></article><article><small>河边坐一会儿</small><h3>不着急，等鱼来</h3><p>观察浮漂，亮起“咬钩了”时收竿。每天一次，消耗 10 精力。</p><button class="primary" onclick="castLine()" ${p.cast===s.day?'disabled':''}>${p.cast===s.day?'今日已垂钓':'抛竿试试 →'}</button></article></div>`+produceSales()}
function stockPond(){const p=s.pond;if(p.fish>=6||s.money<9){toast('需要 9 铜钱，并为鱼苗留出位置。');return}s.money-=9;p.fish+=3;p.growth=0;p.fed=0;commit('三尾小鱼游入清亮的塘水，成长重新开始。')}
function feedPond(){const p=s.pond;if(!p.fish||p.fed===s.day||p.growth>=2)return;if(p.feed<1){toast('先买一点鱼食吧。');return}if(!spendEnergy(6))return;p.feed--;p.fed=s.day;gainLife(2);advanceClock();toast('鱼食落下，水面荡起一圈圈波纹。')}
function harvestFish(){const p=s.pond;if(!p.fish||p.growth<2)return;s.inv.fish+=p.fish;gainLife(p.fish*2);p.fish=0;p.growth=0;p.fed=0;commit('鲜鱼已装入行囊。今晚可以煮一碗山蔬鱼汤。')}
let fishingState='idle',fishTimer=null;
function castLine(){if(s.pond.cast===s.day||!spendEnergy(10))return;s.pond.cast=s.day;fishingState='waiting';save();modal('史河边的浮漂','<div class="fishing-water"><span id="bobber">🎣</span><strong id="fishHint">水面静静的……</strong></div><p>等浮漂提示，再按收竿。错过也没关系。</p><button id="reelButton" class="primary" onclick="reelFish()">收竿</button>');clearTimeout(fishTimer);fishTimer=setTimeout(()=>{if(!$('#modal').open||!$('#fishHint')){fishingState='idle';return}fishingState='bite';$('#fishHint').textContent='咬钩了！现在收竿！';$('#bobber').classList.add('biting');fishTimer=setTimeout(()=>{if(fishingState==='bite'){fishingState='miss';if($('#fishHint'))$('#fishHint').textContent='小鱼游走了，下次会更熟练。'}},4500)},1700)}
function reelFish(){clearTimeout(fishTimer);let msg;if(fishingState==='bite'){s.inv.fish++;gainLife(5);msg='钓到一尾鲜鱼！生活经验 +5。'}else msg='浮漂轻轻摇晃，小鱼溜走了。明天再来试试。';fishingState='idle';closeModal();advanceClock();toast(msg)}
function produceSales(){return `<section class="produce-sales"><h3>小院出品</h3><p>留一些做饭，也可以把剩下的送到山集。</p>${[['egg',6],['fish',10],['wool',12],['eggRice',20],['fishSoup',26]].map(([k,n])=>`<button class="secondary" onclick="sellProduce('${k}')" ${s.inv[k]<1?'disabled':''}>卖${names[k]} · ${n}钱（有${s.inv[k]}）</button>`).join('')}</section>`}
function sellProduce(k){const prices={egg:6,fish:10,wool:12,eggRice:20,fishSoup:26};if(!prices[k]||s.inv[k]<1)return;s.inv[k]--;s.money+=prices[k];s.earnings+=prices[k];gainLife(1);commit('山集收下了'+names[k]+'，铜钱 +'+prices[k]+'。')}
const beforeDay6=advanceDay;advanceDay=function(){extras();const a=s.ranch,p=s.pond;if(a.fed===s.day){a.eggs+=a.chickens;a.cared=(a.cared||0)+1;if(a.cared%2===0)a.wool+=a.rabbits}if(p.fish&&p.fed===s.day)p.growth=Math.min(2,p.growth+1);s.player.energy=100;beforeDay6()};
const beforeCook6=cook;cook=function(k){const n=s.inv[k];beforeCook6(k);if(s.inv[k]>n){gainLife(2);save();render()}};
const validBefore6=validState;validState=function(x){if(!validBefore6(x))return false;if(x.player){const p=x.player;if(typeof p.name!=='string'||p.name.length>12||!['preset','custom'].includes(p.kind))return false;for(const [k,cap]of [['preset',5],['hair',5],['style',2],['outfit',5],['eye',3],['skin',2],['hat',2],['energy',100],['xp',100000000]])if(!Number.isInteger(p[k])||p[k]<0||p[k]>cap)return false}for(const key of ['ranch','pond'])if(x[key]){if(typeof x[key]!=='object'||Array.isArray(x[key]))return false;for(const v of Object.values(x[key]))if(!Number.isSafeInteger(v)||v<0||v>100000000)return false}return true};
const help6=showHelp;showHelp=function(){help6();$('#modalBody').insertAdjacentHTML('beforeend','<p>⑥ 小院人物头像可打开衣橱。可以分别选择男女形象、脸型底模、头发和服装，搭配会保存并在院中展示。</p><p>⑦ 养殖场喂养后次日产蛋，兔子每两个喂养日产绒；鱼塘投喂两天后收鱼。精力不足可每天小憩一次，或结束今日恢复。</p><p>⑧ 离线文件建议定期导出存档。微信等应用内预览可能不运行脚本，请下载后用支持 HTML 的浏览器打开。</p>')};
extras();render();save();

/* 美术分层衣橱：底模脸型 / 发型 / 衣服 */
const WARDROBE={female:{label:'女生',sheet:'girls-layers-png',faces:['星莓 · 明亮蓝瞳','山茶 · 害羞红瞳','晴空 · 灵动蓝瞳','桃桃 · 软萌粉瞳','月铃 · 梦幻紫瞳','栗秋 · 温柔绿瞳'],hair:['蜜糖卷发','银白双马尾','栗色短发','桃粉双辫','浅紫短发','深栗双辫'],clothes:['草莓蝴蝶结裙','山茶采茶裙','晴空背带裤','桃桃猫咪裙','铃兰围裙装','栗香针织裙']},male:{label:'男生',sheet:'boys-layers-png',faces:['清川 · 澄澈蓝瞳','向阳 · 明朗琥珀','青竹 · 温和绿瞳','望舒 · 安静紫瞳','知秋 · 暖棕笑眼','阿澈 · 活泼青瞳'],hair:['栗色蓬松短发','蜜金侧分','深棕利落短发','银灰层次短发','墨色侧梳','雾蓝碎发'],clothes:['青山针织套装','晴空背带套装','麦穗暖黄套装','书院藏蓝套装','栗棕围巾套装','竹青山居套装']}};
let wardrobeTab='face',showLayerParts=false,detailZoom7=false,wardrobeOriginal7=null,genderDrafts7={};
function layerDefaults(p){const i=Number.isInteger(p.preset)?Math.min(5,Math.max(0,p.preset)):0;return {gender:'female',facePart:i,hairPart:p.kind==='custom'?Math.min(5,p.hair||0):i,clothesPart:p.kind==='custom'?Math.min(5,p.outfit||0):i,layerVersion:1,...p}}
const extrasBefore7=extras;extras=function(){extrasBefore7();s.player=layerDefaults(s.player)};
function spriteLayer(g,row,index,extra=''){return `<span class="sprite-layer ${extra}" style="--sheet:var(--asset-${WARDROBE[g].sheet});--part-x:${index*20}%;--part-y:${row*50}%" aria-hidden="true"></span>`}
function layeredDoll(p,only='all'){const q=layerDefaults(p),g=q.gender==='male'?'male':'female';return `<div class="layered-doll ${only==='all'?'assembled':''}" role="img" aria-label="${WARDROBE[g].label}，${WARDROBE[g].faces[q.facePart]}，${WARDROBE[g].hair[q.hairPart]}，${WARDROBE[g].clothes[q.clothesPart]}">${only==='all'||only==='face'?spriteLayer(g,0,q.facePart,'base-part'):''}${only==='all'||only==='clothes'?spriteLayer(g,2,q.clothesPart,'clothes-part'):''}${only==='all'||only==='hair'?spriteLayer(g,1,q.hairPart,'hair-part'):''}</div>`}
avatar=function(p,cls=''){return `<div class="avatar7 ${cls}">${layeredDoll(p)}</div>`};
openWardrobe=function(fresh=false){extras();lookNew=fresh;lookDraft=JSON.parse(JSON.stringify(s.player));wardrobeTab='face';showLayerParts=false;detailZoom7=false;wardrobeOriginal7=JSON.parse(JSON.stringify(lookDraft));genderDrafts7={};wardrobe()};
wardrobe=function(){const p=lookDraft,d=WARDROBE[p.gender],key={face:'facePart',hair:'hairPart',clothes:'clothesPart'}[wardrobeTab],labels=d[{face:'faces',hair:'hair',clothes:'clothes'}[wardrobeTab]];modal(lookNew?'为新的生活，选一个模样':'拾光衣橱 · 随心搭配',`<div class="dress-editor"><div class="dress-mirror"><span class="mirror-stars">✧　♡　✧</span><small>MEISHAN · PAPER DOLL</small><div class="mirror-figure ${detailZoom7?'detail-zoom':''}">${avatar(p)}</div><h3>${safe(p.name||'我的角色')}</h3><p>${d.label} · ${d.hair[p.hairPart]}</p><div class="mirror-actions"><button class="secondary" onclick="randomOutfit()">✦ 随机搭配</button><button class="secondary" onclick="detailZoom7=!detailZoom7;wardrobe()">${detailZoom7?'查看全身':'放大看脸'}</button></div></div><div class="dress-controls"><label class="name-label">角色名字<input id="playerName" maxlength="12" value="${safe(p.name)}" oninput="lookDraft.name=this.value.trim().slice(0,12);document.querySelector('.dress-mirror h3').textContent=lookDraft.name||'我的角色'"></label><div class="gender-switch" role="group" aria-label="选择性别"><button class="${p.gender==='female'?'selected':''}" onclick="setGender('female')">♀ 女生</button><button class="${p.gender==='male'?'selected':''}" onclick="setGender('male')">♂ 男生</button></div><div class="dress-tabs" role="tablist">${[['face','底模 · 脸型'],['hair','头发'],['clothes','衣服']].map(([k,t])=>`<button role="tab" aria-selected="${wardrobeTab===k}" onclick="wardrobeTab='${k}';wardrobe()">${t}</button>`).join('')}</div><p class="dress-hint">${{face:'六张不同表情与眼睛的脸，底模统一穿着浅色内搭。',hair:'已恢复最初的素材位置；脸型、头发和衣服可分别选择。',clothes:'每套包含上装、下装和鞋；不会替换你选好的脸与头发。'}[wardrobeTab]}</p><div class="parts-grid">${labels.map((n,i)=>{const thumb={...p,[key]:i};return `<button class="part-choice ${p[key]===i?'selected':''}" onclick="choosePart('${key}',${i})" aria-label="选择${n}" aria-pressed="${p[key]===i}"><div class="part-thumbnail part-${wardrobeTab}">${layeredDoll(thumb,wardrobeTab)}</div><b>${n}</b>${p[key]===i?'<span class="part-check">✓</span>':''}</button>`}).join('')}</div><button class="layer-inspector" onclick="showLayerParts=!showLayerParts;wardrobe()">${showLayerParts?'收起':'查看'}当前三层素材 ${showLayerParts?'−':'＋'}</button></div></div>${showLayerParts?`<div class="layer-preview">${[['face','① 底模与脸'],['clothes','② 衣服与鞋'],['hair','③ 头发']].map(([k,t])=>`<div><div class="checker">${layeredDoll(p,k)}</div><small>${t}</small></div>`).join('')}<div><div class="checker">${avatar(p)}</div><small>＝ 你的搭配</small></div></div>`:''}<div class="dress-footer"><small>脸型、头发、衣服独立保存 · 可随时回来换装</small><button class="secondary" onclick="resetLook7()">恢复原搭配</button><button class="secondary" onclick="closeModal()">取消</button><button class="primary" onclick="confirmLook7()">${lookNew?'带着这个模样出发 →':'保存搭配'}</button></div>`)};
function choosePart(k,i){if(!['facePart','hairPart','clothesPart'].includes(k)||!Number.isInteger(i)||i<0||i>5)return;lookDraft[k]=i;wardrobe()}
function setGender(g){if(!WARDROBE[g]||g===lookDraft.gender)return;genderDrafts7[lookDraft.gender]={facePart:lookDraft.facePart,hairPart:lookDraft.hairPart,clothesPart:lookDraft.clothesPart};Object.assign(lookDraft,genderDrafts7[g]||{facePart:0,hairPart:0,clothesPart:0},{gender:g});wardrobe()}
function resetLook7(){lookDraft=JSON.parse(JSON.stringify(wardrobeOriginal7));genderDrafts7={};wardrobe()}
function randomOutfit(){for(const k of ['facePart','hairPart','clothesPart'])lookDraft[k]=Math.floor(Math.random()*6);wardrobe()}
function confirmLook7(){if(!lookDraft.name){toast('先给角色起个名字吧。');return}s.player={...s.player,...lookDraft,kind:'preset',layerVersion:1};save();closeModal();if(lookNew)startPrologue();else{render();toast('新搭配已保存，去门前晒晒太阳吧。')}}
const validateBefore7=validState;validState=function(x){if(!validateBefore7(x))return false;const p=x.player;if(!p||p.layerVersion===undefined)return true;return p.layerVersion===1&&['female','male'].includes(p.gender)&&['facePart','hairPart','clothesPart'].every(k=>Number.isInteger(p[k])&&p[k]>=0&&p[k]<6)};
function positionPlayer7(){const scene=document.querySelector('.village-scene'),img=scene?.querySelector('img'),player=scene?.querySelector('.world-player');if(!img||!player||!img.naturalWidth)return;const w=scene.clientWidth,h=scene.clientHeight,offset=parseFloat(getComputedStyle(img).objectPosition)/100||.5,scale=Math.max(w/img.naturalWidth,h/img.naturalHeight),iw=img.naturalWidth*scale,ih=img.naturalHeight*scale;player.style.left=((w-iw)*offset+iw*.287)+'px';player.style.top=((h-ih)/2+ih*.423)+'px';player.style.width=(iw*.052)+'px';player.style.height=(iw*.052*1.5)+'px';}
const drawWardrobe7=wardrobe;wardrobe=function(){const dialog=document.querySelector('#modal'),top=dialog?dialog.scrollTop:0;drawWardrobe7();if(dialog)dialog.scrollTop=top};
const renderBefore7=render;render=function(){renderBefore7();const im=document.querySelector('.village-scene>img');if(im){im.addEventListener('load',positionPlayer7,{once:true});requestAnimationFrame(positionPlayer7)}};
window.addEventListener('resize',positionPlayer7);
if(typeof ResizeObserver!=='undefined'){const observer7=new ResizeObserver(positionPlayer7);observer7.observe(document.body)}
extras();render();save();

/* Illustrated scenes; all state changes reuse the saved game rules. */
function hotspot8(id,label,x,y,disabled=false){return `<button class="scene-hotspot ${disabled?'is-done':''}" style="--x:${x}%;--y:${y}%" onclick="sceneAction8('${id}')" aria-label="${label}"><i></i><b>${label}</b></button>`}
function paintedScene8(kind,caption,spots){return `<section class="painted-scene ${evening()?'is-evening':''}" aria-label="${kind==='pond'?'史河鱼塘':'养殖小舍'}交互场景"><img src="${kind==='pond'?ASSETS["meishan-pond.png"]:ASSETS["meishan-ranch.png"]}" alt="${kind==='pond'?'繁花环绕的像素鱼塘，有水车、鱼苗围栏、鱼食桶与垂钓码头':'花树竹林间的像素养殖小院，有鸡窝、兔舍、食槽和粮仓'}">${spots}<div class="scene-caption">${caption}</div><div class="scene-feedback" aria-live="polite"></div></section>`}
const ranchBefore8=ranchView;ranchView=function(){ranchBefore8();const a=s.ranch;$('#view').innerHTML=$('#view').innerHTML.replace(/<div class="life-scene ranch-scene">[\s\S]*?<div class="life-grid">/,paintedScene8('ranch',`鸡 ${a.chickens} · 兔 ${a.rabbits} · 饲料 ${a.feed}　${a.fed===s.day?'今日已喂养':'等待照料'}`,hotspot8('collect','鸡窝 · 收取',25,43)+hotspot8('feedAnimal','食槽 · 喂养',48,66,a.fed===s.day)+hotspot8('pet','兔舍 · 摸摸',74,49,a.pet===s.day)+hotspot8('barn','粮仓 · 补给',86,77))+'<p class="scene-tip">点击场景里的木牌照料伙伴；下方可查看实际数量与收获。</p><div class="life-grid">')};
const pondBefore8=pondView;pondView=function(){pondBefore8();const p=s.pond;$('#view').innerHTML=$('#view').innerHTML.replace(/<div class="life-scene pond-scene">[\s\S]*?<div class="life-grid">/,paintedScene8('pond',`鱼 ${p.fish} · 鱼食 ${p.feed} · 成长 ${p.growth}/2　${p.fed===s.day?'今日已投喂':''}`,hotspot8('feedFish','鱼食桶 · 投喂',13,46,p.fed===s.day)+hotspot8('stock','鱼苗栏 · 放养',23,74)+hotspot8('fish','码头 · 垂钓',83,58,p.cast===s.day)+hotspot8('harvest','鱼篓 · 收鱼',56,83))+'<p class="scene-tip">鱼苗投喂两天后可收获。画面为环境插画，实际养殖进度见上方状态。</p><div class="life-grid">')};
function sceneAction8(id){const before=JSON.stringify(s);if(id==='barn'){modal('小舍粮仓',`<p>谷料 ${s.ranch.feed} 份。喂养会在次日结算产出。</p><button class="primary" onclick="closeModal();buySupply('animal')">购买 5 份谷料 · 5 钱</button>`);return}if(id==='feedFish'&&(!s.pond.fish||s.pond.fed===s.day||s.pond.growth>=2)){toast(!s.pond.fish?'先在鱼苗栏放养小鱼。':s.pond.growth>=2?'鱼儿长大了，可以收鱼啦。':'今天已经投喂过啦。');return}if(id==='feedAnimal'&&s.ranch.fed===s.day){toast('今天的谷料已经添好了。');return}if(id==='collect'&&!s.ranch.eggs&&!s.ranch.wool){toast('还没有产物，喂养后迎接明天吧。');return}if(id==='harvest'&&(!s.pond.fish||s.pond.growth<2)){toast('鱼儿还没长大：投喂后结束今日，累计两天即可收获。');return}if(id==='pet'&&s.ranch.pet===s.day){toast('小伙伴已经收到今天的陪伴啦。');return}const actions={collect:collectRanch,feedAnimal:feedRanch,pet:petAnimals,feedFish:feedPond,stock:stockPond,fish:castLine,harvest:harvestFish};if(actions[id])actions[id]();if(id!=='fish'&&before!==JSON.stringify(s)){const el=document.querySelector('.scene-feedback');if(el){el.textContent=({collect:'收获已装进行囊',feedAnimal:'谷料添好啦',pet:'伙伴心意 +1',feedFish:'鱼儿游过来啦',stock:'三尾新伙伴入住',harvest:'塘鲜已收好'})[id]||'完成';el.classList.add('show')}}}
const MAP_POINTS8=[[20,72],[29,43],[56,60],[58,26],[86,18],[69,43]];
mapView=function(){$('#view').innerHTML=routeHeader('MEISHAN · VALLEY MAP','山水之间，都是日常','点击地点前往或探索。此为金寨意象故事地图，并非真实地理导航。')+`<section class="painted-scene map-scene8"><img src="${ASSETS['meishan-map.png']}" alt="史河山谷的像素地图，含小院、村集、渡口、栗林与山路">${PLACES.map((p,i)=>`<button class="scene-hotspot ${s.chapter<p.unlock?'is-locked':''}" style="--x:${MAP_POINTS8[i][0]}%;--y:${MAP_POINTS8[i][1]}%" onclick="visitPlace('${p.id}')"><i></i><b>${s.chapter<p.unlock?'第'+(p.unlock+1)+'章解锁':p.name}</b></button>`).join('')}</section><div class="destination-list">${PLACES.map(p=>`<button onclick="visitPlace('${p.id}')"><b>${p.name}</b><small>${s.chapter<p.unlock?'第'+(p.unlock+1)+'章解锁':p.route?'前往 →':s.exploreDays[p.id]===s.day?'今日已探索':'探索 →'}</small></button>`).join('')}<button onclick="go('ranch')"><b>养殖小舍</b><small>照料伙伴 →</small></button><button onclick="go('pond')"><b>史河鱼塘</b><small>去钓鱼 →</small></button></div>`};
const workBefore8=workView;workView=function(){if(page!=='kitchen'){workBefore8();return}const orders=dailyOrders();$('#view').innerHTML=routeHeader('MEISHAN · BREAKFAST','山坳小食铺','先做一份热饭，再把它送到客人手里。')+`<section class="kitchen-hero8"><div><small>今日营业中</small><h3>把山间食材，煮成一口温暖。</h3><p>已招待 ${s.orders.length}/3 位客人</p></div></section><div class="kitchen-tabs8" role="tablist"><button role="tab" aria-selected="${sub!=='orders'}" onclick="sub='cook';render()">制作早餐</button><button role="tab" aria-selected="${sub==='orders'}" onclick="sub='orders';render()">今日订单 · ${3-s.orders.length}</button><button onclick="go('shop')">补充食材</button></div><section class="kitchen-cards8">${sub!=='orders'?Object.entries(recipes).map(([k,r],i)=>`<article class="meal-card8"><header><span class="meal-index">${String(i+1).padStart(2,'0')}</span><div><small>小铺食谱 · 现做一份</small><h3>${r.name}</h3></div><b class="meal-stock">库存 ${s.inv[k]||0}</b></header><div class="ingredient-list8">${Object.entries(r.needs).map(([n,v])=>`<span class="${s.inv[n]>=v?'enough':'missing'}">${names[n]}<b>${s.inv[n]||0} / ${v}</b></span>`).join('')}</div><button class="primary" onclick="cook('${k}')" ${canCook(k)?'':'disabled'}>${canCook(k)?'制作一份':'食材不足 · 先去补给'}</button></article>`).join(''):orders.map((o,i)=>`<article class="meal-card8"><header><span class="meal-index">${i+1}</span><div><small>${o.who}</small><h3>${recipes[o.food].name} × 1</h3></div><b class="meal-stock">${s.orders.includes(i)?'已完成':'待招待'}</b></header><p>${o.line}</p><div class="order-reward8">${recipes[o.food].price+s.upgrades.kitchen*2} 铜钱 · 心意 +1 <span>库存 ${s.inv[o.food]||0}</span></div>${s.orders.includes(i)?'<button disabled>今日已送达</button>':s.inv[o.food]?`<button class="primary" onclick="serve(${i})">送上热饭</button>`:`<button class="secondary" onclick="sub='cook';render()">去制作早餐</button>`}</article>`).join('')}</section><p class="scene-tip">食材与成品都不会过期。做好的早餐保存在行囊中。</p>`};
render();

const BRIDGES10=[[["雨中的落款", 0, "你把照片翻来覆去。背面的“留盏灯”三个字，最后一笔拖得很长，像写字的人停下来听了一会儿雨。店主说，东西是从史河沿岸收来的，照片里的人是谁，已经问不清了。你本想拍下来回去慢慢查，屏幕却忽然暗下去。\n醒来后，照片仍在，边角湿得发软。桂婆婆用旧布替你吸水，却没有伸手看背面。她把屋里唯一一张干凳子推给你，自己坐在门槛上。\n“家里有人等你？”她问。你点头，又摇头。她没有笑你的犹豫。“那今晚先在这里歇脚。明早若还下雨，便再歇一日。”屋檐外的雨落在泥里，你第一次害怕，自己也许连该往哪里走都不知道。", "告诉她，我不记得来时的路", "桂婆婆把门闩搁在你伸手够得到的地方：“怕就闩上。要出去找路，喊我一声。”她没有逼你解释。", "先问借住要做些什么", "“把自己照顾好，再把灶边的柴晒干。”她指了指菜地，“那几畦荒着可惜，收成有了，分一把给邻里便好。”"], ["借来的钥匙", 2, "院门的钥匙藏在一块青砖底下。你翻了三次才找到，钥匙上系着一截洗得发白的红布，像是怕老人记性不好，又像怕新来的人不知道怎样回家。\n周木匠带来半块旧木板，蹲在门前量尺寸。他告诉你，地是桂婆婆家的，早些年借给亲戚种过，如今暂由你照看，不是突然从天而降的产业。你心里反而踏实了：借来的东西可以慢慢还，人情也可以一件件记下。\n你问这屋原先的主人去了哪里。他刨木头的手停了一下：“出门的人，有时许久才有一封信。”他没有再说。阿禾从门外探头，提醒你别把菜种全倒进同一个坑里。你的第一个下午，在木屑味和一点窘迫里过去了。", "给木匠记一笔修屋工钱", "他把你的账本推回来：“先记着，等真有进项再说。我不收你的空口许诺，也不抢你的第一顿饭。”", "提议先用一顿早饭抵工钱", "他终于笑了：“那就要软一点的，给我娘带回去。钱没多少，记得她的牙口就成。”"], ["门槛外的第一位客人", 1, "第一锅粥煮得稠了。你怕别人看出来，添水时又添得太急，灶口发出扑的一声，烟直往脸上冲。阿禾没有替你接过勺子，只帮你把锅盖挪开一点：“别慌，它又不会跑。”\n第一位客人是扛柴的妇人。她问能不能把粥盛在自己带来的瓦罐里，家里还有个等饭的人。你忽然明白，这间小铺卖出去的不是屏幕里跳动的数字。那份热气会沿着山路，被带到另一扇门后。\n收摊时，桌上只多了几枚铜钱。你把一枚压在账本上，旁边写下“第一天”。阿禾说字写歪了，你说是桌腿晃。她故意摇了摇桌子，两个人一起笑起来。外头的山仍然陌生，屋里却有了第二个人的笑声。", "把第一枚钱收作纪念", "阿禾替你找来小布袋：“以后穷得想把它花掉，先来问我借。”你知道她并不宽裕，还是认真道了谢。", "拿第一笔收入补一小包米", "“也好，明早就有底气开门。”她把米袋扎紧，“纪念不一定要留下钱，也可以是留下这口灶。”"]], [["集上没有的东西", 1, "你在山集找电池，话一出口就知道自己又说错了。摊主以为你要灯油，给你看一只小陶壶。阿禾替你圆场，说你一路淋雨，脑子还没转过来。她没有当众追问，只在离开人群后停了脚。\n“你总在找这里没有的东西。”她说得很轻。你看着她篮子里的栗子和粗布，想解释电话、导航和只要按一下就会亮的灯，话到了嘴边却都显得不可靠。\n远处有人喊着去立煌的路不好走。阿禾把篮子换到另一只手，让你走在靠山的一侧。她说，真要找什么就慢慢找；找不到时，也别一声不响地走。你第一次意识到，自己的离开也可能成为别人的牵挂。", "坦白自己来自很远的地方", "她没有问有多远，只说：“远到想哭的时候，就来帮我分种子。手上有点事情，心会稳一点。”", "先问她小时候的梅山", "她讲史河边的石头、雨后的山道和第一次赶集。你把那些细节记下，决定等自己弄清楚了，再告诉她秘密。"], ["纸船不能替人送信", 3, "纸船被捞起时，船底已经浸透。小满嘴上说不要了，手却一直攥着。你问他是不是写了什么，他躲了半天，才让你看里面歪歪扭扭的字：娘，今天没下雨。\n他娘在外村帮工，常赶不及回来。小满知道河水不会照着地址拐弯，但纸船放下去的时候，他总觉得话已经出发了。你没有拿大人的道理纠正他，只陪他把湿纸摊在石头上。\n“你的家里人，会不会也在等？”你一时答不上来。他从口袋里掏出一张干净些的纸，让你也折一只。河风吹过纸面，你想起离家前没回完的那条消息，胸口像被轻轻碰了一下。", "折船，但告诉他信要请人带", "你们约定请林先生帮忙写一封真正的信。小满把纸船留在窗台上，说这是练习用的，不会再把重要的话交给水流。", "坐在旁边听他说完", "他讲得越来越细：娘爱吃什么，衣袖补在哪儿。你认真记住了。离开时，他说下次有话还来找你。"], ["空白页上的年份", 4, "林先生把“民国三十六年”写在纸上，又在旁边写了1947。你盯着那四个数字，手里的茶一点点凉下来。那些在旅行攻略里看到的现代道路、湖岸与大坝，此刻都没有出现在窗外。\n“若一个人知道很久以后的事呢？”你试探着问。他搁下笔：“先问自己，究竟知道多少。听过一个结局，不等于认得其中每个人。”\n你原本准备问许多大问题，最后却只问他这本册子能不能借久一点。他说不是借，是送给你，但不能拿它只记赚钱。回小院的路上，你在第一页写下桂婆婆、阿禾、周木匠、小满。年份写在最下面，像一块终于落地、却还没有安稳的石头。", "把年代推测写入手记", "你在1947后面添了一个小问号。林先生点点头：“知道的写知道，不知道的留下空白，这样的记录才可信。”", "先记录今天见到的人", "你写下小满握纸船的手。林先生说，年代可以查，人怎样过完一天，却常常没人替他们记。"]], [["不肯发芽的那一粒", 1, "阿禾挑种子时，把一粒干瘪的放到一旁。你问是不是可以丢掉，她却说要留下来给你看：“盼头不能只靠说。有些东西得试，有些得认清。”\n你们走到栗林边，篮底垫着旧布，鞋边沾着细泥。她告诉你，今年的收成如果够好，她想攒些钱买纸，让小满不用总拿旧账单折船。你以为她会说新衣或首饰，她听完反倒笑你想得太远。\n回去时天阴下来，你提议跑快些，她先把装种子的布袋塞进怀里。她并不是生来就懂得照看每一件东西，只是在这里长大，知道弄丢一小袋种子，要花多少天才补得回来。", "答应替孩子们留一些纸", "“别急着许一大摞。”她伸出一根手指，“下次赶集带一张，也算数。”你把这个小约定记了下来。", "请她教自己辨认好种子", "她把两粒放进你掌心，让你自己比。你第一次觉得，学一件慢事，也是在学如何留在这里。"], ["旧针脚里的名字", 0, "桂婆婆的针线篮里压着几张旧布条，上面绣的字已经淡了。你想把那件褪色的衣裳补得齐整，她却让你留下一处不同颜色的针脚。\n“那是他自己缝的。”她说。她口中的“他”有时是出门的亲人，有时又像许多再没见过的人。你没有追着问一个确切答案，只帮她把线头穿进针眼。\n窗外有孩子念字的声音，老人的手停了停，说自己年轻时也想认更多字。你问现在认还晚不晚。她抬眼看你：“灶里还有火，哪里算晚。”你们从她的名字写起。桂字第一遍歪了，第二遍仍旧歪，她却把那张纸收得很仔细。", "陪她慢慢写名字", "她把写好的字摊平，嘱咐你明天再来检查。那天你收铺很晚，却觉得并没有耽误什么。", "请她教你缝一枚纽扣", "你的第一针扎偏了，她笑着拆开重来：“别怕慢。能补好的东西，何必急着扔。”"], ["只问吃没吃饭", 5, "罗伯编的竹篮边缘很平，你伸手摸过，没有被扎到。他说从前赶路时，最怕肩上的东西磨人，所以如今做活总多磨几下。旧水壶就放在脚边，壶口插着一枝野花。\n你想问他见过哪些大人物，他却先问你饭铺每天能剩多少饭。你答得不确定，他便掰着指头同你算：哪天赶集，哪家有老人，哪种饼第二顿仍好入口。\n讲到早年的红军，他很少用响亮的词。他记得雨里的草鞋、拿盐换来的菜，也记得有人把自家的碗洗了又洗才递给他们。临走时，他提醒你，山外若有人来，不必抢着问身份，先看看人是不是渴了。", "把他的讲述认真记下", "罗伯纠正了你一个名字：“这个得写对，人家帮过我。”你擦掉重写，才知道记录也需要这样的耐心。", "帮他把明天的竹篮送去集上", "他没推辞，只叮嘱你别把篮底拖坏。你们的关系从听故事，变成了一件能一起做的小事。"]], [["一碗粥的价钱", 6, "小川第二次来时，带回了借走的竹筒，洗得很干净。他把钱放在桌上，你说可以少收一点，他却摇头：“你也要买米。”\n他的袖口磨薄了，手指边有细小的裂口。你想把凳子让给他，他站了片刻才坐，说不能耽误太久。桂婆婆端来温水，没有问他走过多少路。小满趴在门边看，想问帽子，又怕打扰。\n小川注意到他，把竹筒递过去，请他帮忙数一数有没有漏还。孩子终于有了正经差事，跑得很快。你看着这一幕，忽然觉得那些尚未弄明白的名字，也许可以晚一点再问。先让眼前的人坐着把这一碗吃完。", "按原价收钱，多添一点热水", "他把铜钱推到你手边，神色松了下来。你们都保住了自己的分寸，这顿饭反而吃得更踏实。", "问他路上是否缺干粮", "他先问你的米面还够不够。你没有夸口，只答应按自己能做的数量备着。"], ["课本以外的清晨", 4, "林先生的消息传到小院时，你正在擦一只缺口碗。刘伯承、邓小平，大别山，1947。几个名字终于连成了你熟悉的那一句话，却没有课本里的整齐边框。\n眼前有灶灰，有还没付的米钱，有小满担心娘赶不上回家的那场雨。你曾把历史想成一条写好的路，如今才发现路上站着许多人，他们并不知道自己的每一个明天。\n林先生看见你发白的指节，接过碗放好：“知道他们是谁，和决定你要做什么，是两件事。”你想起罗伯。他讲的是更早的红军岁月；现在到来的，是人民解放军。时间终于分清了，心却比从前更乱。你并不能替所有人预知命运，也不该用一句知道结局的话轻轻带过他们今天的难。", "承认自己害怕，也想帮忙", "林先生说，害怕并不妨碍人把一件事做好。你决定先从准备下一顿饭开始，不替未知的事情作保证。", "先确认村里的粮食够不够", "你们把米面和要照顾的邻里分别记下。帮助谁，不必靠一时热血决定，也可以认真地算清楚。"], ["留灯的人有自己的名字", 6, "夜里，小川来还一块遮雨布。你把灯往门边挪，他却先替你挡住了风，怕火苗被吹灭。你告诉他自己曾经以为，这些年月里只有站在前头的人才会留下名字。\n他看了看院子：“我倒盼着记住这家铺子。下回来，不必再问路。”这句话太普通，普通得让你险些掉眼泪。\n你取出手记，让他写一个方便称呼的名字。他认真写下“小川”，又把笔递回来。纸上没有承诺重逢的日期，只有两个人都愿意记住的称呼。灶边的水快开了，你说等一等，拿一壶热的再走。他这一次没有客气。", "约定路过时再来吃饭", "小川指了指门口：“我认得这块招牌了。”你没有追问什么时候，给约定留下一点不被催促的余地。", "问能否参加力所能及的工作", "他建议你先加入村里的互助安排，照看饭食和补给。你把名字记进值日簿；这不是立刻成为战士，而是认真承担一项能完成的工作。"]], [["一篮饭食，两份牵挂", 0, "你把竹篮摆上桌，才发现它装不下自己想帮的所有人。桂婆婆没有替你做决定，只把村里需要留饭的名字写在一边，把山路上要带走的份数写在另一边。\n若留在小院，你会有更多时间陪老人吃饭、给孩子读信；若准备补给，你得早一点起身，把饼做得方便装好。两条路都有人需要，也都有顾不到的地方。\n你第一次认真承认，自己不是一个可以把进度条全部填满的人。桂婆婆把多拿的米放回袋里：“今儿够做这些，就把这些做稳。明天还开门呢。”你没有再为没能做到的一切道歉，而是把眼前的篮子擦干净。", "我更想守好邻里的饭桌", "桂婆婆请你先记住哪些老人吃得慢，哪些孩子怕生。留饭之外，还要留出等他们吃完的时间。", "我更想备好赶路的补给", "她替你找来干净包布：“东西交到手里，再说送到了。自个儿也留一份，别空着肚子忙。”"], ["青禾没有说出口的疲倦", 7, "青禾把杯子放下时，手腕轻轻抖了一下。你问是不是水太烫，她笑着说没有。过了一会儿，她才承认昨夜没睡踏实，听见脚步声就想起身。\n你没有讲宽慰的大道理，只把靠墙的凳子挪到背风处。小满捧着鞋来，她替他系好，又叫他自己重做一遍：“下次我不在，也要会。”\n她说自己想开一间小店，但想卖什么还没决定。你说那就留一页空白，等以后再填。她翻看你的手记，发现里面记了谁爱软饼、谁不喜欢太浓的茶，笑意才慢慢落到眼睛里。“你这本，比账本有趣。”门口有人来叫，她起身时，把没说完的话留在了那一页。", "请她坐着把热茶喝完", "她终于没有立刻起身。你们安静坐了一会儿，没有谁必须找一个漂亮的话题。", "同她约定以后一起试新菜", "她在纸上画了一个小碗：“先记在这儿。做坏了也别偷偷倒掉，我要看看有多难吃。”"], ["背面多出来的一行字", 4, "照片背面的字似乎比从前深了一些。你并不能确定它真的变过，还是自己终于看清。那句“天暗了，也给赶路的人留盏灯”下面，还有一行很淡的落款，像一个被岁月磨去的名字。\n你请林先生看。他说也许是许多人传抄过的话，不该因为你希望它来自自己，就断言它一定如此。你把照片收好，忽然不急着证明自己就是门前的人影了。\n那晚有人来取饭，有人借灯修鞋，有人在桌边等一封信。你从来不曾独自撑起这间屋子。它有桂婆婆的灶、周木匠的桌、阿禾的种子、罗伯磨平的竹篮。照片里究竟是谁，也许不如这些名字重要。", "给每一位帮过忙的人留一页", "林先生替你裁好纸。你把自己的名字写在其中一页，大小与其他人一样。", "写下今天没有完成的事情", "账上还有欠着的饭和约定。你没有把它们抹掉，因为故事继续的理由，有时就在这些尚未完成的地方。"]], [["梦醒时的旧屋檐", 0, "梦里的现代梅山有明亮的窗和熟悉的水面。醒来时，你却先伸手摸了摸门边的灯。它还在，油已经不多了。你终于不再把梦当作一张保证能回家的车票。\n桂婆婆来问今天开不开门，你说开。她没有发现这个字对你有多难，只把一把青菜放在桌上，说天气转凉，别再穿湿鞋。\n你想念从前的生活，也珍惜眼前的人，这两件事不必互相抵消。你可以继续找回去的线索，也可以先把这一天过好。屋檐上的雨停了，有人在院外叫你的名字。那声音不是把你困在这里，而是告诉你，此刻确实有人愿意等你应一声。", "把梦里的现代梅山记下来", "你特意标明这是现代记忆，湖面与后来建成的水库不属于眼前的1947年。两个年代在纸上相邻，各有自己的位置。", "先推门，回应来叫你的人", "你答了一声“来了”，又回头把照片放进抽屉。它没有消失，你也不必每时每刻握紧它。"], ["没有地址，也不是白写", 3, "小满已经能把“今天”两个字写得端正。他看你写没有地址的信，问是不是也要折成纸船。你摇头，说这封先留在这里，等知道往哪里送再说。\n信里你写了初到小院那一夜的雨，写过咸的第一锅粥，也写自己有时仍会害怕。你没有装作已经学会一切。收信的人如果能看见，大概更愿意知道你怎样好好吃了一顿饭。\n小满趴在桌边给信画了个歪歪的屋顶。你原本想让他改直，后来把纸按平，让那道线留了下来。往后的日子未必整齐，记忆也不必每一处都修成一样。你把信和旧照片放在一起，抽屉合上时，木头发出轻轻的一声。", "给家人写下自己平安", "你没有写“别担心”就停笔，而是告诉他们今天吃了什么、认识了谁，像平常会发出的那条消息。", "给未来的小院主人留一句话", "你写：“不必一开始就把一切做好，先把灯点起来。”小满说这句话他认得一半，剩下一半明天学。"], ["后记：这一日并非结尾", 1, "早饭后的桌子还没收，阿禾就带着一包新种子来了。她说等下次收成，要试试你答应过的新菜。周木匠在门外敲了两下招牌，罗伯提来补好的篮子，桂婆婆嫌你把茶泡浓了，却还是慢慢喝完。\n有些人仍在路上，没有如约出现。你给他们留着位置，但不把每一个清晨都变成等待。日子需要继续：池边的鱼要照看，鸡舍要添水，菜地里的泥还湿着。\n你在手记末尾写下“明天照常开门”，随后留了许多空白。主线的这一卷到这里合上，村民的话题、未完成的邀约和小院的四季，仍然可以继续。照片不再只是一道谜题；它也可以是一张普通的纪念，记着你曾在这里，认真地生活过。", "继续经营，慢慢完成每个约定", "你把手记放回柜台下面。下一次有人推门，不必是历史的大事，也值得抬头说一句：来，坐一会儿。", "继续寻找回家的线索", "你在空白页写下新的问题，同时照常备好明早的米。寻找来路与珍惜当下，可以一起往前走。"]]];
const TOPICS10=[
[
['灶边日常','为什么总给门边留一只碗？','有时人不好意思说饿。空碗放着，他知道自己能坐下，便不用先欠一句请求。','那我也留一个位置','把门边擦干净，比喊得热闹有用。你忙不过来时，我替你招呼。','要是饭不够怎么办？','照实说，别硬撑。半碗饭也可以分，只要别把自己饿着。',0],
['过去的自己','你年轻时想过什么样的生活？','想认字，想去山外看看。后来事情一件接一件，就搁下了。如今你教我写名字，也不算太晚。','我们明天接着写','先写“家”，再写“信”。等学会了，我要自己给人写一封。','你会觉得遗憾吗？','会啊。可遗憾也能放在心里，和今天的热饭一起过，不必把哪一个扔掉。',3],
['小院的来处','我能把这间屋子改一改吗？','桌凳可以挪，门口的树留着。地暂借你照看，真要大改，咱们先商量。','那先修漏雨的地方','这件最要紧。等天晴，请周木匠来看看，别一个人爬上去。','我想让每个人都坐得舒服','记得矮凳留给孩子，靠墙的位置留给走路不稳的人。',0],
['你与这里','如果有一天我必须走呢？','那就提前说一声，让我给你烙张饼。别怕我难过，难过也比一直猜强。','我会认真道别','那便说好了。知道你平安走出去，也是好事。','我现在还舍不得','舍不得就先住着。留与走，都不必今天就定下来。',6]
],
[
['留种','为什么这包种子不能卖？','这是特意留到下一茬的。今天卖了能多几枚钱，明年要用时却不一定买得回来。','帮你写个留种标签','写大一点，免得我忙糊涂。你自己的种子也分开放。','我们能试着比较收成吗？','挑两小块地，把浇水和天气都记下来。别光凭哪棵看起来好看。',0],
['山间物产','板栗和茶，哪样更像这里？','都像。栗子像忙完活的一顿热饭，茶像坐下来以后才有的闲工夫。','那做栗子粥招待你','少放些糖，尝得到栗子本来的味道就好。','等有空一起喝茶','别又端着杯子站着忙，邀我坐，你自己也得坐。',0],
['小小愿望','攒下钱后最想买什么？','以前想要一匹好布。现在也想给小满买点纸，两件都想要，不算贪心吧？','当然可以，也给自己留一点','那我便记住这句话，下次别嫌我挑布挑太久。','我想帮你实现一个','别替我全包了。陪我慢慢攒，到买下来的那天会更开心。',3],
['关于离开','你会不会怪我一直找回家的路？','怎么会。只是你若找到了，记得让我知道，不要留下空院子叫我猜。','我会告诉你','好。那在找到之前，下一茬种什么，仍然一起商量。','你愿意听听我的家吗？','愿意。那些我没见过的东西，你说慢一点，我会认真听。',6]
],
[
['木头的脾气','新木板为什么要放一放？','太急着用，干湿一变就容易不平。做活不是只看刚做好那一刻，还得想它以后怎么用。','我帮你把板子码好','垫开些，让风能过去。动作慢点，不必逞力气。','小院还有哪里要修？','门边那只凳子先别坐，等我把松动的榫头收紧。',0],
['家里的老人','你娘喜欢什么样的早饭？','温热、软和，她嘴上说随便，萝卜饼若边太硬，便悄悄掰下来给我。','下次给她留软的一份','我替她谢谢你。记住一副牙口，也算把人放在心上。','请她有空来坐坐','等天好些，我扶她过来。靠门那阵风大，坐里头就好。',0],
['手艺与生活','你有做坏过东西吗？','当然。头一张凳子三条腿着地，被我师父笑了很久。现在我还留着，不叫自己忘了。','我第一锅粥也煮坏了','那咱们各有一件不能拿去卖的宝贝。以后谁都别笑谁。','后来怎么练好的？','拆开看哪里错，再做。只在心里懊恼，凳子是不会自己站稳的。',3],
['想留下的东西','如果给小院做一件新家具呢？','我想做张结实的长桌。别只给一个人坐，要能添凳子，来了客人不用急着挪。','桌边刻大家的名字','刻背面吧，吃饭时摸起来平整。名字要留下，也别硌手。','留一个空位给未归的人','能留，但来的人也要招呼。桌子是让人坐的，不是让人只顾着等。',6]
],
[
['纸船','你给纸船起名字吗？','起！这只叫不怕雨，可它昨天就进水了。我想改成晒一晒还行。','这个名字很好','那我送你一只。别放汤碗旁边，它真没那么不怕雨。','教我折一只吧','先对齐角，慢一点。你看，我也有能教大人的事情！',0],
['学堂','今天认得了什么新字？','信。林先生说人说过的话要可信，写给远方的话也叫信。','写给我看看','要是歪了你别笑。我先写在小纸片上，好了再贴到你的本子里。','有想写给谁的话吗？','有。给我娘写，今天我没有去河边深水的地方，让她别担心。',0],
['怕与勇敢','你也会害怕吗？','会。天黑路上没人，我会故意把脚步踩响，装作还有人一起走。','下次可以叫上我','那我也给你照路。不能总是你陪我，我什么都不做。','我小时候也这样','原来大人不是一下就长大的啊。那我可以再慢一点。',3],
['未来','长大想做什么？','想会写很多字，替不会写的人写信。可我也想开船，两个能一起做吗？','可以先把今天的字学好','那今天再学两个。你不能一转身就忘了答应听我念。','我也还在找答案','那我们一起找。等我有了新主意，先来告诉你。',6]
],
[
['地方与年代','为什么同一片山河会有不同名字？','名称会随年代和行政变化而改。记录时最好写明时间，免得后来的人把几个时代混作一处。','我会把推测和事实分开','这是很好的习惯。尤其你听来的事，最好也记下是谁说的。','可以帮我核对手记吗？','可以。不过别因为我识字，就把每句话都当作定论。人也会记错。',0],
['文字','怎样才算把一个人写活？','先别急着写他勇敢或善良。记他怎样把碗递给别人，怎样在门外犹豫，再让读的人自己看见。','那我写今天的早餐','写清楚谁坐在哪里、谁没吃完。小事常比大词更接近人。','我怕写得不好','先写下来。修句子可以晚些，错过的声音却不一定再听得到。',0],
['没有答案的问题','知道结局，会让人更从容吗？','未必。知道远处有一座山，不等于知道眼前每一步该踩在哪里。','那就先顾好今天','这不是放弃长远，是让长远有东西可以站住。','我总怕自己的选择做错','允许自己问、改、再做。别把一次选择当作整个人的判词。',3],
['你的愿望','你最想留下什么书？','不是一本只写英雄的书。我想记下这村里的人怎样在难处里互相照看，连争执也写进去。','我把手记借给你','你愿意给别人看的部分就好。私人的话，不必为了完整都交出来。','争执也值得写吗？','当然。人不是从不生气才值得记住，而是生气以后还愿意想办法相处。',6]
],
[
['竹器','篮边为什么磨得这么细？','路远，肩上磨一点，走久了就是伤。做东西的人若肯多费一道工，用的人就少受一点罪。','让我试着磨一段','顺着竹纹。别比快，先看手指放在哪里。','这个篮子能借我送饭吗？','借你。回来不用像新的一样，只要用完洗净晾干。',0],
['旧水壶','为什么拿旧水壶来养花？','它还能盛水，便不必只放着给人看。过去留下的东西，也可以接着过今天的日子。','这比收在柜里好','各有各的好。我这人闲不住，水壶大概也随我。','给它换些干净的水','好，根别碰断。花不认得水壶以前走过多少路，只认得今天的水。',0],
['不想说的事','如果有些回忆不愿意讲呢？','那就不讲。听故事的人也得懂这个道理，不能因为好奇，就要别人把伤口翻出来。','我尊重你的决定','你能这么说，我反而自在些。来，看看这片竹篾选得好不好。','那讲一件开心的吧','有一回刚吃过饭又赶上乡亲留饭，大伙儿谁也舍不得说自己饱了。人穷，心却热。',3],
['留在村里','如今最想做好什么？','把手艺教给愿意学的人，把年轻人做事的劲儿护着，别光拿当年的事压他们。','我愿意慢慢学','那先从收好工具开始。肯收尾，比一上来会说更要紧。','你也帮了我很多','互相的。你那口热饭，也不是凭空冒出来的。',6]
],
[
['赶路','路上最惦记什么？','刚开始惦记早点到，走久了就惦记同行的人都在。歇脚时数一数，心才安稳。','这儿可以先坐一会儿','能坐片刻就很好。凳子不必给我最好的，能放稳就行。','我替你添点温水','谢谢。水别装太满，路上容易晃出来。',0],
['这顿饭','为什么一定按价付钱？','你买粮也要花钱。乡亲肯帮忙，我们更不能把人家的日子当成不用算的账。','那收下这份普通招待','好。添水和歇脚的情，我一样记得。','我会量力准备补给','这样最好。能长久做下去，比一回把粮袋倒空更有用。',0],
['想家的时候','你会想起家里什么声音？','吃饭前摆碗的声音。很小，可一听就知道有人在等。不赶路的时候，我想慢慢吃一顿。','以后有机会回来吃','我记着这块招牌。若能再来，便先喊一声老板。','我也想念家里的饭桌','那今天先坐下一起吃几口。想家不必一个人忍着。',3],
['没说出口的愿望','除了安定，还有什么小愿望？','想有一件不磨肩的衣裳，想把欠家里的信补上。说出来很小，却总没做完。','愿你有慢慢做完的一天','借你吉言。也愿你找到自己的路，不必一直皱着眉看那张照片。','我可以借你纸笔','好。私人的话我自己写，写坏了你可别拿去给别人看。',6]
],
[
['歇脚','你为什么总先照看别人？','习惯先看哪里有人需要。可习惯也会让人忘了自己累，所以你提醒我坐下，并不是多余的。','那这杯茶慢慢喝','你也坐。若你站着忙，我又想起来帮手。','我能替你做一件小事吗？','帮我把干净包布放好，别和用过的混在一起。这件就很有用。',0],
['小小店铺','以后的小店想是什么模样？','窗要开得大些，门口有一张能坐很久的凳子。卖什么还没想好，先想好让人怎样歇脚。','留一个卖热茶的角落','好。茶不必贵，水要干净，杯子要好拿。','给店起个名字吧','暂时不起。我怕起得太满，装不下以后新的念头。',0],
['害怕','遇到害怕的时候怎么往前走？','有时是把该做的事一件件数清，有时是找人说一句我也害怕。总装作不怕，很累。','你可以在这里说','谢谢。我不一定每次都想说，但知道可以说，就不一样了。','我也想学着不逞强','那就从今天按时吃饭开始。很小，却不容易。',3],
['未完成的约定','你还记得一起试菜的约定吗？','记得。好吃的要尝，煮坏的也要尝，不能只挑风光的时候来。','给你留靠窗的位置','我更想坐你旁边，听你把那些新菜的名字一个个讲完。','若很久没能再见呢？','先把各自的日子过好。约定可以留着，不必让它变成每天的难过。',6]
]];
const SOCIAL10=[
{help:'你替桂婆婆把晒干的柴抱进屋，粗细分开码好。她检查过门边的空处，点点头，说下雨时不用再踩着湿地找柴了。',invite:'桂婆婆坐在靠墙的凳子上，先问你吃没吃，才肯动自己的碗。你们从灶火聊到小时候过冬的衣裳，一顿饭吃得很慢。',confide:'她没有劝你立刻高兴，只把热水推近一点：“在这里坐着也行，不说话也行。”',request:['给晚归的人留饭','porridge',1]},
{help:'你和阿禾把种子分进小纸包，一包歪了，她没拆，反而说这样一眼就认得是你包的。忙完她分给你一小包青菜种。',invite:'阿禾绕着院子看了一圈，最后在门槛边坐下，说这里能闻见灶火又能看见天。她问下一茬想种什么，没有替你选。',confide:'“我不一定能替你解决。”她说，“但你不用先想好怎么解决，才来找我。”',request:['赶集路上的菜饼','pancake',1]},
{help:'你替周木匠扶住木板，他慢慢收紧凳腿。活干完以后，两个人轮流坐上去试了试，这回没有谁需要踮着脚维持平衡。',invite:'周木匠带来一小截磨圆的木头，说给你压账本。风把纸吹起来时，你们都没再伸手去追，忽然一起笑了。',confide:'他把刨子放下，认真听完：“一处松了就修一处，别因为一条腿晃，就说整张桌子都没用了。”',request:['给家里老人带软饼','radishcake',1]},
{help:'小满请你听他念今天的字。念错时他偷偷看你的脸，你没有笑，只让他再认一次。最后他在纸角画了你的小院。',invite:'小满把凳子拖得离桌子很近，展示三只新纸船。你们挑了一只放在窗台，约定等下次见面，看谁的折得更稳。',confide:'“我也会这样。”他说完又怕太像安慰大人，补上一句，“真的，不是哄你。”你忍不住笑了一下。',request:['读书后的栗香米粥','chestnutporridge',1]},
{help:'你替林先生理好借出去又还回来的纸册，把折角压平。你们没有把每一处旧痕都抹掉，因为那些痕迹也说明书被人认真翻过。',invite:'林先生带着空册子来，却没有急着写。你们先坐着喝茶，看门口的人来来往往。过了好一会儿，他才说今天已经有可记的事情。',confide:'“你不必把自己写成一个从不犹豫的人。”他合上笔，“愿意面对自己的犹豫，也是一种诚实。”',request:['讲完课的一盏茶','tea',1]},
{help:'你替罗伯把竹篾按粗细放好，听他讲哪根适合编边、哪根容易折。没有立刻学会一个篮子，但终于能认出几处差别。',invite:'罗伯在院里挑了处不挡路的位置坐下，一边修篮边一边听你说话。他不时接一句，话不多，却从没让你觉得自己在白说。',confide:'“过去的路不能替你走今天的。”老人说，“可你若需要一个人听，凳子就在这儿。”',request:['竹匠收工的一碗粥','chestnutporridge',1]},
{help:'你帮小川把空竹筒数清，又把包布晾在背风处。他特意把借还的数量念给你听，两个人逐项核对后，才把册子合上。',invite:'小川只得一会儿空闲，仍认真坐下喝完了水。他记住了你今天试的新菜，临走说下次若能赶上，想点同样的一份。',confide:'“我也没有每一步都想明白。”他说，“不过你今天做的事，我看见了。”他没有替未知的明天作保证。',request:['带上山路的青菜饼','pancake',2]},
{help:'你替青禾把干净包布分类收好，并在她指点下把用过的单独放开。她逐一确认后，才放心坐下来喝了半杯水。',invite:'青禾在窗边坐下，先把肩上的包放到脚边。你们暂时不聊赶路，认真讨论起以后的小店门前要不要种一棵树。',confide:'“我听着。”她说。你讲得断断续续，她也没有替你把话补成一个听起来更勇敢的版本。',request:['歇脚时的一盏温茶','tea',1]}
];

/* V10: chapter reader, persistent choices and authored NPC conversations. */
const NOVEL10=CHAPTERS.map((chapter,c)=>chapter.scenes.flatMap((sc,j)=>[{title:sc[0],text:sc[1],who:[0,4,5,6,7,1][c],choices:[]},(()=>{const b=BRIDGES10[c][j];return {title:b[0],who:b[1],text:b[2],choices:[[b[3],b[4]],[b[5],b[6]]]}})()]));
let novelChapter10=0,novelPage10=0,conversation10=null;
const extrasBefore10=extras;extras=function(){extrasBefore10();if(!s.novel){s.novel={read:{},choices:{},topicSeen:{},days:{},memories:{},tasks:{},responses:{}};for(let c=0;c<=s.chapter;c++)s.novel.read[c]=c<s.chapter?6:Math.min(6,(s.storyRead[c]||0)*2)}for(const k of ['read','choices','topicSeen','days','memories','tasks','responses'])s.novel[k]??={};};
const validBefore10=validState;validState=function(x){if(!validBefore10(x))return false;if(x.novel===undefined)return true;const n=x.novel;if(!n||typeof n!=='object'||Array.isArray(n))return false;const dict=v=>v&&typeof v==='object'&&!Array.isArray(v);return ['read','choices','topicSeen','days','memories','tasks','responses'].every(k=>dict(n[k]))&&Object.values(n.read).every(v=>Number.isInteger(v)&&v>=0&&v<=6)&&Object.values(n.choices).every(v=>v===0||v===1)&&Object.values(n.memories).every(v=>typeof v==='string'&&v.length<1000)&&Object.values(n.days).every(v=>Number.isInteger(v)&&v>=0)&&Object.values(n.responses).every(v=>v===0||v===1)&&Object.values(n.tasks).every(v=>v==='active'||v==='done')};
function portrait10(i,locked=false){return `<span class="npc-art ${locked?'npc-silhouette':''}" style="--npc-x:${(i%4)*100/3}%;--npc-y:${i<4?0:100}%" role="img" aria-label="${locked?'尚未相逢':CAST[i].name+'的肖像'}"></span>`}
CAST.forEach((p,i)=>{p.icon=portrait10(i);if(people[i])people[i].icon=p.icon});
function role10(i){return i===6&&s.chapter===3&&(s.novel.read[3]||0)<3?'来小院歇脚的年轻赶路人':CAST[i].role}
function remember10(i,text){s.novel.memories[CAST[i].id]=text;s.dialogueLog.push('第 '+s.day+' 天 · '+CAST[i].name+'：'+text);s.dialogueLog=s.dialogueLog.slice(-80)}
function paragraphs10(text){return text.split('\n').map(t=>`<p>${safe(t)}</p>`).join('')}
readStory=function(index){openNovel10(s.chapter,index??Math.min(s.novel.read[s.chapter]||0,5))};
function openNovel10(c,n=0){extras();if(!Number.isInteger(c)||c<0||c>s.chapter||!Number.isInteger(n)||n<0||n>5)return;if(n>(s.novel.read[c]||0))n=s.novel.read[c]||0;novelChapter10=c;novelPage10=n;const passage=NOVEL10[c][n],key=c+':'+n,selected=s.novel.choices[key],complete=selected!==undefined;modal(passage.title,`<section class="novel-reader"><header><small>梅山拾光记 · 第 ${c+1} 章</small><b>${CHAPTERS[c].title}</b><span>第 ${n+1} / 6 节</span></header><div class="novel-speaker">${portrait10(passage.who)}<div><small>这一页，与${CAST[passage.who].name}有关</small><p>${safe(CHAPTERS[c].subtitle)}</p></div></div><div class="novel-prose">${paragraphs10(passage.text)}</div>${passage.choices.length?`<div class="story-decision"><small>${complete?'已经留下的选择':'此刻，你想怎样回应？'}</small>${passage.choices.map((v,i)=>`<button class="${selected===i?'chosen':''}" ${complete?'disabled':''} onclick="chooseStory10(${i})">${selected===i?'✓ ':''}${safe(v[0])}</button>`).join('')}${complete?`<p class="choice-echo">${safe(passage.choices[selected][1])}</p>`:''}</div>`:''}<footer><button class="secondary" onclick="openNovel10(${c},${n-1})" ${n===0?'disabled':''}>上一节</button><button class="secondary" onclick="closeModal()">稍后再读</button><button class="primary" onclick="finishStoryPage()" ${passage.choices.length&&!complete?'disabled':''}>${n<5?'翻到下一节 →':'合上这一章'}</button></footer><small class="novel-note">阅读与选择自动保存。选择影响人物回忆和回应，不会因某个答案失去主线。</small></section>`)}
function chooseStory10(choice){const c=novelChapter10,n=novelPage10,key=c+':'+n,p=NOVEL10[c]?.[n];if(c>s.chapter||!p?.choices[choice]||s.novel.choices[key]!==undefined)return;s.novel.choices[key]=choice;remember10(p.who,'那时你选择了「'+p.choices[choice][0]+'」。');save();openNovel10(c,n)}
finishStoryPage=function(){const c=novelChapter10,n=novelPage10,p=NOVEL10[c]?.[n];if(c>s.chapter||!p||n>(s.novel.read[c]||0)||p.choices.length&&s.novel.choices[c+':'+n]===undefined)return;s.novel.read[c]=Math.max(s.novel.read[c]||0,n+1);s.storyRead[c]=Math.min(3,Math.floor(s.novel.read[c]/2));save();if(n<5)openNovel10(c,n+1);else{closeModal();go('journal');toast(c===5?'这一卷故事已经读完，小院生活仍在继续。':'本章已读完。完成生活目标后，便能翻开下一章。')}};
nextChapter=function(){extras();if(s.chapter>=5)return;if((s.novel.read[s.chapter]||0)<6||!CHAPTERS[s.chapter].test()){toast('请读完本章六节，并完成生活目标。');return}s.chapter++;s.storyRead[s.chapter]=0;s.novel.read[s.chapter]=0;save();render();openNovel10(s.chapter,0)};
recap=function(i){openNovel10(i,0)};
showStory=function(){readStory()};
journalView=function(){extras();$('#view').innerHTML=routeHeader('A NOVEL OF SMALL LIVES','把日子写成故事','六章三十六节 · 你留下的选择，村里的人会记得。')+`<section class="novel-cover"><small>正在经历 · 第 ${s.chapter+1} 章</small><h2>${chapterName()}</h2><p>${CHAPTERS[s.chapter].subtitle}</p><p>已读 ${s.novel.read[s.chapter]||0} / 6 节 · ${chapterGoal()}</p><div class="modal-actions"><button class="primary" onclick="readStory()">${s.novel.read[s.chapter]>=6?'重读本章':'接着读故事'}</button><button class="secondary" onclick="nextChapter()" ${s.chapter>=5||(s.novel.read[s.chapter]||0)<6||!CHAPTERS[s.chapter].test()?'disabled':''}>${s.chapter>=5?'自由生活已开放':'翻开下一章'}</button></div></section><h3 class="block-title">故事目录</h3><div class="chapter-list">${CHAPTERS.map((c,i)=>`<button class="chapter-item" ${i>s.chapter?'disabled':''} onclick="openNovel10(${i},0)"><b>第 ${i+1} 章 · ${i>s.chapter?'尚未揭开的故事':c.title}</b><small>${i>s.chapter?'随故事推进解锁':(s.novel.read[i]||0)+' / 6 节 · 可重读'}</small></button>`).join('')}</div>${s.chapter>=4?`<section class="support-card"><h3>这一盏灯，留给谁？</h3><p>每天完成一次互助，选择可随每天的情况改变。</p><button class="secondary" onclick="support('village')">邻里暖饭 · 清粥 × 2</button><button class="secondary" onclick="support('road')">山路补给 · 青菜饼 × 2</button><small>已完成 ${s.supportDone} 次</small></section>`:''}<h3 class="block-title">居民托付</h3><div class="commission-list">${CAST.map((p,i)=>s.novel.tasks[p.id]?`<button class="secondary" onclick="residentRequest10(${i})">${p.name} · ${SOCIAL10[i].request[0]} · ${s.novel.tasks[p.id]==='done'?'已完成':'进行中'}</button>`:'').join('')||'<p>到居民页坐坐，听听他们有没有想请你帮忙的事。</p>'}</div><h3 class="block-title">记住的相逢</h3><div class="dialogue-record">${s.dialogueLog.slice(-16).reverse().map(t=>`<p>${safe(t)}</p>`).join('')||'<p>还没有记录，第一句话可以很简单。</p>'}</div><button class="secondary" onclick="growthTasks10()">查看小院成长任务</button><p class="history-note">故事村落、人物和对白为虚构，借用金寨梅山、史河与大别山的地域背景。1947年到来的是解放军；罗伯的红军经历属于更早时期。现代梅山水库只出现在现代记忆中。</p>`};
function growthTasks10(){modal('小院成长任务',milestones.map(m=>`<p>${safe(m.title)} · ${Math.min(m.value(),m.target)}/${m.target}</p><button class="secondary" onclick="claim('${m.id}');growthTasks10()" ${s.claimed.includes(m.id)||m.value()<m.target?'disabled':''}>${s.claimed.includes(m.id)?'已领取':'领取 '+m.reward+' 铜钱'}</button>`).join(''))}
function allTopics10(i){return CAST[i].topics.map(t=>({category:'初识',question:t[0],answer:t[1],choices:[['我会认真记住',SOCIAL10[i].confide],['谢谢你愿意告诉我','你们又坐了一会儿，把刚才的话留在彼此心里。'+CAST[i].name+'问你今天有没有按时吃饭，话题便自然回到了日常。']],need:0})).concat(TOPICS10[i].map(t=>({category:t[0],question:t[1],answer:t[2],choices:[[t[3],t[4]],[t[5],t[6]]],need:t[7]})))}
friendsView=function(){extras();$('#view').innerHTML=routeHeader('LET US SIT FOR A WHILE','与村里的人，慢慢熟悉','每个人都有自己的往事、日常和未说完的话。每天聊天、帮工或邀约，会逐渐解锁心事。')+`<div class="resident-grid">${CAST.map((p,i)=>{const locked=s.chapter<p.unlock;return `<article class="resident-card">${portrait10(i,locked)}<div><small>${locked?'第 '+(p.unlock+1)+' 章相逢':'亲近度 '+s.friends[i]+' · '+(s.friends[i]>=6?'愿意说心事':s.friends[i]>=3?'渐渐熟悉':'初次相识')}</small><h2>${locked?'尚未相逢':p.name}</h2><p>${locked?'留待故事走到这里，再认识这个人。':role10(i)}</p><button class="primary" onclick="talk(${i})" ${locked?'disabled':''}>${locked?'尚未解锁':'坐下来聊聊'}</button></div></article>`}).join('')}</div>`};
talk=function(i){extras();const p=CAST[i];if(!p||s.chapter<p.unlock)return;currentDialogue=i;conversation10=null;const topics=allTopics10(i),memory=s.novel.memories[p.id];modal(p.name,`<section class="resident-room"><div class="resident-intro">${portrait10(i)}<div><small>${role10(i)}</small><h3>${s.friends[i]>=6?'“来了？今天可以多坐一会儿。”':'“来，坐。今天想聊些什么？”'}</h3><p>${memory?safe(memory):'你们的故事，从一句普通的问候开始。'}</p></div></div><h3>聊一个话题</h3><div class="topic-grid">${topics.map((t,j)=>`<button onclick="chooseDialogue(${i},${j})" ${s.friends[i]<t.need?'disabled':''}><small>${t.category} · ${s.friends[i]<t.need?'亲近度 '+t.need+' 解锁':s.novel.topicSeen[p.id+':'+j]?'聊过，可重温':'新话题'}</small>${safe(t.question)}<b>›</b></button>`).join('')}</div><h3>一起做点什么</h3><div class="social-grid"><button onclick="social10(${i},'help')">帮忙做一件小事</button><button onclick="social10(${i},'invite')">邀请来小院坐坐</button><button onclick="social10(${i},'confide')">聊聊我的心情</button><button onclick="gift(${i})">送一份${names[p.gift]}（有 ${s.inv[p.gift]||0}）</button><button onclick="residentRequest10(${i})">问问有没有托付</button><button onclick="residentMemory10(${i})">翻看相处记录</button></div><p class="story-note">每日首次聊天 +1 亲近度；帮工 +1，邀约 +1。话题可以反复阅读，重复操作不会反复领取奖励。所有对话均为编写的分支故事，可离线玩。</p></section>`)};
chooseDialogue=function(i,j){const p=CAST[i],t=allTopics10(i)[j];if(currentDialogue!==i||!p||s.chapter<p.unlock||!t||s.friends[i]<t.need)return;const key=p.id+':'+j;conversation10={i,j};if(!s.novel.topicSeen[key]){s.novel.topicSeen[key]=true;s.rep++}if(s.friendDays['talk'+i]!==s.day){s.friendDays['talk'+i]=s.day;s.friends[i]++;s.actions=Math.min(6,s.actions+1)}if(!s.met.includes(p.id))s.met.push(p.id);remember10(i,'你问过「'+t.question+'」。');save();render();modal(p.name,`<div class="resident-intro">${portrait10(i)}<div><small>你问：${safe(t.question)}</small><p class="npc-reply">${safe(t.answer)}</p></div></div><div class="reply-options">${t.choices.map((v,k)=>`<button onclick="reply10(${i},${j},${k})">${safe(v[0])} →</button>`).join('')}</div><button class="secondary" onclick="talk(${i})">先聊别的话题</button>`)};
function reply10(i,j,k){if(conversation10?.i!==i||conversation10?.j!==j)return;const t=allTopics10(i)[j],r=t?.choices[k];if(!r)return;conversation10=null;s.novel.responses[CAST[i].id+':'+j]=k;remember10(i,'你回应「'+r[0]+'」。');save();modal(CAST[i].name,`<div class="resident-intro">${portrait10(i)}<div><small>你说：${safe(r[0])}</small><p class="npc-reply">${safe(r[1])}</p></div></div><p class="choice-echo">这次回应已记入相处记录。</p><button class="primary" onclick="talk(${i})">再坐一会儿</button><button class="secondary" onclick="closeModal()">今天先聊到这里</button>`)}
function social10(i,kind){const p=CAST[i];if(!p||s.chapter<p.unlock||!['help','invite','confide'].includes(kind))return;if(kind==='confide'){modal('把心事放一放',`<div class="resident-intro">${portrait10(i)}<p>${safe(SOCIAL10[i].confide)}</p></div><div class="reply-options">${['今天有一点想家','我担心自己做不好','其实今天挺开心的'].map((v,k)=>`<button onclick="mood10(${i},${k})">${v}</button>`).join('')}</div>`);return}const key=p.id+':'+kind;if(s.novel.days[key]===s.day){modal(p.name,`<p>今天已经${kind==='help'?'一起做过这件事':'一起坐过一会儿'}了。明天还可以再约，今天也可以继续聊天。</p><button class="primary" onclick="talk(${i})">聊聊别的</button>`);return}s.novel.days[key]=s.day;s.friends[i]++;s.actions=Math.min(6,s.actions+1);if(kind==='help'){s.money+=3;if(i===1)s.seeds.greens++}remember10(i,kind==='help'?'你帮忙做完了一件小事。':'你邀请对方来小院坐坐。');save();render();modal(p.name,`<div class="resident-intro">${portrait10(i)}<div><p class="npc-reply">${SOCIAL10[i][kind]}</p><small>亲近度 +1${kind==='help'?' · 谢礼 3 铜钱':''}</small></div></div><button class="primary" onclick="talk(${i})">接着说说话</button>`)}
function mood10(i,k){if(!CAST[i]||s.chapter<CAST[i].unlock||![0,1,2].includes(k))return;const mood=['今天有一点想家','担心自己做不好','今天挺开心'][k];remember10(i,'你说自己'+mood+'。');save();modal(CAST[i].name,`<div class="resident-intro">${portrait10(i)}<div><small>你的心情被认真听见了</small><p>${SOCIAL10[i].confide}</p><p>${['你把想念的地方慢慢讲出来，对方没有催你结束。','你们把担心的事情分成今天能做的一件和以后再想的几件。','你们分享了今天最开心的一个瞬间，那件小事于是有了第二个记得的人。'][k]}</p></div></div><button class="primary" onclick="talk(${i})">回到话题</button>`)}
gift=function(i){const p=CAST[i];if(!p||s.chapter<p.unlock)return;if(s.friendDays['gift'+i]===s.day){toast('今天的心意已经送到了，明天再来吧。');return}if(!s.inv[p.gift]){toast('行囊里还没有'+names[p.gift]+'，可以到食铺制作。');return}s.inv[p.gift]--;s.friendDays['gift'+i]=s.day;s.friends[i]+=2;s.rep+=2;remember10(i,'你送来一份'+names[p.gift]+'。');save();render();modal(p.name,`<div class="resident-intro">${portrait10(i)}<p>“谢谢你还记得我喜欢${names[p.gift]}。来，别急着走，坐下说两句。”</p></div><p>亲近度 +2 · 心意 +2</p><button class="primary" onclick="talk(${i})">坐下来聊聊</button>`)};
function residentRequest10(i){const p=CAST[i];if(!p||s.chapter<p.unlock)return;const [title,food,count]=SOCIAL10[i].request,state=s.novel.tasks[p.id];modal(title,`<div class="resident-intro">${portrait10(i)}<div><small>${p.name}的托付</small><p>${state==='done'?'这份心意已经送到了。'+SOCIAL10[i].invite:'“若你方便，我想请你准备'+count+'份'+names[food]+'。不用赶，等你手头宽裕再做。”'}</p></div></div><p>已有 ${s.inv[food]||0} / ${count} · 完成获得 8 铜钱、2 亲近度，每位居民仅奖励一次。</p>${state==='done'?'<button class="secondary" onclick="closeModal()">收好这段记忆</button>':`<button class="primary" onclick="acceptRequest10(${i})">${state==='active'?'交付饭食':'答应下来'}</button><button class="secondary" onclick="talk(${i})">稍后再说</button>`}`)}
function acceptRequest10(i){const p=CAST[i];if(!p||s.chapter<p.unlock)return;const [title,food,count]=SOCIAL10[i].request;if(s.novel.tasks[p.id]==='done')return;if(!s.novel.tasks[p.id]){s.novel.tasks[p.id]='active';save();residentRequest10(i);return}if((s.inv[food]||0)<count){toast('还差'+(count-(s.inv[food]||0))+'份'+names[food]+'。');return}s.inv[food]-=count;s.money+=8;s.friends[i]+=2;s.novel.tasks[p.id]='done';remember10(i,'你完成了托付「'+title+'」。');save();render();residentRequest10(i)}
function residentMemory10(i){if(!CAST[i]||s.chapter<CAST[i].unlock)return;const list=s.dialogueLog.filter(t=>t.includes('· '+CAST[i].name+'：'));modal('与'+CAST[i].name+'的相处记录',`<div class="memory-head">${portrait10(i)}<p>亲近度 ${s.friends[i]} · 对方记得你说过的话</p></div><div class="dialogue-record">${list.slice(-12).reverse().map(t=>`<p>${safe(t)}</p>`).join('')||'<p>还没有记下相处的片刻。</p>'}</div><button class="primary" onclick="talk(${i})">回到对话</button>`)}
const renderBefore10=render;render=function(){renderBefore10();if(page==='home'){const note=document.querySelector('.daily-note');if(note)note.innerHTML=`<small>主线 · 第 ${s.chapter+1} 章 · ${s.novel.read[s.chapter]||0}/6 节</small><p>${safe(CHAPTERS[s.chapter].subtitle)}</p><button onclick="readStory()">${s.novel.read[s.chapter]>=6?'重读这一章':'继续这一页故事'} →</button>`;}};
extras();render();save();

sourceView=function(){modal('单文件离线版','<p>游戏代码、音乐与图片都包含在这个 HTML 文件中。用文本编辑器打开文件即可查看全部源码。</p><p>本地文件存档能力因浏览器而异，建议在设置中定期导出存档。</p>')};
document.querySelector('.title-buttons').setAttribute('aria-busy','false');document.getElementById('bootNote').hidden=true;
/* V12: paced chapters, separate conversations, tangible business goals. */
const baseExtras12=extras;
extras=function(){baseExtras12();if(!s.life12){s.life12={flags:{},projects:[],ledger:[],chat:{},chapterDay:{},legacy:true};if(s.chapter>0||(s.novel.read[0]||0)>2){s.life12.flags={yard:true,shop:true,key:true};for(let i=0;i<s.chapter;i++)s.life12.projects.push(i)}}s.life12.chapterDay[s.chapter]??=s.day;};
const baseNew12=newState;newState=function(){const x=baseNew12();x.life12={flags:{},projects:[],ledger:[],chat:{},chapterDay:{0:1},legacy:false};return x};
const baseValid12=validState;validState=function(x){if(!baseValid12(x))return false;if(!x.life12)return true;const q=x.life12,obj=v=>v&&typeof v==='object'&&!Array.isArray(v);return obj(q)&&obj(q.flags)&&Object.values(q.flags).every(v=>typeof v==='boolean')&&Array.isArray(q.projects)&&q.projects.every(i=>Number.isInteger(i)&&i>=0&&i<6)&&Array.isArray(q.ledger)&&q.ledger.length<=60&&q.ledger.every(r=>obj(r)&&typeof r.label==='string'&&r.label.length<100&&Number.isSafeInteger(r.amount)&&Math.abs(r.amount)<1000000&&Number.isSafeInteger(r.day))&&obj(q.chat)&&Object.values(q.chat).every(a=>Array.isArray(a)&&a.length<=30&&a.every(r=>obj(r)&&['me','npc','scene'].includes(r.who)&&typeof r.text==='string'&&r.text.length<3000))&&obj(q.chapterDay)&&Object.values(q.chapterDay).every(d=>Number.isSafeInteger(d)&&d>=1)};
const PROJECTS12=[['补好灶台与门锁',12,'开张用的铁件、泥料和木工钱。修好后，每份早餐额外收入 +1。'],['添置渡口食盒',24,'让早餐送得更远。完成后，每份早餐再额外收入 +1。'],['搭起栗香储物架',36,'收好栗子与茶罐。完成后，每份早餐再额外收入 +1。'],['修起屋檐下的长凳',48,'给赶路的人留一个座位。完成后，每份早餐再额外收入 +1。'],['购置共用热水炉',60,'互助厨房有了自己的热水。完成后，每份早餐再额外收入 +1。'],['修好小院的招牌',80,'自由经营的长期目标。完成后，每份早餐再额外收入 +1。']];
const TURNOVER12=[21,45,80,120,170,220];
function book12(label,amount){s.life12.ledger.push({day:s.day,label,amount});s.life12.ledger=s.life12.ledger.slice(-60)}
function invest12(){extras();const i=s.chapter,p=PROJECTS12[i];if(s.life12.projects.includes(i))return;if(i===0&&(s.novel.read[0]||0)<3){toast('先读到「钥匙的分量」，再决定修缮。');return}if(s.money<p[1]){toast('还差 '+(p[1]-s.money)+' 铜钱；可接早餐订单或到集市帮工。');return}s.money-=p[1];s.life12.projects.push(i);book12(p[0],-p[1]);commit(p[0]+'已完成，早餐售价永久 +1。');if($('#modal').open)business12()}
const serveBefore12=serve;serve=function(i){const before=s.sold,money=s.money;serveBefore12(i);if(s.sold>before){const bonus=s.life12.projects.length;s.money+=bonus;s.earnings+=bonus;book12('早餐营业收入',s.money-money);save();render();toast('客人收下了早餐，入账 '+(s.money-money)+' 铜钱。')}};
function businessCard12(){const i=s.chapter,p=PROJECTS12[i],done=s.life12.projects.includes(i);return `<section class="business12"><small>本章经营目标 · 钱要花在生活上</small><h3>${p[0]}</h3><p>${p[2]}</p><div class="business-numbers"><span>钱袋 <b>${s.money}</b></span><span>累计营业收入 <b>${s.earnings} / ${TURNOVER12[i]}</b></span></div><button class="primary" onclick="invest12()" ${done?'disabled':''}>${done?'已完成投资':p[1]+' 铜钱 · 确认修缮'}</button><button class="secondary" onclick="business12()">查看经营账本</button><p class="micro">本章要求完成修缮并达到营业收入目标。没有倒计时罚款；钱不够可继续经营，或每日到集市帮工。</p></section>`}
function business12(){modal('小铺账本',businessCard12()+`<h3>最近的收支</h3>${s.life12.ledger.slice(-12).reverse().map(r=>`<p>第 ${r.day} 天 · ${safe(r.label)} <b>${r.amount>=0?'+':''}${r.amount}</b></p>`).join('')||'<p>修缮和营业记录将记在这里。</p>'}<button class="secondary" onclick="closeModal();go('shop')">去集市补货 / 帮工</button>`)}
// A short modern prologue, then exploration starts. It never recites the full chapter.
INTRO.splice(0,INTRO.length,['雨停之前','现代 · 金寨梅山','史河边的旧物摊上，一张照片被风掀起。瓦屋、木门、冒着白汽的小灶——照片背面只写着：天暗了，也给赶路的人留盏灯。\n你刚碰到那行字，身后的车声忽然远了。','✉']);
nextIntro=function(){endIntro()};showIntro=function(){let root=$('#prologue');if(!root){root=document.createElement('section');root.id='prologue';document.body.appendChild(root)}root.hidden=false;root.innerHTML=`<div class="intro-haze"></div><div class="intro-card"><small>序章 · 一张旧照片</small><h1>雨声忽然很近</h1><p>${INTRO[0][2]}</p><button class="primary" onclick="endIntro()">抬起头，看看四周 →</button></div>`};
NOVEL10[0]=[
{title:'车声消失以后',who:0,text:'你醒在一段湿滑的石阶上。刚才还在掌心的手机成了一块冷冰冰的黑屏，街边的招牌、电线和车流，全都不见了。\n远处仍有史河的水声，山却像换了一副模样。你摸了摸口袋：照片还在，钱夹还在，偏偏来时的路不在了。\n“不是走错巷子这么简单。”这个念头让你心口一紧。你不敢马上相信穿越这种事，却已经知道，自己回不到刚才那条街上。先确认眼前的地方，再想怎么办。',choices:[['先辨认周围的痕迹','你蹲下来，看见石阶上的苔痕和一串沾泥的脚印。它们都真实得让人无法用梦解释。'],['先让自己冷静下来','你数着呼吸，把照片压平。至少现在没有受伤，也还有一处能避雨的屋檐。']]},
{title:'掌心里多了一把钥匙',who:0,text:'绕过院门时，一位老人正踮着脚收晾在檐下的布。你替她扶住竹竿，她看了看你湿透的衣袖，转身端来热水。\n她让你叫她桂婆婆。你问起附近的公路，她没听明白；你说想找回家的路，她就把凳子往灶边推了推。\n临走前，她忽然把一把小铁钥匙放进你手里：“东边那间铺子，先替我开开门。雨天闷着，木头容易坏。”\n你还没来得及解释自己只是个过路人，她已经挎上篮子走了。钥匙带着她掌心的温度。怎么刚到一个陌生地方，就被安排了差事？',choices:[['先把钥匙收好，照她说的看看','你把钥匙和照片放在一起。这不是承诺，只是先替一个帮过你的人开一扇门。'],['追问一句：您还会回来吗？','桂婆婆回头笑了：“就在隔壁，还能跑了不成？”你悬着的一口气才慢慢落下来。']]},
{title:'钥匙的分量',who:0,text:'锁舌比想象中轻。门一推开，米香和旧木头的味道迎面而来：一张小桌、几只缺口碗、半袋米，灶边还留着记账的粉笔。\n照片里的小食铺，竟就在眼前。你把两处门框缺口对在一起，手指开始发凉——你真的到了照片里的年月。\n桂婆婆回来时，见你还攥着钥匙，沉默了一会儿。她说老伴走后，自己已经撑不起早市；儿女住得远，这间铺子一直没舍得关。\n“不是要你白受我的屋子。先试着接一阵，赚的钱留你过日子。以后想走，把钥匙还我；愿意留下，这铺子的灶火，就交给你续了。”\n你原以为自己莫名继承了一间店，如今才明白，这是一个老人递来的退路，也是托付。找回去的办法需要时间，而今天，至少要先吃饭。',choices:[['答应试着经营，但保留寻找归路的打算','桂婆婆点头：“惦记家里是应该的。日子也得一顿顿过。”你把钥匙系在衣袋里，决定先补好门锁和灶台。'],['先问清楚要承担哪些开销','她把粉笔递给你：米面要买，锅灶要修，账要自己记。没有地租，也没有催债的人；但这口灶能不能继续热着，要靠你自己。']]},
{title:'一笔真正属于你的开支',who:2,text:'你把十二枚铜钱放在桌上，周木匠拨出买铁件的钱，又给你看了一眼修门的木料。钱袋一下子轻了，门却终于能关严。\n“这下雨天不用拿盆接了。”他试了试桌脚，顺手把那块晃动的木楔压紧。\n你没有突然学会经营。点火时仍会呛到，淘米的水也洒了半盆。只是当第一缕白汽升起来，你终于有了一件知道该怎么继续的事。\n先做一碗清粥，再去看看谁在等早饭。穿越究竟有什么道理，可以晚一点再问。',choices:[['先把第一笔修缮费记到账上','账本第一页歪歪斜斜地写着：修灶、补锁，十二钱。你希望以后翻到这里，还能记得自己是怎样开始的。'],['先洗净碗，把门打开','你擦去门槛上的泥，给自己留了最靠灶台的一只碗。忙起来也不能忘了吃饭。']]},
{title:'第一位付钱的客人',who:1,text:'客人把空碗推回来，认真数了饭钱。你愣了一瞬：这不是教程送来的奖励，也不是屏幕上的数字，是你今天能再买一点米的钱。\n阿禾来取自己的碗，看你盯着钱袋，忍不住笑：“第一回？”你点头。她没有追问你从哪里来，只把几包菜种推到桌边。\n你原本想把心里的疑问一口气说出来，最后只问了句，明天还来不来。\n“来。你开门，我就来。”这句普通的话，忽然让明天有了形状。院后的地已经翻过，种下一点菜，等一夜，或许能长出下一顿饭。',choices:[['留下周转的钱，准备明天的食材','你把零钱分成两堆：一堆补货，一堆留给修缮。钱不多，却第一次能被你安排。'],['把今天记在小本子里','你写下第一位客人的碗底没有剩饭。至于自己的来历，先留一页空白。']]},
{title:'第二个清晨',who:0,text:'你在同一间屋子醒来。没有回到原来的床上，也没有被闹钟叫醒。窗外的鸡叫与昨夜的柴火灰，把侥幸一点点压实。\n菜地里终于有了能收进篮子的青绿。你沿着田埂走了一圈，回头看见钥匙挂在门边，灶上还有等着烧开的水。\n你开始接受一件事：自己真的被留在了另一个年代。可这不是故事的答案，只是一个起点。这里究竟是哪一年？为什么照片会找到你？桂婆婆又为什么愿意把小铺交给一个陌生人？\n你决定先把这一轮生意做好，再去山集和渡口打听。钥匙留在掌心，归路留在心里。',choices:[['带着问题，继续把店开下去','你在手记上写下三个问题，把账本翻到新的一页。能养活自己，才能从容寻找答案。'],['先记住眼前帮过自己的人','桂婆婆、阿禾、周木匠。你把名字写在照片背面的空处。这一次，你不再只是照片外面的过路人。']]}
];
CHAPTERS[0].subtitle='醒来、得到钥匙，再决定接下这口灶';
function gate12(c,n){extras();if(n===0||n<(s.novel.read[c]||0)||c<s.chapter)return {ok:true,text:'可回顾',route:'journal'};let ok=true,text='继续在小院生活',route='home';if(c===0){const f=s.life12.flags;const a=[[true,'','',''],[f.yard,'环顾小院，辨认来路','home','yard'],[f.shop,'拿钥匙查看小铺','home','shop'],[s.life12.projects.includes(0),'到集市花 12 铜钱修灶、补锁','shop',''],[s.sold>=1,'制作并交付第一份早餐','kitchen',''],[s.day>=2&&s.harvests>=1,'度过一夜并收获一次作物','farm','']][n];return {ok:!!a[0],text:a[1],route:a[2],action:a[3]}}
const targets=[null,['river','lin'],['grove','luo'],['trail','chuan'],['','qing'],['','']];
if(n===1){ok=s.actions>=2||s.day>s.life12.chapterDay[c];text='先做两件日常小事，或休息到明天';route='kitchen'}
if(n===2&&targets[c][0]){ok=s.visited.includes(targets[c][0]);text='去地图探访'+(c===1?'史河渡口':c===2?'栗林茶坡':'山路驿棚');route='map'}
if(n===3&&targets[c][1]){ok=s.met.includes(targets[c][1]);text='与'+CAST.find(p=>p.id===targets[c][1]).name+'聊一个日常话题';route='neighbors'}
if(n===4){ok=s.life12.projects.includes(c);text='完成本章修缮：'+PROJECTS12[c][0];route='shop'}
if(n===5){ok=s.earnings>=TURNOVER12[c];text='累计营业收入达到 '+TURNOVER12[c]+' 铜钱';route='kitchen'}return {ok,text,route}}
function investigate12(kind){extras();if(kind==='yard'&&(s.novel.read[0]||0)>=1){s.life12.flags.yard=true;commit('石阶、小院与河声，都不是你记忆中的梅山。新的故事可在手记继续。')}else if(kind==='shop'&&(s.novel.read[0]||0)>=2){s.life12.flags.shop=true;commit('钥匙打开了小铺。照片里的门框缺口，就在眼前。')}else toast('先读完眼前的故事，再来看看。')}
const openBefore12=openNovel10;openNovel10=function(c,n=0){extras();if(c>s.chapter||c<0||n<0||n>5)return;n=Math.min(n,s.novel.read[c]||0);const g=gate12(c,n);if(!g.ok){modal('先去过一会儿日子',`<p>下一节：${safe(NOVEL10[c][n].title)}</p><p>${g.text}</p><button class="primary" onclick="closeModal();go('${g.route}')">去完成这件事</button>`);return}openBefore12(c,n);const el=$('.novel-speaker');if(el)el.innerHTML='<div><small>主线故事 · 你的经历与心声</small><p>一段一段走，不必急着读完。</p></div>';const b=$('.novel-reader footer .primary');if(b)b.textContent='记住这一段 · 回到生活';};
finishStoryPage=function(){const c=novelChapter10,n=novelPage10,p=NOVEL10[c]?.[n];if(c>s.chapter||!p||n>(s.novel.read[c]||0)||!gate12(c,n).ok||p.choices.length&&s.novel.choices[c+':'+n]===undefined)return;s.novel.read[c]=Math.max(s.novel.read[c]||0,n+1);s.storyRead[c]=Math.min(3,Math.floor(s.novel.read[c]/2));if(c===0&&n>=1)s.life12.flags.key=true;save();closeModal();render();toast('这一段已记下。下一段从手记或小院提示继续。')};
const testsBefore12=CHAPTERS.map(c=>c.test);CHAPTERS.forEach((c,i)=>{if(i<5)c.test=()=>testsBefore12[i]()&&s.life12.projects.includes(i)&&s.earnings>=TURNOVER12[i];c.goal+=' · '+PROJECTS12[i][0]+' · 营业收入 '+TURNOVER12[i]+' 钱'});
nextChapter=function(){if(s.chapter>=5)return;if((s.novel.read[s.chapter]||0)<6||!CHAPTERS[s.chapter].test()){toast('本章故事、修缮和营业目标还未全部完成。');return}s.chapter++;s.novel.read[s.chapter]=0;s.storyRead[s.chapter]=0;s.life12.chapterDay[s.chapter]=s.day;s.actions=0;commit('下一章已经开启。准备好了，再从手记翻开。')};
// Eight painted portraits always appear; social access still follows the story.
friendsView=function(){extras();const unlocked=CAST.filter(p=>p.unlock<=s.chapter).length;$('#view').innerHTML=routeHeader('PEOPLE OF MEISHAN','八位相逢，各有一段日子',`共 8 位角色 · 已相识 ${unlocked} 位 · 尚待相逢 ${8-unlocked} 位。居民闲谈与主线阅读分别进行。`)+`<div class="resident-grid roster12">${CAST.map((p,i)=>{const locked=s.chapter<p.unlock;return `<article class="resident-card ${locked?'future12':''}">${portrait10(i)}<div><small>${locked?'第 '+(p.unlock+1)+' 章解锁':'亲近度 '+s.friends[i]}</small><h2>${p.name}</h2><p>${locked?'尚未相逢 · 随主线来到小院':role10(i)}</p><button class="primary" onclick="talk(${i})" ${locked?'disabled':''}>${locked?'等待相逢':'坐下来聊聊'}</button></div></article>`}).join('')}</div>`};
// Conversation is its own small text-game scene, with turn-by-turn history.
const SETTINGS12=['灶边的矮凳','种子摊旁','木工棚前','渡口的石阶','学堂窗下','竹篾堆旁','屋檐下','热水炉旁'];
function addChat12(i,who,text){const id=CAST[i].id;s.life12.chat[id]??=[];s.life12.chat[id].push({who,text});s.life12.chat[id]=s.life12.chat[id].slice(-30)}
let chatChoice12=null;
talk=function(i){extras();const p=CAST[i];if(!p||s.chapter<p.unlock)return;currentDialogue=i;chatChoice12=null;if(!s.life12.chat[p.id]?.length){addChat12(i,'scene','你在'+SETTINGS12[i]+'停下来。'+p.name+'抬头，给你留了一个位置。');addChat12(i,'npc',s.friends[i]>=3?'来了？今天想说点什么？':'来，坐一会儿吧。')}conversationView12(i)};
function conversationView12(i){const p=CAST[i],topics=allTopics10(i);modal('与'+p.name+'闲谈',`<section class="chat12"><div class="chat-person12">${portrait10(i)}<div><small>${SETTINGS12[i]} · 第 ${s.day} 天</small><h3>${p.name}</h3><p>${role10(i)} · 亲近度 ${s.friends[i]}</p></div></div><div class="chat-scroll12" aria-live="polite">${(s.life12.chat[p.id]||[]).slice(-8).map(r=>`<div class="chat-line12 ${r.who}"><small>${r.who==='me'?safe(s.player.name):r.who==='npc'?p.name:'此刻'}</small><p>${safe(r.text)}</p></div>`).join('')}</div>${chatChoice12?`<div class="reply-options">${topics[chatChoice12.j].choices.map((a,k)=>`<button onclick="chatReply12(${i},${chatChoice12.j},${k})">${safe(a[0])}</button>`).join('')}</div>`:`<details class="topics12" open><summary>我想聊……</summary><div class="topic-grid">${topics.map((t,j)=>`<button onclick="chooseDialogue(${i},${j})" ${s.friends[i]<t.need?'disabled':''}><small>${s.friends[i]<t.need?'亲近度 '+t.need+' 解锁':t.category}</small>${safe(t.question)}</button>`).join('')}</div></details>`}<div class="social-grid"><button onclick="social10(${i},'help')">一起帮工</button><button onclick="social10(${i},'invite')">邀来小院</button><button onclick="social10(${i},'confide')">说说心事</button><button onclick="gift(${i})">送${names[p.gift]}</button><button onclick="residentRequest10(${i})">居民托付</button><button onclick="residentMemory10(${i})">相处记录</button></div><button class="secondary" onclick="closeModal()">告别，回到小院</button><p class="micro">闲谈不会自动跳出主线。你的选择和最近对话会保存。</p></section>`);const box=$('.chat-scroll12');if(box)box.scrollTop=box.scrollHeight;}
chooseDialogue=function(i,j){const p=CAST[i],t=allTopics10(i)[j];if(currentDialogue!==i||s.chapter<p.unlock||!t||s.friends[i]<t.need)return;addChat12(i,'me',t.question);addChat12(i,'npc',t.answer);const key=p.id+':'+j;if(!s.novel.topicSeen[key]){s.novel.topicSeen[key]=true;s.rep++}if(s.friendDays['talk'+i]!==s.day){s.friendDays['talk'+i]=s.day;s.friends[i]++;s.actions=Math.min(6,s.actions+1)}if(!s.met.includes(p.id))s.met.push(p.id);remember10(i,'你问过「'+t.question+'」。');chatChoice12={i,j};save();render();conversationView12(i)};
function chatReply12(i,j,k){if(chatChoice12?.i!==i||chatChoice12.j!==j)return;const a=allTopics10(i)[j]?.choices[k];if(!a)return;addChat12(i,'me',a[0]);addChat12(i,'npc',a[1]);s.novel.responses[CAST[i].id+':'+j]=k;remember10(i,'你回应「'+a[0]+'」。');chatChoice12=null;save();conversationView12(i)}
const journalBefore12=journalView;journalView=function(){journalBefore12();$('#view').insertAdjacentHTML('afterbegin',paceCard12());$('#view').insertAdjacentHTML('beforeend',businessCard12())};
function paceCard12(){const n=s.novel.read[s.chapter]||0,g=gate12(s.chapter,Math.min(n,5));return `<section class="pace12"><small>主线与日常，慢慢交替</small><h3>${n>=6?'本章故事已读完':safe(NOVEL10[s.chapter][n].title)}</h3><p>${n>=6?'完成经营目标后，可从手记开启下一章。':g.ok?'新的片段已就绪，想读的时候再点开。':'下一步：'+g.text}</p>${s.chapter===0&&n===1?'<button class="primary" onclick="investigate12(\'yard\')">环顾小院</button>':s.chapter===0&&n===2?'<button class="primary" onclick="investigate12(\'shop\')">拿钥匙查看小铺</button>':''}<button class="secondary" onclick="${n<6&&g.ok?'readStory()':"go('"+g.route+"')"}">${n<6&&g.ok?'读这一段故事':'去看看'}</button></section>`}
const renderBefore12=render;render=function(){renderBefore12();if(page==='home'){const note=$('.daily-note');if(note)note.innerHTML=paceCard12();}if(page==='shop')$('#view').insertAdjacentHTML('beforeend',businessCard12());};
// Three newly composed procedural scores: no imported recordings, samples or songs.
const MUSIC12=[
{id:'morning',name:'史河晨光',desc:'轻柔木琴与拨弦 · 适合种田',bpm:86,wave:'sine',notes:[72,76,79,81,79,76,74,72,67,72,74,76,79,76,74,0,76,79,84,81,79,76,74,72,74,76,79,74,72,69,67,0],bass:[48,53,55,48]},
{id:'market',name:'栗香小集',desc:'轻快拨弦与低音 · 适合营业',bpm:104,wave:'triangle',notes:[67,72,76,72,79,76,74,72,69,74,77,74,81,77,76,74,71,74,79,74,83,79,77,74,72,76,79,76,84,79,76,0],bass:[48,50,55,48]},
{id:'night',name:'灯下归人',desc:'缓慢钟琴与柔和长音 · 适合阅读',bpm:68,wave:'sine',notes:[76,0,79,76,74,0,72,0,69,72,76,0,74,72,67,0,72,0,76,79,81,0,79,76,74,0,72,69,67,0,72,0],bass:[48,45,53,48]}
];
function note12(midi,time,duration,level,type='sine'){if(!midi)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(level,time+.025);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(musicGain);o.start(time);o.stop(time+duration+.04)}
let previewMusic12=false;
beginMusic=function(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(!musicGain){musicGain=audioCtx.createGain();musicGain.connect(audioCtx.destination)}audioCtx.resume();musicGain.gain.value=prefs.volume/100*.18;if(musicTimer)return;let cursor=audioCtx.currentTime+.05,step=0;const tune=MUSIC12.find(t=>t.id===prefs.track)||MUSIC12[0],beat=60/tune.bpm;musicTimer=setInterval(()=>{if(document.hidden||(!running&&!previewMusic12))return;if(cursor<audioCtx.currentTime)cursor=audioCtx.currentTime+.03;while(cursor<audioCtx.currentTime+.25){const n=tune.notes[step%32],root=tune.bass[Math.floor(step/8)%4];note12(n,cursor,beat*1.5,.35,tune.wave);if(step%4===0)note12(root,cursor,beat*3,.22);if(step%2===1)note12(root+[12,19,24][Math.floor(step/2)%3],cursor,beat*.9,.1);step++;cursor+=beat/2}},90)}catch{toast('浏览器未开启音频，其他玩法不受影响。')}};
function changeMusic12(id,preview=false){if(!MUSIC12.some(t=>t.id===id))return;prefs.track=id;previewMusic12=preview;stopMusic();writeLocal(PREFKEY,prefs);if(running||preview)beginMusic();settings()}
function stopPreview12(){previewMusic12=false;stopMusic();if(running)beginMusic()}
const settingsBefore12=settings;settings=function(){settingsBefore12();$('#modalBody').insertAdjacentHTML('beforeend',`<section class="music12"><h3>小院的声音</h3><p>三首为本游戏新编写的合成器曲目，无外部歌曲录音或采样。</p>${MUSIC12.map(t=>`<button class="music-choice12 ${prefs.track===t.id?'selected':''}" onclick="changeMusic12('${t.id}',true)"><b>${t.name}${prefs.track===t.id?' · 已选择':''}</b><small>${t.desc}</small><span>选择并试听</span></button>`).join('')}<button class="secondary" onclick="stopPreview12()">结束试听</button></section>`)};
const closeBefore12=closeModal;closeModal=function(){closeBefore12();if(previewMusic12&&!running){previewMusic12=false;stopMusic()}};
if(!MUSIC12.some(t=>t.id===prefs.track))prefs.track='morning';
// Automatic mode follows screen; desktop preference becomes a compact sidebar on narrow screens.
syncLayout11=function(){document.body.dataset.mode=prefs.mode==='auto'?(innerWidth<800?'phone':'desktop'):prefs.mode};window.addEventListener('resize',syncLayout11);syncLayout11();
extras();render();save();

