function firstWardrobeDoll14(p,only='all'){const q=layerDefaults(p),g=q.gender==='male'?'male':'female';return `<div class="layered-doll original-female14 ${only==='all'?'assembled':''}" data-hair="${q.hairPart}" role="img" aria-label="${WARDROBE[g].label}，${WARDROBE[g].faces[q.facePart]}，${WARDROBE[g].hair[q.hairPart]}，${WARDROBE[g].clothes[q.clothesPart]}">${only==='all'?spriteLayer(g,1,q.hairPart,'hair-back-part'):''}${only==='all'||only==='face'?spriteLayer(g,0,q.facePart,'base-part'):''}${only==='all'||only==='clothes'?spriteLayer(g,2,q.clothesPart,'clothes-part'):''}${only==='all'||only==='hair'?spriteLayer(g,1,q.hairPart,'hair-part'):''}</div>`}
