const prices17=[0,0,0,0,55,32,48,20,95,58,80,35,0,0,0,0,45,38,25,22,75,65,42,38,0,0,24,0,0,30];
const types17=['安眠床','茶桌','衣柜','盆栽','软垫长椅','收纳矮柜','编织地毯','落地灯','花鸟屏风','窗边书桌','储物箱','小圆凳','桃花架','竹编布架'];
