const name17=id=>(id<24?['原木初居','竹影山茶','桃花奶油'][Math.floor(id%12/4)]+' · ':'花窗添趣 · ')+types17[type17(id)];
function default17(){return [{id:0,x:0,y:1},{id:2,x:7,y:0},{id:13,x:4,y:0},{id:3,x:0,y:3},{id:15,x:2,y:0},{id:12,x:0,y:5},{id:1,x:3,y:4},{id:14,x:6,y:5},{id:24,x:0,y:0},{id:25,x:7,y:5},{id:27,x:4,y:6},{id:28,x:7,y:3}]}
function state17(){return s.room17??={owned:prices17.flatMap((p,i)=>p===0?[i]:[]),placed:default17(),pos:{x:5,y:5},care:{},friend:0}}
let edit17=false,selected17=0,busy17=false,token17=0;
function sprite17(id){let x,y,w,h,W,H,key;if(id<24){let i=id%12,col=i%4,row=Math.floor(i/4),xs=id<12?[0,410,755,1060,1448]:[0,424,764,1220,1448],ys=[0,350,690,1086];[x,y,w,h]=[xs[col],ys[row],xs[col+1]-xs[col],ys[row+1]-ys[row]];W=1448;H=1086;key=id<12?'furniture17.png':'furniture-extra17.png'}else{let i=id-24,row=Math.floor(i/3),col=i%3,xs=row?[0,410,1024,1536]:[0,512,1024,1536];[x,y,w,h]=[xs[col],row*512,xs[col+1]-xs[col],512];W=1536;H=1024;key='furniture-decor17.png'}return `<svg viewBox="${x} ${y} ${w} ${h}" aria-hidden="true"><image href="${ASSETS[key]}" width="${W}" height="${H}"/></svg>`}
function blocked17(x,y,ignore=-1){return x<0||x>9||y<0||y>6||state17().placed.some(p=>p.id!==ignore&&type17(p.id)!==6&&y===p.y&&x>=p.x&&x<p.x+2)}
function path17(tx,ty){const start=state17().pos,q=[[start]],seen=new Set([start.x+','+start.y]);while(q.length){const path=q.shift(),a=path.at(-1);if(a.x===tx&&a.y===ty)return path.slice(1);for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const b={x:a.x+dx,y:a.y+dy},key=b.x+','+b.y;if(!seen.has(key)&&!blocked17(b.x,b.y)){seen.add(key);q.push([...path,b])}}}return null}
function room17(){const h=state17();$('#view').innerHTML=`<div class="r17-toolbar"><button onclick="edit17=!edit17;render()">${edit17?'完成布置':'布置小屋'}</button><button onclick="go('furniture')">家具铺</button><button onclick="carpenter17()">找沈青木聊聊</button></div><p class="r17-help">${edit17?'先选下方家具，再点地板摆放。点屋内家具可选中挪动；绿色格子可摆放。':'点地板走动；点茶桌喝茶、床休息、椅子坐下、花架浇水。衣柜可换装。'}</p><div class="r17-room" style="background-image:url('${ASSETS['room17.png']}')"><div class="r17-floor ${edit17?'editing':''}" id="floor17">${Array.from({length:70},(_,i)=>`<button class="r17-cell" style="left:${i%10*10}%;top:${Math.floor(i/10)*100/7}%" aria-label="地板 ${i%10+1},${Math.floor(i/10)+1}" onclick="floorClick17(${i%10},${Math.floor(i/10)})"></button>`).join('')}${h.placed.map(p=>`<button class="r17-item t${type17(p.id)}" style="left:${(p.x+1)*10}%;top:${(p.y+1)*100/7}%;z-index:${type17(p.id)===6?1:20+p.y*3}" aria-label="${name17(p.id)}" onclick="itemClick17(${p.id})">${sprite17(p.id)}</button>`).join('')}<div id="actor17" class="r17-actor" style="left:${(h.pos.x+.5)*10}%;top:${(h.pos.y+1)*100/7}%;z-index:${22+h.pos.y*3}">${avatar(s.player)}<span class="r17-prop"></span><span class="r17-bubble"></span></div></div></div>${edit17?`<section class="r17-inventory"><h3>我的家具 · ${h.owned.length} 件</h3><div class="r17-tools"><button onclick="store17()">收起选中家具</button><button onclick="resetRoom17()">恢复温馨布局</button></div><div class="r17-grid">${h.owned.map(id=>`<button class="${selected17===id?'chosen':''}" onclick="selected17=${id};render()">${sprite17(id)}<span>${name17(id)}</span></button>`).join('')}</div></section>`:''}`}
function floorClick17(x,y){if(busy17)return;if(edit17){const h=state17();if(x>8||blocked17(x,y,selected17)||blocked17(x+1,y,selected17)||(h.pos.y===y&&h.pos.x>=x&&h.pos.x<=x+1)){toast('这里需要留出通道，换一个空位置吧。');return}h.placed=h.placed.filter(p=>p.id!==selected17);h.placed.push({id:selected17,x,y});save();render()}else walk17(x,y)}
async function walk17(x,y,done){const path=path17(x,y);if(!path){toast('这里走不到，先挪开挡路的家具吧。');return}busy17=true;const token=++token17;try{for(const pos of path){if(page!=='room'||token!==token17)return;state17().pos=pos;const a=$('#actor17');if(!a)return;a.classList.add('walking');a.style.left=(pos.x+.5)*10+'%';a.style.top=(pos.y+1)*100/7+'%';a.style.zIndex=22+pos.y*3;await new Promise(r=>setTimeout(r,160))}$('#actor17')?.classList.remove('walking');save();if(done&&page==='room')await done()}finally{busy17=false}}
function itemClick17(id){if(busy17)return;if(edit17){selected17=id;render();return}const p=state17().placed.find(p=>p.id===id),choices=[];for(let y=p.y-1;y<=p.y+1;y++)for(let x=p.x-1;x<=p.x+2;x++){if(blocked17(x,y))continue;const path=path17(x,y);if(path)choices.push({x,y,n:path.length})}choices.sort((a,b)=>a.n-b.n);if(!choices.length){toast('家具旁边没有可到达的位置，请先调整布置。');return}walk17(choices[0].x,choices[0].y,()=>act17(id))}
async function act17(id){const kind=type17(id),h=state17();if(kind===2){openWardrobe(false);return}const actions={0:['sleep','闭上眼睛，听竹叶轻响。',20],1:['tea','捧一杯热茶，慢慢喝。',10],3:['water','叶尖也有了精神。',0],4:['sit','在软垫上歇一会儿。',0],9:['read','翻开旧书，读到一页山村旧事。',0],11:['sit','坐下，给自己一点闲暇。',0],12:['water','给桃花添一点清水。',0]},[action,words,energy]=actions[kind]||['read',kind===7?'灯火映着窗棂，满屋温柔。':'整理小物，留下今天的记忆。',0],a=$('#actor17');if(!a)return;const cup='<svg viewBox="0 0 40 40"><path d="M7 17h24v15H7z" fill="#fff0cc" stroke="#947354" stroke-width="2"/><path d="M31 19c12 0 10 12 0 10M14 12q-5-5 0-10M23 12q-5-5 0-10" fill="none" stroke="#c5a67a" stroke-width="3"/></svg>';a.querySelector('.r17-prop').innerHTML=action==='tea'?cup:action==='water'?'<svg viewBox="0 0 40 40"><path d="M7 14h20v20H7zM27 20l10-7v8l-10 8" fill="#8eae90"/><path d="M34 29l-2 5m6-3-2 5" stroke="#92c9e5" stroke-width="3"/></svg>':action==='read'?'<svg viewBox="0 0 40 40"><path d="M3 8l17 4 17-4v25l-17 3-17-3z" fill="#e9d3a6" stroke="#876846"/><path d="M20 12v24" stroke="#876846"/></svg>':'';a.querySelector('.r17-bubble').textContent=words;a.classList.add('action-'+action);const key=kind===0?'rest':kind===1?'tea':'care';if(h.care[key]!==s.day){h.care[key]=s.day;s.player.energy=Math.min(100,s.player.energy+energy);s.player.xp++;save()}await new Promise(r=>setTimeout(r,2600));if(page==='room')render()}
function store17(){if(busy17)return;state17().placed=state17().placed.filter(p=>p.id!==selected17);save();render()}
function resetRoom17(){modal('恢复布局？','<p>所有已购买家具仍会保留在收纳栏。</p><button onclick="state17().placed=default17();state17().pos={x:5,y:5};save();closeModal();render()">确认恢复</button>')}
function shop17(){const h=state17();$('#view').innerHTML=`<div class="r17-shop-intro"><img src="${ASSETS['carpenter17.png']}" alt="沈青木的像素肖像"><div><small>梅山手作 · 青木家具铺</small><h2>把小屋，住成喜欢的样子。</h2><p>沈青木把刨花扫到一旁：“基础家具给你留好了。再添一张茶桌、一盏暖灯，日子就像个家。”</p><button onclick="carpenter17()">和青木说说话</button><button onclick="go('room')">回家布置</button></div></div><p>钱袋：${s.money} 铜钱 · 购入后永久保留 · 每款限一件</p><div class="r17-grid shop">${prices17.map((price,id)=>`<article>${sprite17(id)}<h3>${name17(id)}</h3><button ${h.owned.includes(id)?'disabled':''} onclick="buy17(${id})">${h.owned.includes(id)?'已拥有':price+' 铜钱 · 购买'}</button></article>`).join('')}</div>`}
function buy17(id){if(!Number.isInteger(id)||id<0||id>=30)return;const h=state17();if(h.owned.includes(id))return;if(s.money<prices17[id]){toast('钱袋还不够，经营食铺、完成订单后再来吧。');return}s.money-=prices17[id];h.owned.push(id);commit('买好了，回小屋就能摆放。')}
function carpenter17(topic=-1){const lines=['“师父周木匠总说，木头也有性子。顺着纹理下刨，做出的桌子才经得住年月。你那间小屋，我想让它陪你住很久。”','“史河边的风吹过来，屋里容易潮。柜子别紧贴墙，给它留一点缝。日子也是，别把自己挤得太满。”','“你问我为什么留在这里？有天收工，看见每家门口都亮着灯，就觉得自己做的桌椅，终于有了去处。”'];modal('沈青木 · 木香里的相逢',`<div class="r17-dialog"><img src="${ASSETS['carpenter17.png']}" alt="沈青木"><div><p>${topic<0?'他放下手里的木尺，笑着给你挪出一张小凳：“来了？想添点什么，还是坐着聊聊？”':lines[topic]}</p>${['问问他的手艺','聊聊小屋与史河','问他为何留在村里'].map((v,i)=>`<button onclick="carpenter17(${i})">${v}</button>`).join('')}<button onclick="closeModal();go('furniture')">看看家具</button></div></div>`);if(topic>=0&&state17().chatDay!==s.day){state17().chatDay=s.day;state17().friend++;save()}}
const previousRender17=render;render=function(){previousRender17();if(page==='room')room17();if(page==='furniture')shop17();if(page==='home')$('#view').insertAdjacentHTML('beforeend','<button class="r17-home" onclick="go(\'room\')">我的小屋 · 布置、喝茶与慢生活 →</button>');if(page==='neighbors'){$('#view').innerHTML=$('#view').innerHTML.replace('八位相逢','九位相逢').replace('共 8 位角色','共 9 位角色');$('#view').insertAdjacentHTML('beforeend',`<section class="r17-shop-intro"><img src="${ASSETS['carpenter17.png']}" alt="沈青木"><div><h3>沈青木</h3><p>木匠学徒 · 家具铺的新朋友</p><button onclick="carpenter17()">坐下聊聊</button></div></section>`)}};
const previousValid17=validState;validState=function(x){if(!previousValid17(x))return false;const h=x.room17;if(!h)return true;const id=v=>Number.isInteger(v)&&v>=0&&v<30,pos=p=>p&&Number.isInteger(p.x)&&p.x>=0&&p.x<=9&&Number.isInteger(p.y)&&p.y>=0&&p.y<=6;return Array.isArray(h.owned)&&h.owned.length<=30&&h.owned.every(id)&&new Set(h.owned).size===h.owned.length&&Array.isArray(h.placed)&&h.placed.length<=30&&h.placed.every(p=>id(p.id)&&h.owned.includes(p.id)&&pos(p)&&p.x<=8)&&new Set(h.placed.map(p=>p.id)).size===h.placed.length&&pos(h.pos)&&h.care&&typeof h.care==='object'&&Object.values(h.care).every(v=>Number.isInteger(v)&&v>=0)};
render();

