const oldSprite18=sprite17;sprite17=function(id){if(id<30)return oldSprite18(id);const i=id-30;return `<svg viewBox="${i%3*512} ${Math.floor(i/3)*512} 512 512" aria-hidden="true"><image href="${ASSETS['furniture18.webp']}" width="1536" height="1024"/></svg>`};
let history18=[],snap18=false,active18=null,drag18=null,suppress18=false;
const stateBefore18=state17;state17=function(){const h=stateBefore18();if(!h.gift18){h.owned=[...new Set([...h.owned,33])];h.gift18=true}return h};
function remember18(){history18.push(JSON.stringify(state17().placed));if(history18.length>30)history18.shift()}
function undo18(){if(!history18.length)return;state17().placed=JSON.parse(history18.pop());save();render()}
function select18(id){selected17=id;render()}
function clamp18(v,min,max){return Math.max(min,Math.min(max,v))}
function position18(x,y){const step=snap18?.25:.01;return {x:clamp18(Math.round(x/step)*step,0,8),y:clamp18(Math.round(y/step)*step,0,6)}}
function put18(id,x,y){const h=state17();if(!h.owned.includes(id))return;remember18();let p=h.placed.find(p=>p.id===id);if(!p){p={id,x:0,y:0};h.placed.push(p)}Object.assign(p,position18(x,y));save();render()}
function adjust18(dx,dy){const p=state17().placed.find(p=>p.id===selected17);if(!p){toast('先点小屋地板放下这件家具。');return}put18(p.id,p.x+dx,p.y+dy)}
function prop18(key,value){const p=state17().placed.find(p=>p.id===selected17);if(!p)return;remember18();p[key]=value;save();render()}
