blocked17=function(x,y,ignore=-1){return x<0||x>9||y<0||y>6||state17().placed.some(p=>p.id!==ignore&&type17(p.id)!==6&&Math.abs(y-p.y)<.48&&x>=p.x-.15&&x<p.x+1.65)};
function roomToolbar18(){const p=state17().placed.find(p=>p.id===selected17);return `<section class="r18-controls"><div><small>正在布置</small><b>${name17(selected17)}</b><span>拖动家具，或选家具后点地板。允许叠放，可用前后层次调整遮挡。</span></div><div class="r18-control-row"><button onclick="adjust18(-.05,0)" aria-label="家具左移">←</button><button onclick="adjust18(0,-.05)" aria-label="家具上移">↑</button><button onclick="adjust18(0,.05)" aria-label="家具下移">↓</button><button onclick="adjust18(.05,0)" aria-label="家具右移">→</button><button onclick="prop18('flip',${!p?.flip})">左右镜像</button><button onclick="prop18('depth',${clamp18((p?.depth||0)+5,-20,50)})">移到前面</button><button onclick="prop18('depth',${clamp18((p?.depth||0)-5,-20,50)})">移到后面</button><button onclick="undo18()" ${history18.length?'':'disabled'}>撤销</button><button onclick="store17()">收纳</button></div><label>大小 <input aria-label="家具大小" type="range" min="0.6" max="1.4" step="0.05" value="${p?.scale||1}" onchange="prop18('scale',+this.value)"></label><label><input type="checkbox" ${snap18?'checked':''} onchange="snap18=this.checked"> 对齐辅助网格</label></section>`}
room17=function(){const h=state17();$('#view').innerHTML=`<div class="r17-toolbar"><button onclick="toggleEdit18()">${edit17?'完成布置':'布置小屋'}</button><button onclick="go('furniture')">家具铺 · 36款</button><button onclick="carpenter17()">找沈青木聊聊</button>${active18?'<button class="r18-end" onclick="finishAction18()">起身 / 结束互动</button>':''}</div><p class="r17-help">${edit17?'手机按住家具拖动；也可以点击选中，再点地板放置。支持微调、叠放、大小、镜像与撤销。':'点床躺下休息，点椅子落座；点地板走动。休息会保持到你选择起身。'}</p>${edit17?roomToolbar18():''}<div class="r17-room" style="background-image:url('${ASSETS['room17.png']}')"><div class="r17-floor ${edit17?'editing':''}" id="floor17">${Array.from({length:70},(_,i)=>`<button class="r17-cell" style="left:${i%10*10}%;top:${Math.floor(i/10)*100/7}%" aria-label="地板 ${i%10+1},${Math.floor(i/10)+1}" onclick="floorClick17(${i%10},${Math.floor(i/10)})"></button>`).join('')}${h.placed.map(p=>`<button data-item18="${p.id}" class="r17-item t${type17(p.id)} ${edit17&&p.id===selected17?'r18-selected':''} ${h.lights18?.[p.id]?'r18-lit':''}" style="left:${(p.x+1)*10}%;top:${(p.y+1)*100/7}%;z-index:${type17(p.id)===6?1:20+p.y*3+(p.depth||0)};--fscale:${p.scale||1};--flip:${p.flip?-1:1}" aria-label="${name17(p.id)}" onclick="itemClick17(${p.id})">${sprite17(p.id)}</button>`).join('')}<div id="actor17" class="r17-actor" style="left:${(h.pos.x+.5)*10}%;top:${(h.pos.y+1)*100/7}%;z-index:${22+h.pos.y*3}">${avatar(s.player)}<span class="r18-blanket"></span><span class="r17-prop"></span><span class="r17-bubble"></span><span class="r18-sleep">z Z</span></div></div></div>${edit17?`<section class="r17-inventory"><h3>家具收纳 · ${h.owned.length} 件</h3><p>选中未摆放的家具，再点小屋地板。现有家具可以直接拖动。</p><div class="r17-tools"><button onclick="resetRoom17()">恢复初始布局</button></div><div class="r17-grid">${h.owned.map(id=>`<button class="${selected17===id?'chosen':''}" onclick="select18(${id})">${sprite17(id)}<span>${name17(id)}</span><small>${h.placed.some(p=>p.id===id)?'已摆放':'在收纳中'}</small></button>`).join('')}</div></section>`:''}`;bindDrag18();if(active18)requestAnimationFrame(pose18)};
function bindDrag18(){const floor=$('#floor17');floor.addEventListener('pointerdown',e=>{if(!edit17||e.button>0)return;const b=e.target.closest('[data-item18]');if(!b)return;e.preventDefault();selected17=+b.dataset.item18;const p=state17().placed.find(p=>p.id===selected17);drag18={id:p.id,x:p.x,y:p.y,startX:e.clientX,startY:e.clientY,element:b,moved:false};floor.setPointerCapture(e.pointerId);b.classList.add('r18-selected')});floor.addEventListener('pointermove',e=>{if(!drag18)return;const r=floor.getBoundingClientRect(),dx=(e.clientX-drag18.startX)/r.width*10,dy=(e.clientY-drag18.startY)/r.height*7;if(Math.abs(dx)+Math.abs(dy)>.04)drag18.moved=true;const q=position18(drag18.x+dx,drag18.y+dy);drag18.next=q;drag18.element.style.left=(q.x+1)*10+'%';drag18.element.style.top=(q.y+1)*100/7+'%'});const end=e=>{if(!drag18)return;const d=drag18;drag18=null;suppress18=true;setTimeout(()=>suppress18=false,100);if(e.type==='pointercancel'){render();return}if(d.moved&&d.next)put18(d.id,d.next.x,d.next.y);else render()};floor.addEventListener('pointerup',end);floor.addEventListener('pointercancel',end);floor.addEventListener('click',e=>{if(!edit17||suppress18||e.target.closest('[data-item18]'))return;const r=floor.getBoundingClientRect();put18(selected17,(e.clientX-r.left)/r.width*10-1,(e.clientY-r.top)/r.height*7-1)})}
floorClick17=function(x,y){if(edit17)return;if(active18){active18=null;render()}if(!busy17)walk17(x,y)};
store17=function(){remember18();state17().placed=state17().placed.filter(p=>p.id!==selected17);save();render()};
resetRoom17=function(){modal('恢复初始布局？','<p>已买家具仍会保留。恢复后也可以撤销。</p><button onclick="remember18();state17().placed=default17();state17().pos={x:5,y:5};save();closeModal();render()">确认恢复</button>')};
itemClick17=function(id){if(suppress18)return;if(edit17){selected17=id;render();return}if(busy17)return;active18=null;const p=state17().placed.find(p=>p.id===id);if(!p)return;const choices=[];for(let y=0;y<7;y++)for(let x=0;x<10;x++){if(blocked17(x,y))continue;const d=Math.hypot(x-(p.x+.5),y-p.y);if(d>2.2)continue;const path=path17(x,y);if(path)choices.push({x,y,n:path.length,d})}choices.sort((a,b)=>a.n-b.n||a.d-b.d);if(!choices.length){toast('家具周围被挡住了。进入布置模式，留一条走近它的小路。');return}walk17(choices[0].x,choices[0].y,()=>act17(id))};
act17=function(id){const kind=type17(id),h=state17();if(kind===2){openWardrobe(false);return}if(kind===7){h.lights18??={};h.lights18[id]=!h.lights18[id];save();render();toast(h.lights18[id]?'小灯亮了，暖光落在木地板上。':'轻轻熄灯。');return}const defs={0:['sleep','枕着山风，盖好被子。',20],1:['tea','端起热茶，轻轻吹一吹。',10],3:['water','水珠顺着叶尖落下来。',0],4:['sit','陷进柔软的坐垫，歇一会儿。',5],6:['sit','坐在地毯上，听窗外的风。',2],9:['read','翻开一页，慢慢读。',0],11:['sit','坐稳小凳，放松双脚。',3],12:['water','给花浇一点水。',0],14:['rock','摇椅轻轻摇，竹叶沙沙响。',5],15:['wash','掬起清水，洗去一点疲惫。',3],16:['groom','对着镜子，理好额前的头发。',0],17:['pet','轻轻摸摸，小猫发出呼噜声。',0],18:['music','摇动手柄，听一段轻柔的曲子。',0],19:['sew','穿针引线，绣一朵小小山茶。',0]};const [action,text,energy]=defs[kind]||['read','把小物收好，再翻一页旧书。',0];active18={id,action,text};const key=kind===0?'rest':kind===1?'tea':'care';if(h.care[key]!==s.day){h.care[key]=s.day;s.player.energy=Math.min(100,s.player.energy+energy);s.player.xp++;save()}if(action==='music')beginMusic();render()};
function pose18(){if(!active18||page!=='room')return;const a=$('#actor17'),item=document.querySelector(`[data-item18="${active18.id}"]`),floor=$('#floor17');if(!a||!item||!floor)return;const {action,text}=active18;const r=item.getBoundingClientRect(),f=floor.getBoundingClientRect();a.className='r17-actor r18-pose r18-'+action;a.style.zIndex=String(Math.ceil(+item.style.zIndex)+2);let w=f.width*.12,x=r.left+r.width*.5,y=r.top+r.height*.84;
if(action==='sleep'){w=r.width*.47;y=r.top+r.height*.2+w*1.5*.85}
else if(['sit','rock'].includes(action)){w=Math.min(f.width*.13,r.width*.68);y=r.top+r.height*.58+w*1.5*.35}
else if(['read','sew','tea','groom'].includes(action)){y=r.bottom+w*.18;x=r.left+r.width*.6}
else{x=r.right-w*.1;y=r.bottom}
a.style.width=w+'px';a.style.left=(x-f.left)+'px';a.style.top=(y-f.top)+'px';a.querySelector('.r17-bubble').textContent=text;const prop=a.querySelector('.r17-prop');const svg=(body)=>`<svg viewBox="0 0 40 40">${body}</svg>`;prop.innerHTML=action==='tea'?svg('<path d="M8 16h23v17H8z" fill="#fff1d5" stroke="#967956" stroke-width="2"/><path d="M31 18c10 0 10 12 0 10M15 12q-4-5 0-10M23 12q-4-5 0-10" fill="none" stroke="#c8b28e" stroke-width="2"/>'):action==='water'?svg('<path d="M6 15h20v20H6zM26 19l11-6v8l-11 8" fill="#96b391"/><path d="M34 29l-3 7m7-5-2 6" stroke="#8ec7e4" stroke-width="3"/>'):['read','sew'].includes(action)?svg('<path d="M3 8l17 4 17-4v25l-17 3-17-3z" fill="#e7d1a0" stroke="#876846"/><path d="M20 12v24" stroke="#876846"/>'):action==='wash'?svg('<path d="M8 12q-12 18 0 18t0-18m17 5q-10 16 0 16t0-16" fill="#b3dce6"/>'):action==='music'?'<span class="r18-notes">♪ ♫</span>':'';}
