document.addEventListener('keydown',e=>{if(page!=='room'||!edit17||e.target.matches('input,textarea,select')||$('#modal').open)return;const d={ArrowLeft:[-.05,0],ArrowRight:[.05,0],ArrowUp:[0,-.05],ArrowDown:[0,.05]};if(d[e.key]){e.preventDefault();adjust18(...d[e.key])}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();undo18()}});
