validState=function(x){if(!previousValid17(x))return false;const h=x.room17;if(!h)return true;const id=v=>Number.isInteger(v)&&v>=0&&v<36,finite=v=>typeof v==='number'&&Number.isFinite(v),pos=p=>p&&finite(p.x)&&p.x>=0&&p.x<=9&&finite(p.y)&&p.y>=0&&p.y<=6;return Array.isArray(h.owned)&&h.owned.length<=36&&h.owned.every(id)&&new Set(h.owned).size===h.owned.length&&Array.isArray(h.placed)&&h.placed.length<=36&&h.placed.every(p=>id(p.id)&&h.owned.includes(p.id)&&pos(p)&&p.x<=8&&(p.scale===undefined||finite(p.scale)&&p.scale>=.6&&p.scale<=1.4)&&(p.depth===undefined||finite(p.depth)&&p.depth>=-20&&p.depth<=50)&&(p.flip===undefined||typeof p.flip==='boolean'))&&new Set(h.placed.map(p=>p.id)).size===h.placed.length&&pos(h.pos)&&h.care&&typeof h.care==='object'&&Object.values(h.care).every(v=>Number.isInteger(v)&&v>=0)};
