shop17=function(){const h=state17(),set=sets18[shopSet18];$('#view').innerHTML=`<div class="r17-shop-intro"><img src="${ASSETS['carpenter17.png']}" alt="沈青木"><div><small>梅山手作 · 青木家具铺</small><h2>一套风格，二十件家的小事。</h2><p>三套风格各有20件家具与装饰。茶盘、画框可以自由叠放在桌柜旁；地毯可垫在家具下。</p><button onclick="carpenter17()">与青木聊聊</button><button onclick="go('room')">回家布置</button></div></div><div class="r17-toolbar">${sets18.map((s,i)=>`<button aria-pressed="${shopSet18===i}" onclick="shopSet18=${i};render()">${s.name} · 20件</button>`).join('')}</div><p>钱袋 ${s.money} 铜钱 · 当前系列 ${h.owned.filter(id=>set.ids.includes(id)).length} / 20 件</p><div class="r17-grid shop">${set.ids.map(id=>`<article>${sprite17(id)}<h3>${label18(id)}</h3><button ${h.owned.includes(id)?'disabled':''} onclick="buy17(${id})">${h.owned.includes(id)?'已拥有':prices17[id]+' 铜钱 · 购买'}</button></article>`).join('')}</div>`};
const roomBeforeSets18=room17;room17=function(){roomBeforeSets18();$('#view').innerHTML=$('#view').innerHTML.replace('家具铺 · 36款','家具铺 · 三套共60件');document.querySelectorAll('[data-item18]').forEach(el=>{const id=+el.dataset.item18;el.setAttribute('aria-label',label18(id));if(id>=36){el.classList.add('r18-decor','decor-'+(id-36)%8);if((id-36)%8===6)el.style.zIndex='1'}});if(edit17){const b=$('.r18-controls b');if(b)b.textContent=label18(selected17);document.querySelectorAll('.r17-inventory .r17-grid button').forEach((el,i)=>{const span=el.querySelector('span');if(span)span.textContent=label18(state17().owned[i])})}bindDrag18();if(active18)requestAnimationFrame(pose18)};
