buy17=function(id){if(!Number.isInteger(id)||id<0||id>=60)return;const h=state17();if(h.owned.includes(id))return;if(s.money<prices17[id]){toast('钱袋还不够，完成一些订单再来吧。');return}s.money-=prices17[id];h.owned.push(id);commit('新家具已收好，回小屋自由摆放吧。')};
const validBeforeSets18=validState;validState=function(x){if(!x?.room17)return validBeforeSets18(x);const h=x.room17;const clone={...x,room17:undefined};if(!previousValid17(clone))return false;const id=v=>Number.isInteger(v)&&v>=0&&v<60,num=v=>typeof v==='number'&&Number.isFinite(v),pos=p=>p&&num(p.x)&&p.x>=0&&p.x<=9&&num(p.y)&&p.y>=0&&p.y<=6;return Array.isArray(h.owned)&&h.owned.length<=60&&h.owned.every(id)&&new Set(h.owned).size===h.owned.length&&Array.isArray(h.placed)&&h.placed.length<=60&&h.placed.every(p=>id(p.id)&&h.owned.includes(p.id)&&pos(p)&&p.x<=8&&(p.scale===undefined||num(p.scale)&&p.scale>=.6&&p.scale<=1.4)&&(p.depth===undefined||num(p.depth)&&p.depth>=-20&&p.depth<=50)&&(p.flip===undefined||typeof p.flip==='boolean'))&&new Set(h.placed.map(p=>p.id)).size===h.placed.length&&pos(h.pos)&&h.care&&typeof h.care==='object'&&Object.values(h.care).every(v=>Number.isInteger(v)&&v>=0)};
